 bits,\n        symbols,\n    );\n  }\n}\n"
runtimeSource "web-data-strategies" = "// Native fast-check generation and shrinking for instantiated Core schemas.\nimport * as fc from 'fast-check';\nimport * as ls from './lawspec_runtime.mjs';\nimport {RefinementViolation} from './lawspec_schema.mjs';\n\n// fast-check has no empty arbitrary: an always-false filter would loop forever.\n// A native factory may ignore this argument, but drawing it must fail promptly.\nclass EmptyArgumentArbitrary extends fc.Arbitrary {\n  constructor(type, budget) {\n    super();\n    this.type = type;\n    this.budget = budget;\n  }\n\n  generate() {\n    throw new RangeError(\n        `no native generator argument for ${JSON.stringify(this.type)} ` +\n        `within node budget ${this.budget}`,\n    );\n  }\n\n  canShrinkWithoutContext() {\n    return false;\n  }\n\n  shrink() {\n    return fc.Stream.nil();\n  }\n}\n\n// Preserve the underlying Value and shrink context while bounding rejection.\nclass ContractArbitrary extends fc.Arbitrary {\n  constructor(source, accepts, attempts, name) {\n    super();\n    this.source = source;\n    this.accepts = accepts;\n    this.attempts = attempts;\n    this.name = name;\n  }\n\n  generate(random, bias) {\n    for (let attempt = 0; attempt < this.attempts; ++attempt) {\n      const value = this.source.generate(random, bias);\n      if (this.accepts(value.value)) return value;\n    }\n    throw new RangeError(`constructor generation exhausted for ${this.name}`);\n  }\n\n  canShrinkWithoutContext(value) {\n    return this.source.canShrinkWithoutContext(value) && this.accepts(value);\n  }\n\n  shrink(value, context) {\n    return this.source\n        .shrink(value, context)\n        .filter((candidate) => this.accepts(candidate.value));\n  }\n}\n\nexport function strategy(\n    schema,\n    reference,\n    bits,\n    budget,\n    scalar,\n    symbols = new Map(),\n    witnesses = [],\n    maxAttempts = 1000,\n    nativeGenerators = new Map(),\n    nativeSchema = schema,\n    index = null,\n) {\n  if (!Number.isSafeInteger(budget) || budget < 1) {\n    throw new RangeError('structural node budget must be positive');\n  }\n  if (bits !== 32 && bits !== 64) {\n    throw new RangeError('machineBits must be 32 or 64');\n  }\n  schema.constructors(reference);\n  nativeGenerators = new Map(nativeGenerators);\n  for (const [name, factory] of nativeGenerators) {\n    if (typeof name !== 'string' || typeof factory !== 'function') {\n      throw new TypeError('invalid native generator binding');\n    }\n  }\n  if (!Number.isSafeInteger(maxAttempts) || maxAttempts < 1) {\n    throw new RangeError('constructor attempt budget must be positive');\n  }\n  const seeds = new Map();\n  function remember(type, value) {\n    const constructors = schema.constructors(type);\n    let children = [];\n    if (constructors !== null) {\n      const constructor = constructors.find((item) => item.tag === value.tag);\n      children = constructor.fields.map((field, index) => [\n        field.type,\n        value.fields[index],\n      ]);\n    } else if (type.name === 'List') {\n      children = value.map((child) => [type.args[0], child]);\n    } else if (['Nullable', 'Optional'].includes(type.name) && value.present) {\n      children = [[type.args[0], value.value]];\n    } else if (type.name === 'Maybe' && value.tag === 'Maybe::Just') {\n      children = [[type.args[0], value.fields[0]]];\n    } else if (type.name === 'Either') {\n      children = [\n        [type.args[value.tag === 'Either::Right' ? 1 : 0], value.fields[0]],\n      ];\n    }\n    const cost =\n        1 +\n        children.reduce(\n            (total, [childType, child]) => total + remember(childType, child),\n            0,\n        );\n    const key = JSON.stringify(type);\n    if (!seeds.has(key)) seeds.set(key, []);\n    seeds.get(key).push({cost, value});\n    return cost;\n  }\n  for (const value of witnesses) {\n    remember(reference, schema.validate(reference, value, bits, symbols));\n  }\n  function accepts(type, value) {\n    try {\n      schema.validate(type, value, bits, symbols);\n      return true;\n    } catch (error) {\n      if (error instanceof RefinementViolation) return false;\n      throw error;\n    }\n  }\n  const minima = new Map();\n  const inhabitants = new Map();\n  const arbitraries = new Map();\n  const key = (type, available) => JSON.stringify([type, available]);\n\n  function minimum(type, limit) {\n    const id = key(type, limit);\n    if (minima.has(id)) return minima.get(id);\n    let result = null;\n    for (let cost = 1; cost <= limit; ++cost) {\n      if (inhabited(type, cost)) {\n        result = cost;\n        break;\n      }\n    }\n    minima.set(id, result);\n    return result;\n  }\n\n  function allocation(fields, available) {\n    const costs = [];\n    for (const field of fields) {\n      const cost = minimum(field.type, available);\n      if (cost === null) return null;\n      costs.push(cost);\n      available -= cost;\n    }\n    return costs.map(\n        (cost, index) =>\n            cost +\n            Math.floor(available / costs.length) +\n            Number(index < available % costs.length),\n    );\n  }\n\n  function inhabited(type, available) {\n    if (available < 1) return false;\n    if (nativeGenerators.has(type.name)) return true;\n    const id = key(type, available);\n    if (inhabitants.has(id)) return inhabitants.get(id);\n    const constructors = schema.constructors(type);\n    let result;\n    if (constructors !== null) {\n      result = constructors.some(\n          (item) => allocation(item.fields, available - 1) !== null,\n      );\n    } else if (\n        type.args.length === 0 ||\n        ['List', 'Maybe', 'Nullable', 'Optional'].includes(type.name)\n    ) {\n      result = true;\n    } else if (type.name === 'Either') {\n      result = type.args.some((child) => inhabited(child, available - 1));\n    } else {\n      throw new TypeError(`unsupported generator type: ${type.name}`);\n    }\n    inhabitants.set(id, result);\n    return result;\n  }\n\n  function build(type, available) {\n    const id = key(type, available);\n    if (arbitraries.has(id)) return arbitraries.get(id);\n    if (nativeGenerators.has(type.name)) {\n      const children = type.args.map((child) => {\n        const remaining = Math.max(1, available - 1);\n        const source = inhabited(child, remaining)\n          ? build(child, remaining)\n          : new EmptyArgumentArbitrary(child, remaining);\n        return source.map((value) =>\n          nativeSchema.toNative(child, value, bits, symbols));\n      });\n      const source = nativeGenerators.get(type.name)(...children);\n      if (!(source instanceof fc.Arbitrary)) {\n        throw new TypeError(\n            `native generator ${type.name} must return an arbitrary`,\n        );\n      }\n      const result = source.map((value) => {\n        try {\n          return nativeSchema.fromNative(type, value, bits, symbols);\n        } catch (error) {\n          throw new TypeError(\n              `native generator ${type.name}: ${error.message}`,\n              {cause: error},\n          );\n        }\n      });\n      arbitraries.set(id, result);\n      return result;\n    }\n    if (!inhabited(type, available)) {\n      throw new RangeError(\n          `no value of ${type.name} within structural node budget ${available}`,\n      );\n    }\n    const constructors = schema.constructors(type);\n    let result;\n    if (constructors !== null) {\n      const alternatives = [];\n      for (const constructor of constructors) {\n        const costs = allocation(constructor.fields, available - 1);\n        if (costs === null) continue;\n        const children = constructor.fields.map((field, index) =>\n            build(field.type, costs[index]),\n        );\n        const values = fc\n            .tuple(...children)\n            .map((fields) => new ls.DataValue(constructor.tag, fields));\n        alternatives.push(values);\n      }\n      result = fc.oneof({withCrossShrink: true}, ...alternatives);\n    } else if (type.args.length === 0) {\n      result = scalar(type.name).map((value) =>\n          schema.validate(type, value, bits, symbols),\n      );\n    } else if (type.name === 'List') {\n      const remaining = available - 1;\n      const cost = minimum(type.args[0], remaining);\n      const max = cost === null ? 0 : Math.floor(remaining / cost);\n      result = fc.integer({min: 0, max}).chain((length) =>\n          length === 0\n            ? fc.constant([])\n            : fc.array(build(type.args[0], Math.floor(remaining / length)), {\n                minLength: length,\n                maxLength: length,\n              }),\n      );\n    } else if (['Maybe', 'Nullable', 'Optional'].includes(type.name)) {\n      const maybe = type.name === 'Maybe';\n      const absent = fc.constant(\n          maybe\n            ? new ls.DataValue('Maybe::Nothing', [])\n            : new ls.Presence(type.name, false),\n      );\n      result = inhabited(type.args[0], available - 1)\n        ? fc.oneof(\n            {withCrossShrink: true},\n            absent,\n            build(type.args[0], available - 1).map((value) =>\n                maybe\n                  ? new ls.DataValue('Maybe::Just', [value])\n                  : new ls.Presence(type.name, true, value),\n            ),\n          )\n        : absent;\n    } else if (type.name === 'Either') {\n      const tags = ['Either::Left', 'Either::Right'];\n      result = fc.oneof(\n          {withCrossShrink: true},\n          ...type.args.flatMap((child, index) =>\n              inhabited(child, available - 1)\n                ? [\n                    build(child, available - 1).map(\n                        (value) => new ls.DataValue(tags[index], [value]),\n                    ),\n                  ]\n                : [],\n          ),\n      );\n    } else {\n      throw new TypeError(`unsupported generator type: ${type.name}`);\n    }\n    const values = (seeds.get(JSON.stringify(type)) ?? [])\n        .filter((item) => item.cost <= available)\n        .map((item) => item.value);\n    if (values.length) {\n      result = fc.oneof(\n          {withCrossShrink: true},\n          result,\n          fc.constantFrom(...values),\n      );\n    }\n    arbitraries.set(id, result);\n    return result;\n  }\n\n  // Reject complete candidates, not subtrees: an impossible child must not\n  // prevent choosing a viable sibling constructor on the next attempt.\n  const root = index === null\n    ? build(reference, budget)\n    : indexedArbitrary(schema, reference, Number(index[0]), index[1], budget,\n        build, inhabited, (type, value) => accepts(type, value));\n  return new ContractArbitrary(\n      root,\n      (value) => accepts(reference, value),\n      maxAttempts,\n      reference.name,\n  );\n}\n\n// Construct values whose linear structural measure equals target. Each\n// constructor contributes a constant plus the measures of its listed recursive\n// fields, so the target is solved backwards and split across those fields.\n// Samples and shrinks keep the measure; nothing is filtered away.\nfunction indexedArbitrary(\n    schema, reference, target, equations, budget, build, inhabited, accepts) {\n  if (!Number.isSafeInteger(target) || target < 0) {\n    throw new RangeError('index target must be a natural number');\n  }\n  if (schema.constructors(reference) === null) {\n    throw new TypeError('indexed generation requires a data type');\n  }\n  const key = (...parts) => JSON.stringify(parts);\n  const equation = (constructor) => {\n    const found = equations[constructor.tag];\n    if (found === undefined) {\n      throw new TypeError(`missing index equation for ${constructor.tag}`);\n    }\n    return [Number(found[0]), found[1].map(Number)];\n  };\n  const plainFields = (constructor, positions) =>\n    constructor.fields.every((field, index) =>\n      positions.includes(index) || inhabited(field.type, budget));\n  const reachableMemo = new Map();\n  const visiting = new Set();\n  function reachable(type, k) {\n    const id = key(type, k);\n    if (reachableMemo.has(id)) return reachableMemo.get(id);\n    if (visiting.has(id)) return false;\n    visiting.add(id);\n    let result = false;\n    for (const constructor of schema.constructors(type)) {\n      const [constant, positions] = equation(constructor);\n      const rest = k - constant;\n      if (rest < 0 || !plainFields(constructor, positions)) continue;\n      const types = positions.map((position) => constructor.fields[position].type);\n      if (types.length === 0 ? rest === 0 : splittable(types, rest)) {\n        result = true;\n        break;\n      }\n    }\n    visiting.delete(id);\n    reachableMemo.set(id, result);\n    return result;\n  }\n  const splitMemo = new Map();\n  function splittable(types, rest) {\n    if (types.length === 1) return reachable(types[0], rest);\n    const id = key(types, rest);\n    if (splitMemo.has(id)) return splitMemo.get(id);\n    let result = false;\n    for (let first = 0; first <= rest && !result; ++first) {\n      result = reachable(types[0], first) &&\n        splittable(types.slice(1), rest - first);\n    }\n    splitMemo.set(id, result);\n    return result;\n  }\n  function splits(types, rest) {\n    if (types.length === 1) return fc.constant([rest]);\n    return fc.integer({min: 0, max: rest})\n        .filter((first) => reachable(types[0], first) &&\n          splittable(types.slice(1), rest - first))\n        .chain((first) => splits(types.slice(1), rest - first)\n            .map((tail) => [first, ...tail]));\n  }\n  const arbitraries = new Map();\n  function indexed(type, k) {\n    const id = key(type, k);\n    if (arbitraries.has(id)) return arbitraries.get(id);\n    const alternatives = [];\n    for (const constructor of schema.constructors(type)) {\n      const [constant, positions] = equation(constructor);\n      const rest = k - constant;\n      if (rest < 0 || !plainFields(constructor, positions)) continue;\n      const types = positions.map((position) => constructor.fields[position].type);\n      if (!(types.length === 0 ? rest === 0 : splittable(types, rest))) continue;\n      const assemble = (targets) => fc\n          .tuple(...constructor.fields.map((field, index) =>\n            positions.includes(index)\n              ? indexed(field.type, targets[positions.indexOf(index)])\n              : build(field.type, budget)))\n          .map((fields) => new ls.DataValue(constructor.tag, fields));\n      let values = types.length === 0\n        ? assemble([])\n        : splits(types, rest).chain(assemble);\n      if (constructor.predicates && constructor.predicates.length) {\n        values = values.filter((value) => accepts(type, value));\n      }\n      alternatives.push(values);\n    }\n    if (!alternatives.length) {\n      throw new RangeError(`no value of ${type.name} has index ${k}`);\n    }\n    const result = alternatives.length === 1\n      ? alternatives[0]\n      : fc.oneof({withCrossShrink: true}, ...alternatives);\n    arbitraries.set(id, result);\n    return result;\n  }\n  return indexed(reference, target);\n}\n"
runtimeSource "java" = "package lawspec.runtime;\n\nimport java.math.BigDecimal;\nimport java.math.BigInteger;\nimport java.math.RoundingMode;\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Objects;\nimport java.util.Random;\nimport java.util.function.BiFunction;\nimport java.util.function.Function;\nimport java.util.function.Supplier;\n\n/** Portable scalar and collection values, independent of test frameworks. */\npublic final class LawSpecRuntime {\n  private LawSpecRuntime() {}\n\n  public record Value(String type, Object data) {\n    @Override\n    public String toString() {\n      return \"Value[type=\"\n          + type\n          + \", data=\"\n          + (data instanceof int[] units ? Arrays.toString(units) : String.valueOf(data))\n          + \"]\";\n    }\n  }\n\n  public record Complex(double real, double imaginary) {}\n\n  public record SymbolValue(String description) {}\n\n  public record Presence(boolean present, Value value) {}\n\n  public sealed interface Maybe<T> permits Nothing, Just {}\n\n  public record Nothing<T>() implements Maybe<T> {}\n\n  public record Just<T>(T value) implements Maybe<T> {}\n\n  public sealed interface Either<L, R> permits Left, Right {}\n\n  public record Left<L, R>(L value) implements Either<L, R> {}\n\n  public record Right<L, R>(R value) implements Either<L, R> {}\n\n  public record Data(String tag, List<Value> fields) {\n    public Data {\n      fields = List.copyOf(fields);\n    }\n  }\n\n  public record Ratio(BigInteger n, BigInteger d) {\n    public Ratio {\n      if (d.signum() == 0) throw new ArithmeticException(\"exact division by zero\");\n      if (d.signum() < 0) {\n        n = n.negate();\n        d = d.negate();\n      }\n      var gcd = n.gcd(d);\n      n = n.divide(gcd);\n      d = d.divide(gcd);\n    }\n  }\n\n  public static boolean integerType(String t) {\n    return t.matches(\"(U?Int(8|16|32|64|Size)|UIntPtr|BigU?Int|Integer)\");\n  }\n\n  public static boolean exactType(String t) {\n    return integerType(t) || t.equals(\"Decimal\") || t.equals(\"Rational\");\n  }\n\n  public static Value integer(String t, String n) {\n    return new Value(t, new BigInteger(n));\n  }\n\n  public static Value decimal(String c, String e) {\n    return new Value(\n        \"Decimal\", new BigDecimal(new BigInteger(c), Math.negateExact(Integer.parseInt(e))));\n  }\n\n  public static Value rational(String n, String d) {\n    return new Value(\"Rational\", new Ratio(new BigInteger(n), new BigInteger(d)));\n  }\n\n  public static Value bool(boolean b) {\n    return new Value(\"Bool\", b);\n  }\n\n  public static Value floating(String t, String bits) {\n    return new Value(\n        t,\n        t.equals(\"Float32\")\n            ? (double) Float.intBitsToFloat(Integer.parseUnsignedInt(bits, 16))\n            : Double.longBitsToDouble(Long.parseUnsignedLong(bits, 16)));\n  }\n\n  public static Value complex(String t, Value r, Value i) {\n    return new Value(t, new Complex((double) r.data, (double) i.data));\n  }\n\n  public static Value sequence(String t, int[] units) {\n    return new Value(t, Arrays.stream(units).boxed().toList());\n  }\n\n  public static Value character(String t, int c) {\n    return new Value(t, c);\n  }\n\n  public static Value absent(String t) {\n    return new Value(t, null);\n  }\n\n  public static Value present(String t, Value v) {\n    return new Value(t, new Presence(v != null, v));\n  }\n\n  public static Value symbol(String id, String description, Map<String, Object> symbols) {\n    return new Value(\"Symbol\", symbols.computeIfAbsent(id, k -> new SymbolValue(description)));\n  }\n\n  public static Value list(String type, List<Value> values) {\n    if (!type.startsWith(\"List \")) {\n      throw new IllegalArgumentException(\"List type required\");\n    }\n    return new Value(type, List.copyOf(values));\n  }\n\n  private static List<Value> listElements(Value value) {\n    if (value == null\n        || !value.type.startsWith(\"List \")\n        || !(value.data instanceof List<?> values)) {\n      throw new IllegalArgumentException(\"List value required\");\n    }\n    var result = new ArrayList<Value>(values.size());\n    for (Object element : values) {\n      if (!(element instanceof Value field)) {\n        throw new IllegalArgumentException(\"invalid List element representation\");\n      }\n      result.add(field);\n    }\n    return result;\n  }\n\n  public static Value construct(String type, String tag, Value[] fields) {\n    if (sumType(type)) {\n      if (sumFields(type, tag).size() != fields.length) {\n        throw new IllegalArgumentException(\"invalid constructor arity: \" + tag);\n      }\n      return new Value(type, new Data(tag, Arrays.asList(fields)));\n    }\n    if (tag.equals(\"List::Nil\") && fields.length == 0) {\n      return list(type, List.of());\n    }\n    if (tag.equals(\"List::Cons\") && fields.length == 2) {\n      var values = new ArrayList<Value>();\n      values.add(fields[0]);\n      values.addAll(listElements(fields[1]));\n      return list(type, values);\n    }\n    throw new IllegalArgumentException(\"invalid constructor or arity: \" + tag);\n  }\n\n  private static boolean sumType(String type) {\n    return type.startsWith(\"Maybe \") || type.startsWith(\"Either \");\n  }\n\n  private static List<String> eitherArguments(String type) {\n    if (!type.startsWith(\"Either \")) {\n      throw new IllegalArgumentException(\"Either type required\");\n    }\n    var arguments = new ArrayList<String>();\n    int cursor = 7;\n    while (cursor < type.length()) {\n      if (type.charAt(cursor) != '(') {\n        throw new IllegalArgumentException(\"invalid Either type: \" + type);\n      }\n      int start = ++cursor;\n      int depth = 1;\n      while (cursor < type.length() && depth > 0) {\n        char unit = type.charAt(cursor++);\n        if (unit == '(') depth++;\n        if (unit == ')') depth--;\n      }\n      if (depth != 0 || cursor == start + 1) {\n        throw new IllegalArgumentException(\"invalid Either type: \" + type);\n      }\n      arguments.add(type.substring(start, cursor - 1));\n      if (cursor < type.length() && type.charAt(cursor++) != ' ') {\n        throw new IllegalArgumentException(\"invalid Either type: \" + type);\n      }\n    }\n    if (arguments.size() != 2) {\n      throw new IllegalArgumentException(\"Either requires two type arguments\");\n    }\n    return arguments;\n  }\n\n  private static List<String> sumFields(String type, String tag) {\n    if (type.startsWith(\"Maybe \")) {\n      if (tag.equals(\"Maybe::Nothing\")) return List.of();\n      if (tag.equals(\"Maybe::Just\")) return List.of(type.substring(6));\n    } else if (type.startsWith(\"Either \")) {\n      var arguments = eitherArguments(type);\n      if (tag.equals(\"Either::Left\")) return List.of(arguments.get(0));\n      if (tag.equals(\"Either::Right\")) return List.of(arguments.get(1));\n    }\n    throw new IllegalArgumentException(\"invalid constructor \" + tag + \" for \" + type);\n  }\n\n  private static Data dataValue(Value value) {\n    if (value == null\n        || !(value.data instanceof Data data)\n        || sumFields(value.type, data.tag).size() != data.fields.size()) {\n      throw new IllegalArgumentException(\"invalid sum value representation\");\n    }\n    return data;\n  }\n\n  public static <T> Maybe<T> maybeToNative(\n      String type, Value value, int bits, Function<Value, T> element) {\n    if (!type.startsWith(\"Maybe \")) throw new IllegalArgumentException(\"Maybe type required\");\n    var data = dataValue(convert(type, value, bits));\n    return data.tag.equals(\"Maybe::Nothing\")\n        ? new Nothing<>()\n        : new Just<>(element.apply(data.fields.getFirst()));\n  }\n\n  public static <L, R> Either<L, R> eitherToNative(\n      String type, Value value, int bits, Function<Value, L> left, Function<Value, R> right) {\n    if (!type.startsWith(\"Either \")) throw new IllegalArgumentException(\"Either type required\");\n    var data = dataValue(convert(type, value, bits));\n    return data.tag.equals(\"Either::Left\")\n        ? new Left<>(left.apply(data.fields.getFirst()))\n        : new Right<>(right.apply(data.fields.getFirst()));\n  }\n\n  public static Value matchMaybe(\n      Value value, Supplier<Value> nothing, Function<Value, Value> just) {\n    var data = dataValue(value);\n    return switch (data.tag) {\n      case \"Maybe::Nothing\" -> nothing.get();\n      case \"Maybe::Just\" -> just.apply(data.fields.getFirst());\n      default -> throw new IllegalArgumentException(\"Maybe value required\");\n    };\n  }\n\n  public static Value matchEither(\n      Value value, Function<Value, Value> left, Function<Value, Value> right) {\n    var data = dataValue(value);\n    return switch (data.tag) {\n      case \"Either::Left\" -> left.apply(data.fields.getFirst());\n      case \"Either::Right\" -> right.apply(data.fields.getFirst());\n      default -> throw new IllegalArgumentException(\"Either value required\");\n    };\n  }\n\n  public static <T> List<T> listToNative(\n      String type, Value value, int bits, Function<Value, T> element) {\n    var values = listElements(convert(type, value, bits));\n    var result = new ArrayList<T>(values.size());\n    for (Value field : values) {\n      result.add(element.apply(field));\n    }\n    return result;\n  }\n\n  public static Value refineElements(\n      Value value, Function<Value, Value> prepare, Function<Value, Value> predicate) {\n    var accepted = new ArrayList<Value>();\n    for (Value item : listElements(value)) {\n      Value prepared = prepare.apply(item);\n      if (truth(predicate.apply(prepared))) accepted.add(prepared);\n    }\n    return list(value.type, accepted);\n  }\n\n  public static Value allElements(Value value, Function<Value, Value> predicate) {\n    var values = listElements(value);\n    for (int index = 0; index < values.size(); index++) {\n      try {\n        if (!truth(predicate.apply(values.get(index)))) return bool(false);\n      } catch (RuntimeException error) {\n        throw new IllegalArgumentException(\n            \"List element \" + index + \": \" + error.getMessage(), error);\n      }\n    }\n    return bool(true);\n  }\n\n  public static Value matchList(\n      Value value, Supplier<Value> nil, BiFunction<Value, Value, Value> cons) {\n    var values = listElements(value);\n    if (values.isEmpty()) return nil.get();\n    return cons.apply(values.getFirst(), list(value.type, values.subList(1, values.size())));\n  }\n\n  private static Ratio ratio(Value v) {\n    if (integerType(v.type)) return new Ratio((BigInteger) v.data, BigInteger.ONE);\n    if (v.data instanceof Ratio r) return r;\n    if (v.data instanceof BigDecimal d) {\n      int s = d.scale();\n      return new Ratio(\n          s < 0 ? d.unscaledValue().multiply(BigInteger.TEN.pow(-s)) : d.unscaledValue(),\n          s < 0 ? BigInteger.ONE : BigInteger.TEN.pow(s));\n    }\n    throw new IllegalArgumentException(\"exact numeric value required\");\n  }\n\n  private static double real(Value v) {\n    if (v.data instanceof Double d) return d;\n    Ratio r = ratio(v);\n    return new BigDecimal(r.n)\n        .divide(new BigDecimal(r.d), new java.math.MathContext(400, RoundingMode.HALF_EVEN))\n        .doubleValue();\n  }\n\n  private static double precision(String t, double d) {\n    return t.equals(\"Float32\") || t.equals(\"Complex64\") ? (double) (float) d : d;\n  }\n\n  public static Value convert(String t, Value v, int bits) {\n    if (sumType(t)) {\n      var data = dataValue(v);\n      var types = sumFields(t, data.tag);\n      var fields = new ArrayList<Value>();\n      for (int i = 0; i < types.size(); i++) {\n        fields.add(convert(types.get(i), data.fields.get(i), bits));\n      }\n      return new Value(t, new Data(data.tag, fields));\n    }\n    if (t.startsWith(\"List \