Map<>());\n  }\n\n  public boolean equal(Named type, Value left, Value right, int bits, Map<String, Object> symbols) {\n    return equalValidated(\n        validate(type, left, bits, symbols), validate(type, right, bits, symbols));\n  }\n\n  /** A native bridge always validates before decoding and after encoding. */\n  public interface Codec<T> {\n    Named type();\n\n    Value encode(T value);\n\n    T decode(Value value);\n  }\n\n  public <T> Codec<T> codec(\n      Named type, int bits, Function<T, Value> encode, Function<Value, T> decode) {\n    return codec(type, bits, new HashMap<>(), encode, decode);\n  }\n\n  public <T> Codec<T> codec(\n      Named type,\n      int bits,\n      Map<String, Object> symbols,\n      Function<T, Value> encode,\n      Function<Value, T> decode) {\n    checkType(type, 0);\n    if (bits != 32 && bits != 64)\n      throw new IllegalArgumentException(\"machineBits must be 32 or 64\");\n    return new Codec<>() {\n      public Named type() {\n        return type;\n      }\n\n      public Value encode(T value) {\n        return validate(type, encode.apply(value), bits, symbols);\n      }\n\n      public T decode(Value value) {\n        return decode.apply(validate(type, value, bits, symbols));\n      }\n    };\n  }\n\n  public static <T> Value encodeField(Codec<T> codec, T value, String context) {\n    try {\n      return codec.encode(value);\n    } catch (RefinementViolation error) {\n      throw new RefinementViolation(context + \": \" + error.getMessage(), error);\n    } catch (IllegalArgumentException | ArithmeticException | ClassCastException error) {\n      throw new IllegalArgumentException(context + \": \" + error.getMessage(), error);\n    }\n  }\n\n  public <T> Codec<T> scalar(String name, int bits, Class<T> nativeClass) {\n    if (!SCALARS.contains(name)) throw new IllegalArgumentException(\"scalar type required\");\n    return codec(\n        new Named(name),\n        bits,\n        value -> LawSpecRuntime.fromNative(name, nativeClass.cast(value), bits),\n        value -> nativeClass.cast(LawSpecRuntime.toNative(name, value, bits)));\n  }\n\n  public Codec<Value> supported(Named type, int bits) {\n    return supported(type, bits, new HashMap<>());\n  }\n\n  public Codec<Value> supported(Named type, int bits, Map<String, Object> symbols) {\n    return codec(type, bits, symbols, Function.identity(), Function.identity());\n  }\n\n  public <T> Codec<List<T>> list(Codec<T> element, int bits) {\n    return list(element, bits, new HashMap<>());\n  }\n\n  public <T> Codec<List<T>> list(Codec<T> element, int bits, Map<String, Object> symbols) {\n    var type = new Named(\"List\", element.type());\n    return codec(\n        type,\n        bits,\n        symbols,\n        values -> new Value(key(type), values.stream().map(element::encode).toList()),\n        value -> {\n          var values = new ArrayList<T>();\n          for (var item : (List<?>) value.data()) values.add(element.decode((Value) item));\n          return values;\n        });\n  }\n\n  public <T> Codec<LawSpecRuntime.Maybe<T>> maybe(Codec<T> element, int bits) {\n    return maybe(element, bits, new HashMap<>());\n  }\n\n  public <T> Codec<LawSpecRuntime.Maybe<T>> maybe(\n      Codec<T> element, int bits, Map<String, Object> symbols) {\n    var type = new Named(\"Maybe\", element.type());\n    return codec(\n        type,\n        bits,\n        symbols,\n        value ->\n            switch (value) {\n              case LawSpecRuntime.Nothing<T> ignored ->\n                  construct(type, \"Maybe::Nothing\", List.of(), bits, symbols);\n              case LawSpecRuntime.Just<T> just ->\n                  construct(\n                      type, \"Maybe::Just\", List.of(element.encode(just.value())), bits, symbols);\n            },\n        value -> {\n          var data = (Data) value.data();\n          return data.tag().equals(\"Maybe::Nothing\")\n              ? new LawSpecRuntime.Nothing<>()\n              : new LawSpecRuntime.Just<>(element.decode(data.fields().get(0)));\n        });\n  }\n\n  public <L, R> Codec<LawSpecRuntime.Either<L, R>> either(Codec<L> left, Codec<R> right, int bits) {\n    return either(left, right, bits, new HashMap<>());\n  }\n\n  public <L, R> Codec<LawSpecRuntime.Either<L, R>> either(\n      Codec<L> left, Codec<R> right, int bits, Map<String, Object> symbols) {\n    var type = new Named(\"Either\", left.type(), right.type());\n    return codec(\n        type,\n        bits,\n        symbols,\n        value ->\n            switch (value) {\n              case LawSpecRuntime.Left<L, R> item ->\n                  construct(\n                      type, \"Either::Left\", List.of(left.encode(item.value())), bits, symbols);\n              case LawSpecRuntime.Right<L, R> item ->\n                  construct(\n                      type, \"Either::Right\", List.of(right.encode(item.value())), bits, symbols);\n            },\n        value -> {\n          var data = (Data) value.data();\n          return data.tag().equals(\"Either::Left\")\n              ? new LawSpecRuntime.Left<>(left.decode(data.fields().get(0)))\n              : new LawSpecRuntime.Right<>(right.decode(data.fields().get(0)));\n        });\n  }\n\n  private boolean equalValidated(Value left, Value right) {\n    if (left.data() instanceof Data a && right.data() instanceof Data b) {\n      if (!a.tag().equals(b.tag()) || a.fields().size() != b.fields().size()) return false;\n      for (int index = 0; index < a.fields().size(); index++) {\n        if (!equalValidated(a.fields().get(index), b.fields().get(index))) return false;\n      }\n      return true;\n    }\n    if (left.type().startsWith(\"List \")) {\n      var a = (List<?>) left.data();\n      var b = (List<?>) right.data();\n      if (a.size() != b.size()) return false;\n      for (int index = 0; index < a.size(); index++) {\n        if (!equalValidated((Value) a.get(index), (Value) b.get(index))) return false;\n      }\n      return true;\n    }\n    if (left.data() instanceof Presence a && right.data() instanceof Presence b) {\n      return a.present() == b.present() && (!a.present() || equalValidated(a.value(), b.value()));\n    }\n    return LawSpecRuntime.equal(left, right);\n  }\n}\n"
runtimeSource "java-data-strategies" = "package lawspec.testing;\n\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.function.Function;\nimport java.util.function.Predicate;\nimport lawspec.runtime.LawSpecRuntime.Data;\nimport lawspec.runtime.LawSpecRuntime.Presence;\nimport lawspec.runtime.LawSpecRuntime.Value;\nimport lawspec.runtime.LawSpecSchema;\nimport lawspec.runtime.LawSpecSchema.Named;\nimport org.jetbrains.jetCheck.Generator;\nimport org.jetbrains.jetCheck.IntDistribution;\n\n/** Native JetCheck generation and shrinking for the checked data schema. */\npublic final class LawSpecDataStrategies {\n  private LawSpecDataStrategies() {}\n\n  @FunctionalInterface\n  public interface NativeFactory {\n    Generator<Value> create(\n        LawSpecSchema schema,\n        Named type,\n        int bits,\n        Map<String, Object> symbols,\n        List<Generator<Value>> arguments);\n  }\n\n  /** Conversion failures are values at the checked property boundary, even on replay. */\n  private static final class NativeFailure extends IllegalArgumentException {\n    NativeFailure(Named type, RuntimeException cause) {\n      super(\"native generator \" + LawSpecSchema.key(type) + \": \" + cause.getMessage(), cause);\n    }\n  }\n\n  public static <T> Generator<Value> nativeValues(\n      LawSpecSchema.Codec<T> codec, Generator<T> source) {\n    return source.map(\n        value -> {\n          try {\n            return codec.encode(value);\n          } catch (RuntimeException error) {\n            throw new NativeFailure(codec.type(), error);\n          }\n        });\n  }\n\n  public static <T> Generator<T> nativeArguments(\n      LawSpecSchema.Codec<T> codec, Generator<Value> source) {\n    return source.map(\n        value -> {\n          try {\n            return codec.decode(value);\n          } catch (RuntimeException error) {\n            throw new NativeFailure(codec.type(), error);\n          }\n        });\n  }\n\n  public record Captured<T>(T value, RuntimeException error) {\n    public T requireValue() {\n      if (error != null) throw error;\n      return value;\n    }\n  }\n\n  /** Carry native conversion errors across composed draws to the property callback. */\n  public static <T> Generator<Captured<T>> capture(Generator<T> source) {\n    return Generator.from(\n        environment -> {\n          try {\n            return new Captured<>(environment.generate(source), null);\n          } catch (NativeFailure error) {\n            return new Captured<>(null, error);\n          }\n        });\n  }\n\n  public static Generator<Value> generator(\n      LawSpecSchema schema,\n      Named type,\n      int bits,\n      int nodeBudget,\n      Function<String, Generator<Value>> scalar) {\n    return new Builder(schema, bits, scalar).generate(type, nodeBudget);\n  }\n\n  public static Generator<Value> sizedGenerator(\n      LawSpecSchema schema,\n      Named type,\n      int bits,\n      int minimumBudget,\n      Function<String, Generator<Value>> scalar) {\n    var builder = new Builder(schema, bits, scalar);\n    return Generator.from(\n        environment -> {\n          int budget =\n              (int)\n                  Math.min(\n                      Integer.MAX_VALUE,\n                      Math.max(minimumBudget, 4L * environment.getSizeHint() + 1));\n          return environment.generate(builder.generate(type, budget));\n        });\n  }\n\n  /** A rejected predicate is retried; an evaluation error is delivered to the property. */\n  public record Checked(Value value, RuntimeException error) {\n    public Value requireValue() {\n      if (error != null) throw error;\n      return value;\n    }\n  }\n\n  public static Generator<Checked> checkedGenerator(\n      LawSpecSchema schema,\n      Named type,\n      int bits,\n      int minimumBudget,\n      Map<String, Object> symbols,\n      List<Value> witnesses,\n      Function<String, Generator<Value>> scalar) {\n    return checkedGenerator(schema, type, bits, minimumBudget, 100, symbols, witnesses, scalar);\n  }\n\n  public static Generator<Checked> checkedGenerator(\n      LawSpecSchema schema,\n      Named type,\n      int bits,\n      int minimumBudget,\n      int maxAttempts,\n      Map<String, Object> symbols,\n      List<Value> witnesses,\n      Function<String, Generator<Value>> scalar) {\n    return checkedGenerator(\n        schema, type, bits, minimumBudget, maxAttempts, symbols, witnesses, scalar, Map.of());\n  }\n\n  public static Generator<Checked> checkedGenerator(\n      LawSpecSchema schema,\n      Named type,\n      int bits,\n      int minimumBudget,\n      int maxAttempts,\n      Map<String, Object> symbols,\n      List<Value> witnesses,\n      Function<String, Generator<Value>> scalar,\n      Map<String, NativeFactory> factories) {\n    if (maxAttempts < 1) throw new IllegalArgumentException(\"maxAttempts must be positive\");\n    var builder = new Builder(schema, bits, scalar, symbols, maxAttempts, factories);\n    for (var witness : witnesses) {\n      // Invalid witnesses indicate a compiler/caller error, not an empty domain.\n      builder.addWitness(type, schema.validate(type, witness, bits, symbols));\n    }\n    return Generator.from(\n        environment -> {\n          try {\n            int budget =\n                (int)\n                    Math.min(\n                        Integer.MAX_VALUE,\n                        Math.max(minimumBudget, 4L * environment.getSizeHint() + 1));\n            var candidate =\n                builder\n                    .generate(type, budget)\n                    .map(\n                        value -> {\n                          try {\n                            var result = schema.check(type, value, bits, symbols);\n                            if (result instanceof LawSpecSchema.Accepted accepted)\n                              return new Checked(accepted.value(), null);\n                            return new Checked(null, null);\n                          } catch (RuntimeException error) {\n                            return new Checked(null, error);\n                          }\n                        });\n            // JetCheck bounds rejection at 100 attempts and discards invalid replays\n            // while shrinking. Errors remain values so properties report them.\n            return environment.generate(\n                boundedFilter(\n                    candidate,\n                    checked -> checked.value() != null || checked.error() != null,\n                    maxAttempts));\n          } catch (NativeFailure error) {\n            // Do not catch JetCheck's internal replay-control exceptions.\n            return new Checked(null, error);\n          }\n        });\n  }\n\n  private static <T> Generator<T> boundedFilter(\n      Generator<T> source, Predicate<T> predicate, int maxAttempts) {\n    // JetCheck itself caps suchThat at 100 attempts. A smaller LawSpec budget\n    // stops before drawing an additional candidate. This counter is recreated\n    // during replay, so a rejected shrink is still discarded by native suchThat.\n    if (maxAttempts >= 100) return source.suchThat(predicate);\n    return Generator.from(\n        environment -> {\n          int[] attempts = {0};\n          Generator<T> limited =\n              Generator.from(\n                  candidate -> {\n                    if (attempts[0]++ >= maxAttempts)\n                      throw new IllegalArgumentException(\n                          \"constructor generation exhausted \" + maxAttempts + \" attempts\");\n                    return candidate.generate(source);\n                  });\n          return environment.generate(limited.suchThat(predicate));\n        });\n  }\n\n  private static int nodes(Value value) {\n    if (value.data() instanceof Data data)\n      return 1 + data.fields().stream().mapToInt(LawSpecDataStrategies::nodes).sum();\n    if (value.data() instanceof Presence presence)\n      return 1 + (presence.present() ? nodes(presence.value()) : 0);\n    if (value.type().startsWith(\"List \"))\n      return 1 + ((List<?>) value.data()).stream().mapToInt(item -> nodes((Value) item)).sum();\n    return 1;\n  }\n\n  private record Request(Named type, int budget) {}\n\n  private static final class Builder {\n    private final LawSpecSchema schema;\n    private final int bits;\n    private final Function<String, Generator<Value>> scalar;\n    private final boolean unchecked;\n    private final int maxAttempts;\n    private final Map<String, Object> symbols;\n    private final Map<Named, List<Value>> witnesses = new HashMap<>();\n    private final Map<Request, Boolean> inhabited = new HashMap<>();\n    private final Map<Request, Generator<Value>> generators = new HashMap<>();\n    private final Map<String, NativeFactory> factories;\n\n    Builder(LawSpecSchema schema, int bits, Function<String, Generator<Value>> scalar) {\n      this(schema, bits, scalar, null, 100);\n    }\n\n    Builder(\n        LawSpecSchema schema,\n        int bits,\n        Function<String, Generator<Value>> scalar,\n        Map<String, Object> symbols,\n        int maxAttempts) {\n      this(schema, bits, scalar, symbols, maxAttempts, Map.of());\n    }\n\n    Builder(\n        LawSpecSchema schema,\n        int bits,\n        Function<String, Generator<Value>> scalar,\n        Map<String, Object> symbols,\n        int maxAttempts,\n        Map<String, NativeFactory> factories) {\n      boolean unchecked = symbols != null;\n      if (!unchecked && schema.hasContracts())\n        throw new IllegalArgumentException(\"constructor contracts require checked generation\");\n      this.unchecked = unchecked;\n      this.maxAttempts = maxAttempts;\n      this.symbols = symbols;\n      this.schema = schema;\n      this.bits = bits;\n      this.scalar = scalar;\n      this.factories = Map.copyOf(factories);\n    }\n\n    private void addWitness(Named type, Value value) {\n      witnesses.computeIfAbsent(type, ignored -> new ArrayList<>()).add(value);\n      if (schema.isScalar(type)) return;\n      if (type.name().equals(\"List\")) {\n        for (var item : (List<?>) value.data())\n          addWitness((Named) type.arguments().get(0), (Value) item);\n      } else if (type.name().equals(\"Nullable\") || type.name().equals(\"Optional\")) {\n        var presence = (Presence) value.data();\n        if (presence.present()) addWitness((Named) type.arguments().get(0), presence.value());\n      } else {\n        var data = (Data) value.data();\n        var fields = schema.fields(type, data.tag());\n        for (int i = 0; i < fields.size(); i++)\n          addWitness((Named) fields.get(i).type(), data.fields().get(i));\n      }\n    }\n\n    private boolean canGenerate(Named type, int budget) {\n      if (budget < 1) return false;\n      if (factories.containsKey(type.name())) return true;\n      var request = new Request(type, budget);\n      if (inhabited.containsKey(request)) return inhabited.get(request);\n      boolean result;\n      if (schema.isScalar(type)\n          || type.name().equals(\"List\")\n          || type.name().equals(\"Nullable\")\n          || type.name().equals(\"Optional\")) {\n        result = true;\n      } else {\n        result =\n            schema.constructors(type).stream()\n                .anyMatch(tag -> allocation(schema.fields(type, tag), budget - 1) != null);\n      }\n      inhabited.put(request, result);\n      return result;\n    }\n\n    private List<Integer> allocation(List<LawSpecSchema.Field> fields, int budget) {\n      var costs = new ArrayList<Integer>();\n      int remaining = budget;\n      for (var field : fields) {\n        int minimum = 1;\n        while (minimum <= remaining && !canGenerate((Named) field.type(), minimum)) minimum++;\n        if (minimum > remaining) return null;\n        costs.add(minimum);\n        remaining -= minimum;\n      }\n      for (int i = 0; i < costs.size(); i++) {\n        costs.set(\n            i, costs.get(i) + remaining / costs.size() + (i < remaining % costs.size() ? 1 : 0));\n      }\n      return costs;\n    }\n\n    Generator<Value> generate(Named type, int budget) {\n      if (!canGenerate(type, budget)) {\n        throw new IllegalArgumentException(\n            \"no inhabitant of \"\n                + LawSpecSchema.key(type)\n                + \" within structural node budget \"\n                + budget);\n      }\n      var request = new Request(type, budget);\n      if (generators.containsKey(request)) return generators.get(request);\n      if (factories.containsKey(type.name())) {\n        var arguments = new ArrayList<Generator<Value>>();\n        for (var argument : type.arguments()) {\n          int remaining = Math.max(1, budget - 1);\n          // An uninhabited parameter need not be stored by the native type.\n          // JetCheck bounds rejection if its factory actually draws this child.\n          arguments.add(\n              canGenerate((Named) argument, remaining)\n                  ? generate((Named) argument, remaining)\n                  : Generator.constant(new Value(\"Unit\", null)).suchThat(ignored -> false));\n        }\n        var source = factories.get(type.name()).create(schema, type, bits, symbols, arguments);\n        if (source == null) {\n          throw new IllegalArgumentException(\"native generator \" + type.name() + \" returned null\");\n        }\n        var nativeGenerator =\n            source.map(\n                value -> {\n                  try {\n                    return schema.validate(type, value, bits, symbols);\n                  } catch (RuntimeException error) {\n                    throw new NativeFailure(type, error);\n                  }\n                });\n        generators.put(request, nativeGenerator);\n        return nativeGenerator;\n      }\n      Generator<Value> generator;\n      if (schema.isScalar(type)) {\n        generator = scalar.apply(type.name()).map(value -> schema.validate(type, value, bits));\n      } else if (type.name().equals(\"List\")) {\n        var element = (Named) type.arguments().get(0);\n        int maxLength = budget - 1;\n        while (maxLength > 0 && !canGenerate(element, (budget - 1) / maxLength)) maxLength--;\n        generator =\n            Generator.integers(0, maxLength)\n                .flatMap(\n                    length ->\n                        length == 0\n                            ? Generator.constant(new Value(LawSpecSchema.key(type), List.of()))\n                            : Generator.listsOf(\n                                    IntDistribution.uniform(length, length),\n                                    generate(element, (budget - 1) / length))\n                                .map(\n                                    values ->\n                                        new Value(LawSpecSchema.key(type), List.copyOf(values))));\n      } else if (type.name().equals(\"Nullable\") || type.name().equals(\"Optional\")) {\n        var element = (Named) type.arguments().get(0);\n        var absent =\n            Generator.constant(new Value(LawSpecSchema.key(type), new Presence(false, null)));\n        generator =\n            canGenerate(element, budget - 1)\n                ? Generator.anyOf(\n                    absent,\n                    generate(element, budget - 1)\n                        .map(\n                            value -> new Value(LawSpecSchema.key(type), new Presence(true, value))))\n                : absent;\n      } else {\n        var variants = new ArrayList<Generator<Value>>();\n        for (var tag : schema.constructors(type)) {\n          var fields = schema.fields(type, tag);\n          var budgets = allocation(fields, budget - 1);\n          if (budgets == null) continue;\n          var children = new ArrayList<Generator<Value>>();\n          for (int i = 0; i < fields.size(); i++) {\n            children.add(generate((Named) fields.get(i).type(), budgets.get(i)));\n          }\n          variants.add(\n              Generator.from(\n                  environment -> {\n                    var values = new ArrayList<Value>();\n                    for (var child : children) values.add(environment.generate(child));\n                    return unchecked\n                        ? new Value(LawSpecSchema.key(type), new Data(tag, List.copyOf(values)))\n                        : schema.construct(type, tag, values, bits);\n                  }));\n        }\n        generator = Generator.anyOf(variants);\n      }\n      if (witnesses.containsKey(type)) {\n        var seeds = witnesses.get(type).stream().filter(value -> nodes(value) <= budget).toList();\n        if (!seeds.isEmpty()) generator = Generator.anyOf(generator, Generator.sampledFrom(seeds));\n      }\n      if (unchecked && !schema.isScalar(type)) {\n        generator =\n            boundedFilter(\n                generator,\n                value -> {\n                  try {\n                    return schema.check(type, value, bits, symbols)\n                        instanceof LawSpecSchema.Accepted;\n                  } catch (RuntimeException error) {\n                    // Keep evaluation errors for the outer checked result to report.\n                    return true;\n                  }\n                },\n                maxAttempts);\n      }\n      generators.put(request, generator);\n      return generator;\n    }\n  }\n}\n"
runtimeSource "go" = "// Portable scalar arithmetic. No test framework dependencies.\npackage RUNTIME_PACKAGE\n\nimport (\n\t\"fmt\"\n\t\"math\"\n\t\"math/big\"\n\t\"math/rand\"\n\t\"reflect\"\n\t\"strconv\"\n\t\"strings\"\n\t\"unicode/utf8\"\n)\n\ntype LawSpecValue struct {\n\tType string\n\tData any\n}\ntype lawSpecDecimal struct {\n\tcoefficient *big.Int\n\texponent    int\n}\ntype lawSpecSymbol struct{ description string }\ntype lawSpecPresence struct{ value *LawSpecValue }\n\n// Named support types preserve scalar domains in native data fields.\ntype LawSpecDecimal = lawSpecDecimal\ntype LawSpecSymbol = lawSpecSymbol\ntype LawSpecUnit struct{}\ntype LawSpecNull struct{}\ntype LawSpecUndefined struct{}\n\n// Presence is tagged so nested nullable and optional states remain distinct.\ntype LawSpecNullable[T any] struct {\n\tPresent bool\n\tValue   T\n}\n\ntype LawSpecOptional[T any] struct {\n\tPresent bool\n\tValue   T\n}\n\n// LawSpecMaybe keeps algebraic absence separate from nullable payloads.\ntype LawSpecMaybe[T any] struct {\n\tpresent bool\n\tvalue   T\n}\n\nfunc LawSpecNothing[T any]() LawSpecMaybe[T]     { return LawSpecMaybe[T]{} }\nfunc LawSpecJust[T any](value T) LawSpecMaybe[T] { return LawSpecMaybe[T]{true, value} }\nfunc (m LawSpecMaybe[T]) Value() (T, bool)       { return m.value, m.present }\nfunc (m LawSpecMaybe[T]) lawSpecTag() string {\n\tif m.present {\n\t\treturn \"Maybe::Just\"\n\t}\n\treturn \"Maybe::Nothing\"\n}\nfunc (m LawSpecMaybe[T]) lawSpecFields() []any {\n\tif m.present {\n\t\treturn []any{m.value}\n\t}\n\treturn nil\n}\n\n// LawSpecEither has an explicit constructor; its zero value is invalid.\ntype LawSpecEither[L, R any] struct {\n\ttag   uint8\n\tleft  L\n\tright R\n}\n\nfunc LawSpecLeft[L, R any](value L) LawSpecEither[L, R] {\n\treturn LawSpecEither[L, R]{tag: 1, left: value}\n}\nfunc LawSpecRight[L, R any](value R) LawSpecEither[L, R] {\n\treturn LawSpecEither[L, R]{tag: 2, right: value}\n}\nfunc (e LawSpecEither[L, R]) Left() (L, bool)  { return e.left, e.tag == 1 }\nfunc (e LawSpecEither[L, R]) Right() (R, bool) { return e.right, e.tag == 2 }\nfunc (e LawSpecEither[L, R]) lawSpecTag() string {\n\tswitch e.tag {\n\tcase 1:\n\t\treturn \"Either::Left\"\n\tcase 2:\n\t\treturn \"Either::Right\"\n\tdefault:\n\t\tpanic(\"Either requires Left or Right\")\n\t}\n}\nfunc (e LawSpecEither[L, R]) lawSpecFields() []any {\n\tswitch e.tag {\n\tcase 1:\n\t\treturn []any{e.left}\n\tcase 2:\n\t\treturn []any{e.right}\n\tdefault:\n\t\tpanic(\"Either requires Left or Right\")\n\t}\n}\n\ntype lawSpecSum interface {\n\tlawSpecTag() string\n\tlawSpecFields() []any\n}\ntype lawSpecData struct {\n\ttag    string\n\tfields []LawSpecValue\n}\n\nfunc (d lawSpecData) String() string { return fmt.Sprintf(\"%s(%v)\", d.tag, d.fields) }\n\nfunc lsSumType(t string) bool {\n\treturn strings.HasPrefix(t, \"Maybe \") || strings.HasPrefix(t, \"Either \")\n}\nfunc lsEitherArguments(t string) []string {\n\tif !strings.HasPrefix(t, \"Either \") {\n\t\tpanic(\"Either type required\")\n\t}\n\tvar result []string\n\tfor cursor := 7; cursor < len(t); {\n\t\tif t[cursor] != '(' {\n\t\t\tpanic(\"invalid Either type: \" + t)\n\t\t}\n\t\tcursor++\n\t\tstart, depth := cursor, 1\n\t\tfor cursor < len(t) && depth > 0 {\n\t\t\tif t[cursor] == '(' {\n\t\t\t\tdepth++\n\t\t\t}\n\t\t\tif t[cursor] == ')' {\n\t\t\t\tdepth--\n\t\t\t}\n\t\t\tcursor++\n\t\t}\n\t\tif depth != 0 || cursor == start+1 {\n\t\t\tpanic(\"invalid Either type: \" + t)\n\t\t}\n\t\tresult = append(result, t[start:cursor-1])\n\t\tif cursor < len(t) {\n\t\t\tif t[cursor] != ' ' || cursor+1 == len(t) {\n\t\t\t\tpanic(\"invalid Either type: \" + t)\n\t\t\t}\n\t\t\tcursor++\n\t\t}\n\t}\n\tif len(result) != 2 {\n\t\tpanic(\"Either requires two type arguments\")\n\t}\n\treturn result\n}\nfunc lsSumFields(t, tag string) []string {\n\tif strings.HasPrefix(t, \"Maybe \") {\n\t\tswitch tag {\n\t\tcase \"Maybe::Nothing\":\n\t\t\treturn nil\n\t\tcase \"Maybe::Just\":\n\t\t\treturn []string{strings.TrimPrefix(t, \"Maybe \")}\n\t\t}\n\t}\n\tif strings.HasPrefix(t, \"Either \") {\n\t\targuments := lsEitherArguments(t)\n\t\tswitch tag {\n\t\tcase \"Either::Left\":\n\t\t\treturn arguments[:1]\n\t\tcase \"Either::Right\":\n\t\t\treturn arguments[1:]\n\t\t}\n\t}\n\tpanic(\"invalid constructor \" + tag + \" for \" + t)\n}\nfunc lsDataValue(value LawSpecValue) lawSpecData {\n\tdata, ok := value.Data.(lawSpecData)\n\tif !ok || len(lsSumFields(value.Type, data.tag)) != len(data.fields) {\n\t\tpanic(\"invalid sum representation\")\n\t}\n\treturn data\n}\nfunc lsMaybeToNative[T any](t string, value LawSpecValue, bits int, element func(LawSpecValue) T) LawSpecMaybe[T] {\n\tif !strings.HasPrefix(t, \"Maybe \") {\n\t\tpanic(\"Maybe type required\")\n\t}\n\tlsCheckNativeProfile(t, bits)\n\tdata := lsDataValue(lsConvert(t, value, bits))\n\tif data.tag == \"Maybe::Nothing\" {\n\t\treturn LawSpecNothing[T]()\n\t}\n\treturn LawSpecJust(element(data.fields[0]))\n}\nfunc lsEitherToNative[L, R any](t string, value LawSpecValue, bits int, left func(LawSpecValue) L, right func(LawSpecValue) R) LawSpecEither[L, R] {\n\tif !strings.HasPrefix(t, \"Either \") {\n\t\tpanic(\"Either type required\")\n\t}\n\tlsCheckNativeProfile(t, bits)\n\tdata := lsDataValue(lsConvert(t, value, bits))\n\tif data.tag == \"Either::Left\" {\n\t\treturn LawSpecLeft[L, R](left(data.fields[0]))\n\t}\n\treturn LawSpecRight[L, R](right(data.fields[0]))\n}\nfunc lsAllElements(value LawSpecValue, predicate func(LawSpecValue) LawSpecValue) LawSpecValue {\n\tvalues, ok := value.Data.([]LawSpecValue)\n\tif !ok {\n\t\tpanic(\"expected List in element predicate\")\n\t}\n\tindex := 0\n\tdefer func() {\n\t\tif failure := recover(); failure != nil {\n\t\t\tpanic(fmt.Sprintf(\"List element %d: %v\", index, failure))\n\t\t}\n\t}()\n\tfor index = range values {\n\t\tif !lsTruth(predicate(values[index])) {\n\t\t\treturn lsBool(false)\n\t\t}\n\t}\n\treturn lsBool(true)\n}\n\nfunc lsMatchMaybe(value LawSpecValue, nothing func() LawSpecValue, just func(LawSpecValue) LawSpecValue) LawSpecValue {\n\tdata := lsDataValue(value)\n\tswitch data.tag {\n\tcase \"Maybe::Nothing\":\n\t\treturn nothing()\n\tcase \"Maybe::Just\":\n\t\treturn just(data.fields[0])\n\tdefault:\n\t\tpanic(\"Maybe value required\")\n\t}\n}\nfunc lsMatchEither(value LawSpecValue, left, right func(LawSpecValue) LawSpecValue) LawSpecValue {\n\tdata := lsDataValue(value)\n\tswitch data.tag {\n\tcase \"Either::Left\":\n\t\treturn left(data.fields[0])\n\tcase \"Either::Right\":\n\t\treturn right(data.fields[0])\n\tdefault:\n\t\tpanic(\"Either value required\")\n\t}\n}\n\nfunc lsList(t string, values []LawSpecValue) LawSpecValue {\n\treturn LawSpecValue{t, append([]LawSpecValue{}, values...)}\n}\n\nfunc lsConstruct(t, tag string, fields []LawSpecValue) LawSpecValue {\n\tif lsSumType(t) {\n\t\tif len(lsSumFields(t, tag)) != len(fields) {\n\t\t\tpanic(\"invalid constructor arity: \" + tag)\n\t\t}\n\t\treturn LawSpecValue{t, lawSpecData{tag, append([]LawSpecValue{}, fields...)}}\n\t}\n\tswitch tag {\n\tcase \"List::Nil\":\n\t\tif len(fields) == 0 {\n\t\t\treturn lsList(t, nil)\n\t\t}\n\tcase \"List::Cons\":\n\t\tif len(fields) == 2 {\n\t\t\tif tail, ok := fields[1].Data.([]LawSpecValue); ok {\n\t\t\t\treturn lsList(t, append([]LawSpecValue{fields[0]}, tail...))\n\t\t\t}\n\t\t}\n\t}\n\tpanic(\"invalid constructor or arity: \" + tag)\n}\n\nfunc lsSignedInteger(t string, value int64) LawSpecValue {\n\treturn lsInteger(t, strconv.FormatInt(value, 10))\n}\n\nfunc lsUnsignedInteger(t string, value uint64) LawSpecValue {\n\treturn lsInteger(t, strconv.FormatUint(value, 10))\n}\n\nfunc lsListToNative[T any](t string, value LawSpecValue, bits int, element func(LawSpecValue) T) []T {\n\tlsCheckNativeProfile(t, bits)\n\tvalues := lsConvert(t, value, bits).Data.([]LawSpecValue)\n\tresult := make([]T, len(values))\n\tfor index, item := range values {\n\t\tresult[index] = element(item)\n\t}\n\treturn result\n}\n\nfunc lsCheckNativeProfile(t string, bits int) {\n\tif strings.HasPrefix(t, \"List \") || strings.HasPrefix(t, \"Maybe \") {\n\t\tlsCheckNativeProfile(strings.SplitN(t, \" \", 2)[1], bits)\n\t\treturn\n\t}\n\tif strings.HasPrefix(t, \"Either \") {\n\t\tfor _, argument := range lsEitherArguments(t) {\n\t\t\tlsCheckNativeProfile(argument, bits)\n\t\t}\n\t\treturn\n\t}\n\tif (t == \"IntSize\" || t == \"UIntSize\" || t == \"UIntPtr\") && strconv.IntSize != bits {\n\t\tpanic(\"machineBits does not match native architecture\")\n\t}\n}\n\nfunc lsIntegerType(t string) bool {\n\treturn strings.HasPrefix(t, \"Int\") || strings.HasPrefix(t, \"UInt\") || t == \"BigInt\" || t == \"BigUInt\"\n}\nfunc lsExactType(t string) bool { return lsIntegerType(t) || t == \"Decimal\" || t == \"Rational\" }\nfunc lsInt(s string) *big.Int {\n\tn, ok := new(big.Int).SetString(s, 10)\n\tif !ok {\n\t\tpanic(\"invalid integer\")\n\t}\n\treturn n\n}\nfunc lsInteger(t, n string) LawSpecValue { return LawSpecValue{t, lsInt(n)} }\nfunc lsBool(b bool) LawSpecValue         { return LawSpecValue{\"Bool\", b} }\nfunc lsDecimal(c, e string) LawSpecValue {\n\tn, err := strconv.Atoi(e)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn LawSpecValue{\"Decimal\", lawSpecDecimal{lsInt(c), n}}\n}\nfunc lsRational(n, d string) LawSpecValue {\n\treturn LawSpecValue{\"Rational\", new(big.Rat).SetFrac(lsInt(n), lsInt(d))}\n}\nfunc lsFloating(t, b string) LawSpecValue {\n\tn, err := strconv.ParseUint(b, 16, 64)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tv := math.Float64frombits(n)\n\tif t == \"Float32\" {\n\t\tv = float64(math.Float32frombits(uint32(n)))\n\t}\n\treturn LawSpecValue{t, v}\n}\nfunc lsComplex(t string, r, i LawSpecValue) LawSpecValue {\n\treturn LawSpecValue{t, complex(r.Data.(float64), i.Data.(float64))}\n}\nfunc lsSequence(t string, u []int) LawSpecValue        { return LawSpecValue{t, append([]int{}, u...)} }\nfunc lsCharacter(t string, c int) LawSpecValue         { return LawSpecValue{t, c} }\nfunc lsAbsent(t string) LawSpecValue                   { return LawSpecValue{t, nil} }\nfunc lsPresent(t string, v *LawSpecValue) LawSpecValue { return LawSpecValue{t, lawSpecPresence{v}} }\nfunc lsPointer(v LawSpecValue) *LawSpecValue           { return &v }\nfunc lsSymbol(id, d string, symbols map[string]*lawSpecSymbol) LawSpecValue {\n\ts, ok := symbols[id]\n\tif !ok {\n\t\ts = &lawSpecSymbol{d}\n\t\tsymbols[id] = s\n\t}\n\treturn LawSpecValue{\"Symbol\", s}\n}\nfunc lsPow(n int) *big.Int { return new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(n)), nil) }\nfunc lsRatio(v LawSpecValue) *big.Rat {\n\tswitch x := v.Data.(type) {\n\tcase *big.Int:\n\t\treturn new(big.Rat).SetInt(x)\n\tcase *big.Rat:\n\t\treturn new(big.Rat).Set(x)\n\tcase lawSpecDecimal:\n\t\tif x.exponent >= 0 {\n\t\t\treturn new(big.Rat).SetInt(new(big.Int).Mul(x.coefficient, lsPow(x.exponent)))\n\t\t}\n\t\treturn new(big.Rat).SetFrac(x.coefficient, lsPow(-x.exponent))\n\tcase float64:\n\t\tr := new(big.Rat).SetFloat64(x)\n\t\tif r == nil {\n\t\t\tpanic(\"non-finite exact conversion\")\n\t\t}\n\t\treturn r\n\tdefault:\n\t\tpanic(\"exact numeric value required\")\n\t}\n}\nfunc lsReal(v LawSpecValue) float64 {\n\tif x, ok := v.Data.(float64); ok {\n\t\treturn x\n\t}\n\tr, _ := lsRatio(v).Float64()\n\treturn r\n}\nfunc lsPrecision(t string, x float64) float64 {\n\tif t == \"Float32\" || t == \"Complex64\" {\n\t\treturn float64(float32(x))\n\t}\n\treturn x\n}\nfunc lsConvert(t string, v LawSpecValue, bits int) LawSpecValue {\n\tif lsSumType(t) {\n\t\tdata := lsDataValue(v)\n\t\ttypes := lsSumFields(t, data.tag)\n\t\tfields := make([]LawSpecValue, len(types))\n\t\tfor index, fieldType := range types {\n\t\t\tfields[index] = lsConvert(fieldType, data.fields[index], bits)\n\t\t}\n\t\treturn lsConstruct(t, data.tag, fields)\n\t}\n\tif strings.HasPrefix(t, \"List \") {\n\t\tvalues, ok := v.Data.([]LawSpecValue)\n\t\tif !ok || !strings.HasPrefix(v.Type, \"List \") {\n\t\t\tpanic(\"List required\")\n\t\t}\n\t\tconverted := make([]