cValue{}, values...), v)\n\t\t\tif d.accept(next) {\n\t\t\t\tif result, ok := search(next); ok {\n\t\t\t\t\treturn result, true\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn nil, false\n\t}\n\tfor used < attempts {\n\t\tif result, ok := search(append([]LawSpecValue{}, prefix...)); ok {\n\t\t\treturn result, true\n\t\t}\n\t}\n\treturn lastPrefix, false\n}\nfunc lsRequireContract(condition bool, context string) {\n\tif !condition {\n\t\tpanic(context)\n\t}\n}\nfunc lsContract(context string, condition bool, result LawSpecValue) LawSpecValue {\n\tlsRequireContract(condition, context)\n\treturn result\n}\nfunc lsCapture(check func([]LawSpecValue), values []LawSpecValue) (failure any) {\n\tdefer func() { failure = recover() }()\n\tcheck(values)\n\treturn nil\n}\nfunc lsRefinedCase(domains []lawSpecDomain, seed, attempts, shrinks int, check func([]LawSpecValue), context string) {\n\tvalues, ok := lsGenerateTuple(domains, seed, attempts, nil)\n\tif !ok {\n\t\tpanic(fmt.Sprintf(\"%s: refinement-generation-exhausted after %d attempts; prefix=%v; seed=%d\", context, attempts, values, seed))\n\t}\n\tif original := lsCapture(check, values); original != nil {\n\t\tbest, budget := values, shrinks\n\t\tfor i := range best {\n\t\t\tvalue := best[i]\n\t\t\tcandidates := domains[i].candidates(best[:i], 0)\n\t\t\tif lsIntegerType(value.Type) {\n\t\t\t\tinitial := value.Data.(*big.Int)\n\t\t\t\tcandidates = append([]LawSpecValue{{value.Type, big.NewInt(0)}, {value.Type, big.NewInt(int64(initial.Sign()))}}, candidates...)\n\t\t\t\tfor n := new(big.Int).Quo(initial, big.NewInt(2)); new(big.Int).Abs(n).Cmp(big.NewInt(1)) > 0; n = new(big.Int).Quo(n, big.NewInt(2)) {\n\t\t\t\t\tcandidates = append(candidates, LawSpecValue{value.Type, n})\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor _, candidate := range candidates {\n\t\t\t\tif budget <= 0 {\n\t\t\t\t\tbreak\n\t\t\t\t}\n\t\t\t\tbudget--\n\t\t\t\tif lsComplexity(candidate).Cmp(lsComplexity(best[i])) >= 0 {\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\tprefix := append(append([]LawSpecValue{}, best[:i]...), candidate)\n\t\t\t\tif !domains[i].accept(prefix) {\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\ttrial, ok := lsGenerateTuple(domains, seed, min(attempts, 100), prefix)\n\t\t\t\tif ok && lsCapture(check, trial) != nil {\n\t\t\t\t\tbest = trial\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tpanic(fmt.Sprintf(\"%s: %v; refined counterexample=%v; seed=%d\", context, original, best, seed))\n\t}\n}\nfunc lsAssert(context string, actual, expected func() LawSpecValue) {\n\tdefer func() {\n\t\tif err := recover(); err != nil {\n\t\t\tpanic(fmt.Sprintf(\"%s: %v\", context, err))\n\t\t}\n\t}()\n\ta, b := actual(), expected()\n\tif !lsEqual(a, b) {\n\t\tpanic(fmt.Sprintf(\"%s | actual=%v expected=%v\", context, a, b))\n\t}\n}\n\nfunc lsComplexity(v LawSpecValue) *big.Int {\n\tswitch x := v.Data.(type) {\n\tcase *big.Int:\n\t\treturn new(big.Int).Abs(x)\n\tcase []int:\n\t\treturn big.NewInt(int64(len(x)))\n\tcase lawSpecPresence:\n\t\tif x.value == nil {\n\t\t\treturn big.NewInt(0)\n\t\t}\n\t\treturn new(big.Int).Add(big.NewInt(1), lsComplexity(*x.value))\n\tcase bool:\n\t\tif x {\n\t\t\treturn big.NewInt(1)\n\t\t}\n\t\treturn big.NewInt(0)\n\tcase float64:\n\t\treturn new(big.Int).SetUint64(math.Float64bits(math.Abs(x)))\n\tcase complex128:\n\t\treturn new(big.Int).Add(lsComplexity(LawSpecValue{\"Float64\", real(x)}), lsComplexity(LawSpecValue{\"Float64\", imag(x)}))\n\tcase int:\n\t\treturn big.NewInt(int64(x))\n\t}\n\tif lsExactType(v.Type) {\n\t\tr := lsRatio(v)\n\t\treturn new(big.Int).Sub(new(big.Int).Add(new(big.Int).Abs(r.Num()), r.Denom()), big.NewInt(1))\n\t}\n\tif v.Data == nil {\n\t\treturn big.NewInt(0)\n\t}\n\treturn big.NewInt(1)\n}\n"
runtimeSource "go-schema" = "// Structural validation is independent of property-testing frameworks.\npackage RUNTIME_PACKAGE\n\nimport (\n\t\"fmt\"\n\t\"reflect\"\n)\n\n// Conversion paths reject cycles while allowing shared acyclic subtrees.\ntype lawSpecPathKey struct {\n\ttypeOf  reflect.Type\n\tpointer uintptr\n\tlength  int\n}\n\ntype lawSpecPath map[lawSpecPathKey]bool\n\nfunc (p lawSpecPath) enter(value any) func() {\n\trv := reflect.ValueOf(value)\n\tif !rv.IsValid() || (rv.Kind() != reflect.Slice && rv.Kind() != reflect.Pointer) || rv.IsNil() {\n\t\treturn func() {}\n\t}\n\tlength := 0\n\tif rv.Kind() == reflect.Slice {\n\t\tlength = rv.Len()\n\t\tif length == 0 {\n\t\t\treturn func() {}\n\t\t}\n\t}\n\tkey := lawSpecPathKey{rv.Type(), rv.Pointer(), length}\n\tif p[key] {\n\t\tpanic(\"cyclic structural value\")\n\t}\n\tp[key] = true\n\treturn func() { delete(p, key) }\n}\n\ntype lawSpecTypeRef struct {\n\tname      string\n\targuments []lawSpecTypeRef\n\tparameter int\n}\n\nfunc lsNamed(name string, arguments ...lawSpecTypeRef) lawSpecTypeRef {\n\treturn lawSpecTypeRef{name: name, arguments: arguments}\n}\n\nfunc lsParameter(index int) lawSpecTypeRef {\n\treturn lawSpecTypeRef{parameter: index}\n}\n\nfunc (t lawSpecTypeRef) key() string {\n\tif t.name == \"\" {\n\t\tpanic(\"uninstantiated schema parameter\")\n\t}\n\tresult := t.name\n\tfor _, argument := range t.arguments {\n\t\tif len(t.arguments) == 1 {\n\t\t\tresult += \" \" + argument.key()\n\t\t} else {\n\t\t\tresult += \" (\" + argument.key() + \")\"\n\t\t}\n\t}\n\treturn result\n}\n\ntype lawSpecFieldSchema struct {\n\tname    string\n\ttypeRef lawSpecTypeRef\n}\n\ntype lawSpecConstructorSchema struct {\n\ttag    string\n\tfields []lawSpecFieldSchema\n}\n\ntype lawSpecDataSchema struct {\n\tname         string\n\tparameters   int\n\tconstructors []lawSpecConstructorSchema\n}\n\n// Predicates run in declaration order after recursive representation validation.\ntype lawSpecFieldPredicate func(*lawSpecSchema, []lawSpecTypeRef, []LawSpecValue, int, map[string]*lawSpecSymbol) bool\n\ntype lawSpecConstructorContract struct {\n\ttag        string\n\tpredicates []lawSpecFieldPredicate\n}\n\ntype lawSpecRefinementViolation struct{ message string }\n\nfunc (v lawSpecRefinementViolation) Error() string { return v.message }\n\ntype lawSpecSchema struct {\n\tdefinitions map[string]lawSpecDataSchema\n\tarity       map[string]int\n\tcontracts   map[string][]lawSpecFieldPredicate\n}\n\nfunc lsNewSchema(definitions []lawSpecDataSchema, primitives []string) *lawSpecSchema {\n\tschema := &lawSpecSchema{definitions: map[string]lawSpecDataSchema{}, arity: map[string]int{\n\t\t\"List\": 1, \"Maybe\": 1, \"Either\": 2, \"Nullable\": 1, \"Optional\": 1,\n\t}}\n\tfor _, name := range primitives {\n\t\tif _, exists := schema.arity[name]; exists || name == \"\" {\n\t\t\tpanic(\"duplicate or invalid primitive: \" + name)\n\t\t}\n\t\tschema.arity[name] = 0\n\t}\n\tfor _, definition := range definitions {\n\t\tif _, exists := schema.arity[definition.name]; exists || definition.name == \"\" {\n\t\t\tpanic(\"duplicate or invalid type: \" + definition.name)\n\t\t}\n\t\tif definition.parameters < 0 {\n\t\t\tpanic(\"negative parameter count: \" + definition.name)\n\t\t}\n\t\t// Own the schema metadata; callers cannot mutate it after registration.\n\t\tconstructors := make([]lawSpecConstructorSchema, len(definition.constructors))\n\t\tfor index, constructor := range definition.constructors {\n\t\t\tfields := make([]lawSpecFieldSchema, len(constructor.fields))\n\t\t\tfor position, field := range constructor.fields {\n\t\t\t\tfields[position] = lawSpecFieldSchema{field.name, lsCopyType(field.typeRef)}\n\t\t\t}\n\t\t\tconstructors[index] = lawSpecConstructorSchema{constructor.tag, fields}\n\t\t}\n\t\tdefinition.constructors = constructors\n\t\tschema.definitions[definition.name] = definition\n\t\tschema.arity[definition.name] = definition.parameters\n\t}\n\ttags := map[string]bool{}\n\tfor _, definition := range schema.definitions {\n\t\tfor _, constructor := range definition.constructors {\n\t\t\tif constructor.tag == \"\" || tags[constructor.tag] {\n\t\t\t\tpanic(\"duplicate or invalid constructor: \" + constructor.tag)\n\t\t\t}\n\t\t\ttags[constructor.tag] = true\n\t\t\tnames := map[string]bool{}\n\t\t\tfor _, field := range constructor.fields {\n\t\t\t\tif field.name == \"\" || names[field.name] {\n\t\t\t\t\tpanic(\"duplicate or invalid field: \" + field.name)\n\t\t\t\t}\n\t\t\t\tnames[field.name] = true\n\t\t\t\tschema.check(field.typeRef, definition.parameters)\n\t\t\t}\n\t\t}\n\t}\n\treturn schema\n}\n\n// Keep contract metadata separate from the representation-only schema API.\nfunc lsNewSchemaWithContracts(definitions []lawSpecDataSchema, primitives []string,\n\tcontracts []lawSpecConstructorContract) *lawSpecSchema {\n\tschema := lsNewSchema(definitions, primitives)\n\tschema.contracts = map[string][]lawSpecFieldPredicate{}\n\ttags := map[string]bool{}\n\tfor _, definition := range schema.definitions {\n\t\tfor _, constructor := range definition.constructors {\n\t\t\ttags[constructor.tag] = true\n\t\t}\n\t}\n\tfor _, contract := range contracts {\n\t\tif _, exists := schema.contracts[contract.tag]; exists || !tags[contract.tag] {\n\t\t\tpanic(\"duplicate or unknown constructor contract: \" + contract.tag)\n\t\t}\n\t\tpredicates := append([]lawSpecFieldPredicate{}, contract.predicates...)\n\t\tfor _, predicate := range predicates {\n\t\t\tif predicate == nil {\n\t\t\t\tpanic(\"nil constructor predicate: \" + contract.tag)\n\t\t\t}\n\t\t}\n\t\tschema.contracts[contract.tag] = predicates\n\t}\n\treturn schema\n}\n\nfunc (s *lawSpecSchema) hasContracts() bool {\n\tfor _, predicates := range s.contracts {\n\t\tif len(predicates) != 0 {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc lsSchemaSymbols(contexts []map[string]*lawSpecSymbol) map[string]*lawSpecSymbol {\n\tif len(contexts) > 1 {\n\t\tpanic(\"expected at most one Symbol context\")\n\t}\n\tif len(contexts) == 1 && contexts[0] != nil {\n\t\treturn contexts[0]\n\t}\n\treturn map[string]*lawSpecSymbol{}\n}\n\n// A false predicate is a rejected candidate; evaluator failures remain panics.\nfunc (s *lawSpecSchema) accepts(t lawSpecTypeRef, value LawSpecValue, bits int,\n\tcontexts ...map[string]*lawSpecSymbol) (accepted bool) {\n\tdefer func() {\n\t\tif problem := recover(); problem != nil {\n\t\t\tif _, rejected := problem.(lawSpecRefinementViolation); rejected {\n\t\t\t\taccepted = false\n\t\t\t} else {\n\t\t\t\tpanic(problem)\n\t\t\t}\n\t\t}\n\t}()\n\ts.validate(t, value, bits, contexts...)\n\treturn true\n}\n\nfunc lsCopyType(t lawSpecTypeRef) lawSpecTypeRef {\n\targuments := make([]lawSpecTypeRef, len(t.arguments))\n\tfor index, argument := range t.arguments {\n\t\targuments[index] = lsCopyType(argument)\n\t}\n\tt.arguments = arguments\n\treturn t\n}\n\nfunc (s *lawSpecSchema) check(t lawSpecTypeRef, parameters int) {\n\tif t.name == \"\" {\n\t\tif t.parameter < 0 || t.parameter >= parameters || len(t.arguments) != 0 {\n\t\t\tpanic(\"unbound schema parameter\")\n\t\t}\n\t\treturn\n\t}\n\tarity, exists := s.arity[t.name]\n\tif !exists || arity != len(t.arguments) {\n\t\tpanic(\"unknown type or wrong arity: \" + t.name)\n\t}\n\tfor _, argument := range t.arguments {\n\t\ts.check(argument, parameters)\n\t}\n}\n\nfunc lsSubstitute(t lawSpecTypeRef, arguments []lawSpecTypeRef) lawSpecTypeRef {\n\tif t.name == \"\" {\n\t\treturn lsCopyType(arguments[t.parameter])\n\t}\n\tchildren := make([]lawSpecTypeRef, len(t.arguments))\n\tfor index, child := range t.arguments {\n\t\tchildren[index] = lsSubstitute(child, arguments)\n\t}\n\treturn lsNamed(t.name, children...)\n}\n\nfunc (s *lawSpecSchema) constructors(t lawSpecTypeRef) ([]lawSpecConstructorSchema, bool) {\n\ts.check(t, 0)\n\tdefinition, exists := s.definitions[t.name]\n\tif !exists {\n\t\treturn nil, false\n\t}\n\tresult := make([]lawSpecConstructorSchema, len(definition.constructors))\n\tfor index, constructor := range definition.constructors {\n\t\tfields := make([]lawSpecFieldSchema, len(constructor.fields))\n\t\tfor position, field := range constructor.fields {\n\t\t\tfields[position] = lawSpecFieldSchema{field.name, lsSubstitute(field.typeRef, t.arguments)}\n\t\t}\n\t\tresult[index] = lawSpecConstructorSchema{constructor.tag, fields}\n\t}\n\treturn result, true\n}\n\nfunc lsSchemaContext(context string, operation func() LawSpecValue) (result LawSpecValue) {\n\tdefer func() {\n\t\tif problem := recover(); problem != nil {\n\t\t\tmessage := fmt.Sprintf(\"%s: %v\", context, problem)\n\t\t\tif _, rejected := problem.(lawSpecRefinementViolation); rejected {\n\t\t\t\tpanic(lawSpecRefinementViolation{message})\n\t\t\t}\n\t\t\tpanic(message)\n\t\t}\n\t}()\n\treturn operation()\n}\n\n// Payload recipes preserve declaration parameter identity through nested types.\n// A nil plan ignores fixed fields, even when their concrete types match a slot.\ntype lawSpecPayloadPlan struct {\n\tname      string\n\tparameter int\n\targuments []*lawSpecPayloadPlan\n}\n\nfunc lsPayloadRecipe(t lawSpecTypeRef, arguments []*lawSpecPayloadPlan) *lawSpecPayloadPlan {\n\tif t.name == \"\" {\n\t\treturn arguments[t.parameter]\n\t}\n\tchildren := make([]*lawSpecPayloadPlan, len(t.arguments))\n\tstored := false\n\tfor index, child := range t.arguments {\n\t\tchildren[index] = lsPayloadRecipe(child, arguments)\n\t\tstored = stored || children[index] != nil\n\t}\n\tif !stored {\n\t\treturn nil\n\t}\n\treturn &lawSpecPayloadPlan{name: t.name, arguments: children}\n}\n\n// Validate the whole value and its contracts before invoking scoped callbacks.\nfunc (s *lawSpecSchema) allPayloads(t lawSpecTypeRef, value LawSpecValue,\n\tpredicates []func(LawSpecValue) LawSpecValue, bits int,\n\tcontexts ...map[string]*lawSpecSymbol) LawSpecValue {\n\ts.check(t, 0)\n\tif _, custom := s.definitions[t.name]; !custom {\n\t\tswitch t.name {\n\t\tcase \"List\", \"Maybe\", \"Either\", \"Nullable\", \"Optional\":\n\t\tdefault:\n\t\t\tpanic(\"payload predicates require a data type\")\n\t\t}\n\t}\n\tif len(predicates) != len(t.arguments) {\n\t\tpanic(\"payload predicate arity mismatch\")\n\t}\n\tpredicates = append([]func(LawSpecValue) LawSpecValue{}, predicates...)\n\targuments := make([]*lawSpecPayloadPlan, len(predicates))\n\tfor index, predicate := range predicates {\n\t\tif predicate == nil {\n\t\t\tpanic(\"nil payload predicate\")\n\t\t}\n\t\targuments[index] = &lawSpecPayloadPlan{parameter: index}\n\t}\n\tchecked := s.validate(t, value, bits, contexts...)\n\treturn lsBool(s.walkPayload(&lawSpecPayloadPlan{name: t.name, arguments: arguments}, checked, predicates))\n}\n\nfunc (s *lawSpecSchema) contextualPayload(plan *lawSpecPayloadPlan, value LawSpecValue,\n\tpredicates []func(LawSpecValue) LawSpecValue, context string) bool {\n\treturn lsTruth(lsSchemaContext(context, func() LawSpecValue {\n\t\treturn lsBool(s.walkPayload(plan, value, predicates))\n\t}))\n}\n\nfunc (s *lawSpecSchema) walkPayload(plan *lawSpecPayloadPlan, value LawSpecValue,\n\tpredicates []func(LawSpecValue) LawSpecValue) bool {\n\tif plan == nil {\n\t\treturn true\n\t}\n\tif plan.name == \"\" {\n\t\treturn lsTruth(predicates[plan.parameter](value))\n\t}\n\targuments := plan.arguments\n\tswitch plan.name {\n\tcase \"List\":\n\t\tfor index, child := range value.Data.([]LawSpecValue) {\n\t\t\tif !s.contextualPayload(arguments[0], child, predicates, fmt.Sprintf(\"List[%d]\", index)) {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\tcase \"Nullable\", \"Optional\":\n\t\tpresence := value.Data.(lawSpecPresence)\n\t\treturn presence.value == nil || s.contextualPayload(arguments[0], *presence.value, predicates, plan.name+\".value\")\n\t}\n\tdata := value.Data.(lawSpecData)\n\tswitch plan.name {\n\tcase \"Maybe\":\n\t\treturn data.tag == \"Maybe::Nothing\" || s.contextualPayload(arguments[0], data.fields[0], predicates, \"Maybe::Just.value\")\n\tcase \"Either\":\n\t\tindex := 0\n\t\tif data.tag == \"Either::Right\" {\n\t\t\tindex = 1\n\t\t}\n\t\treturn s.contextualPayload(arguments[index], data.fields[0], predicates, data.tag+\".value\")\n\t}\n\tfor _, constructor := range s.definitions[plan.name].constructors {\n\t\tif constructor.tag != data.tag {\n\t\t\tcontinue\n\t\t}\n\t\tfor index, field := range constructor.fields {\n\t\t\tif !s.contextualPayload(lsPayloadRecipe(field.typeRef, arguments), data.fields[index], predicates, data.tag+\".\"+field.name) {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\t}\n\tpanic(\"invalid checked payload constructor\")\n}\n\nfunc (s *lawSpecSchema) validate(t lawSpecTypeRef, value LawSpecValue, bits int, contexts ...map[string]*lawSpecSymbol) LawSpecValue {\n\treturn s.validateValue(t, value, bits, lawSpecPath{}, lsSchemaSymbols(contexts))\n}\n\nfunc (s *lawSpecSchema) validateValue(t lawSpecTypeRef, value LawSpecValue, bits int, path lawSpecPath, symbols map[string]*lawSpecSymbol) LawSpecValue {\n\tvar payload any\n\tswitch data := value.Data.(type) {\n\tcase lawSpecData:\n\t\tpayload = data.fields\n\tcase []LawSpecValue:\n\t\tpayload = data\n\tcase lawSpecPresence:\n\t\tpayload = data.value\n\t}\n\tdefer path.enter(payload)()\n\ts.check(t, 0)\n\tif bits != 32 && bits != 64 {\n\t\tpanic(\"machineBits must be 32 or 64\")\n\t}\n\tif value.Type != t.key() {\n\t\tpanic(\"invalid representation for \" + t.key())\n\t}\n\tconstructors, custom := s.constructors(t)\n\tif !custom {\n\t\tswitch t.name {\n\t\tcase \"List\":\n\t\t\tvalues, ok := value.Data.([]LawSpecValue)\n\t\t\tif !ok {\n\t\t\t\tpanic(\"List payload must be a slice of values\")\n\t\t\t}\n\t\t\tresult := make([]LawSpecValue, len(values))\n\t\t\tfor index, child := range values {\n\t\t\t\tresult[index] = lsSchemaContext(fmt.Sprintf(\"List[%d]\", index), func() LawSpecValue {\n\t\t\t\t\treturn s.validateValue(t.arguments[0], child, bits, path, symbols)\n\t\t\t\t})\n\t\t\t}\n\t\t\treturn LawSpecValue{t.key(), result}\n\t\tcase \"Nullable\", \"Optional\":\n\t\t\tpresence, ok := value.Data.(lawSpecPresence)\n\t\t\tif !ok {\n\t\t\t\tpanic(\"invalid presence representation\")\n\t\t\t}\n\t\t\tif presence.value == nil {\n\t\t\t\treturn value\n\t\t\t}\n\t\t\tchild := s.validateValue(t.arguments[0], *presence.value, bits, path, symbols)\n\t\t\treturn lsPresent(t.key(), &child)\n\t\tcase \"Maybe\":\n\t\t\tconstructors = []lawSpecConstructorSchema{\n\t\t\t\t{\"Maybe::Nothing\", nil},\n\t\t\t\t{\"Maybe::Just\", []lawSpecFieldSchema{{\"value\", t.arguments[0]}}},\n\t\t\t}\n\t\tcase \"Either\":\n\t\t\tconstructors = []lawSpecConstructorSchema{\n\t\t\t\t{\"Either::Left\", []lawSpecFieldSchema{{\"value\", t.arguments[0]}}},\n\t\t\t\t{\"Either::Right\", []lawSpecFieldSchema{{\"value\", t.arguments[1]}}},\n\t\t\t}\n\t\tdefault:\n\t\t\treturn lsClone(lsValidate(t.name, value, bits))\n\t\t}\n\t}\n\tdata, ok := value.Data.(lawSpecData)\n\tif !ok {\n\t\tpanic(\"expected constructor payload for \" + t.key())\n\t}\n\tfor _, constructor := range constructors {\n\t\tif constructor.tag != data.tag {\n\t\t\tcontinue\n\t\t}\n\t\tif len(constructor.fields) != len(data.fields) {\n\t\t\tpanic(\"wrong field count: \" + data.tag)\n\t\t}\n\t\tfields := make([]LawSpecValue, len(data.fields))\n\t\tfor index, field := range constructor.fields {\n\t\t\tfields[index] = lsSchemaContext(data.tag+\".\"+field.name, func() LawSpecValue {\n\t\t\t\treturn s.validateValue(field.typeRef, data.fields[index], bits, path, symbols)\n\t\t\t})\n\t\t}\n\t\tfor index, predicate := range s.contracts[data.tag] {\n\t\t\tlsSchemaContext(fmt.Sprintf(\"%s predicate %d\", data.tag, index+1), func() LawSpecValue {\n\t\t\t\tif !predicate(s, t.arguments, fields, bits, symbols) {\n\t\t\t\t\tpanic(lawSpecRefinementViolation{\"constructor field contract rejected\"})\n\t\t\t\t}\n\t\t\t\treturn lsBool(true)\n\t\t\t})\n\t\t}\n\t\treturn LawSpecValue{t.key(), lawSpecData{data.tag, fields}}\n\t}\n\tpanic(\"unknown constructor \" + data.tag + \" for \" + t.key())\n}\n\nfunc (s *lawSpecSchema) construct(t lawSpecTypeRef, tag string, fields []LawSpecValue, bits int, contexts ...map[string]*lawSpecSymbol) LawSpecValue {\n\tsymbols := lsSchemaSymbols(contexts)\n\tif t.name == \"List\" {\n\t\ts.check(t, 0)\n\t\tswitch tag {\n\t\tcase \"List::Nil\":\n\t\t\tif len(fields) != 0 {\n\t\t\t\tpanic(\"Nil takes no fields\")\n\t\t\t}\n\t\t\treturn s.validate(t, LawSpecValue{t.key(), []LawSpecValue{}}, bits, symbols)\n\t\tcase \"List::Cons\":\n\t\t\tif len(fields) != 2 {\n\t\t\t\tpanic(\"Cons takes two fields\")\n\t\t\t}\n\t\t\ttail := s.validate(t, fields[1], bits, symbols).Data.([]LawSpecValue)\n\t\t\treturn s.validate(t, LawSpecValue{t.key(), append([]LawSpecValue{fields[0]}, tail...)}, bits, symbols)\n\t\tdefault:\n\t\t\tpanic(\"unknown List constructor: \" + tag)\n\t\t}\n\t}\n\treturn s.validate(t, LawSpecValue{t.key(), lawSpecData{tag, fields}}, bits, symbols)\n}\n\nfunc (s *lawSpecSchema) equal(t lawSpecTypeRef, a, b LawSpecValue, bits int, contexts ...map[string]*lawSpecSymbol) bool {\n\tsymbols := lsSchemaSymbols(contexts)\n\ta, b = s.validate(t, a, bits, symbols), s.validate(t, b, bits, symbols)\n\treturn lsSchemaEqual(a, b)\n}\n\nfunc lsSchemaEqual(a, b LawSpecValue) bool {\n\tif x, ok := a.Data.(lawSpecData); ok {\n\t\ty, ok := b.Data.(lawSpecData)\n\t\tif !ok || x.tag != y.tag || len(x.fields) != len(y.fields) {\n\t\t\treturn false\n\t\t}\n\t\tfor index, field := range x.fields {\n\t\t\tif !lsSchemaEqual(field, y.fields[index]) {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\t}\n\tif x, ok := a.Data.([]LawSpecValue); ok {\n\t\ty, ok := b.Data.([]LawSpecValue)\n\t\tif !ok || len(x) != len(y) {\n\t\t\treturn false\n\t\t}\n\t\tfor index, field := range x {\n\t\t\tif !lsSchemaEqual(field, y[index]) {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t\treturn true\n\t}\n\tif x, ok := a.Data.(lawSpecPresence); ok {\n\t\ty, ok := b.Data.(lawSpecPresence)\n\t\tif !ok || (x.value == nil) != (y.value == nil) {\n\t\t\treturn false\n\t\t}\n\t\treturn x.value == nil || lsSchemaEqual(*x.value, *y.value)\n\t}\n\treturn lsEqual(a, b)\n}\n\n// Check the complete native binding, including fields in unselected variants.\nfunc (s *lawSpecSchema) checkNativeProfile(t lawSpecTypeRef, bits int) {\n\tvisited := map[string]bool{}\n\tvar check func(lawSpecTypeRef)\n\tcheck = func(current lawSpecTypeRef) {\n\t\tfor _, argument := range current.arguments {\n\t\t\tcheck(argument)\n\t\t}\n\t\tlsCheckNativeProfile(current.name, bits)\n\t\tif visited[current.name] {\n\t\t\treturn\n\t\t}\n\t\tvisited[current.name] = true\n\t\tconstructors, _ := s.constructors(current)\n\t\tfor _, constructor := range constructors {\n\t\t\tfor _, field := range constructor.fields {\n\t\t\t\tcheck(field.typeRef)\n\t\t\t}\n\t\t}\n\t}\n\tcheck(t)\n}\n"
runtimeSource "go-codecs" = "// Typed conversion bridges are independent of property-testing frameworks.\npackage RUNTIME_PACKAGE\n\nimport \"fmt\"\n\ntype lawSpecCodec[T any] struct {\n\ttypeRef    lawSpecTypeRef\n\ttoNative   func(LawSpecValue) T\n\tfromNative func(T) LawSpecValue\n\tencode     func(T, lawSpecPath) LawSpecValue\n}\n\nfunc lsNativeContext[T any](context string, operation func() T) (result T) {\n\tdefer func() {\n\t\tif problem := recover(); problem != nil {\n\t\t\tmessage := fmt.Sprintf(\"%s: %v\", context, problem)\n\t\t\tif _, rejected := problem.(lawSpecRefinementViolation); rejected {\n\t\t\t\tpanic(lawSpecRefinementViolation{message})\n\t\t\t}\n\t\t\tpanic(message)\n\t\t}\n\t}()\n\treturn operation()\n}\n\nfunc lsCodec[T any](schema *lawSpecSchema, bits int, typeRef lawSpecTypeRef,\n\ttoNative func(LawSpecValue) T, fromNative func(T, lawSpecPath) LawSpecValue, contexts ...map[string]*lawSpecSymbol) lawSpecCodec[T] {\n\tsymbols := lsSchemaSymbols(contexts)\n\tschema.check(typeRef, 0)\n\tif bits != 32 && bits != 64 {\n\t\tpanic(\"machineBits must be 32 or 64\")\n\t}\n\tschema.checkNativeProfile(typeRef, bits)\n\tencode := func(value T, path lawSpecPath) LawSpecValue {\n\t\treturn lsSchemaContext(typeRef.key(), func() LawSpecValue {\n\t\t\treturn schema.validate(typeRef, fromNative(value, path), bits, symbols)\n\t\t})\n\t}\n\treturn lawSpecCodec[T]{\n\t\ttypeRef: typeRef,\n\t\ttoNative: func(value LawSpecValue) T {\n\t\t\treturn lsNativeContext(typeRef.key(), func() T {\n\t\t\t\treturn toNative(schema.validate(typeRef, value, bits, symbols))\n\t\t\t})\n\t\t},\n\t\tfromNative: func(value T) LawSpecValue { return encode(value, lawSpecPath{}) },\n\t\tencode:     encode,\n\t}\n}\n\n// Opaque generic payloads retain validation while crossing application hooks.\nfunc lsLogicalCodec(schema *lawSpecSchema, bits int, typeRef lawSpecTypeRef, contexts ...map[string]*lawSpecSymbol) lawSpecCodec[LawSpecValue] {\n\treturn lsCodec(schema, bits, typeRef,\n\t\tfunc(value LawSpecValue) LawSpecValue { return value },\n\t\tfunc(value LawSpecValue, path lawSpecPath) LawSpecValue { return value }, contexts...)\n}\n\nfunc lsScalarCodec[T any](schema *lawSpecSchema, bits int, name string) lawSpecCodec[T] {\n\tlsCheckNativeProfile(name, bits)\n\treturn lsCodec(schema, bits, lsNamed(name),\n\t\tfunc(value LawSpecValue) T {\n\t\t\tvar native any\n\t\t\tswitch name {\n\t\t\tcase \"Unit\":\n\t\t\t\tnative = LawSpecUnit{}\n\t\t\tcase \"Null\":\n\t\t\t\tnative = LawSpecNull{}\n\t\t\tcase \"Undefined\":\n\t\t\t\tnative = LawSpecUndefined{}\n\t\t\tdefault:\n\t\t\t\tnative = lsToNative(name, value, bits)\n\t\t\t}\n\t\t\treturn native.(T)\n\t\t},\n\t\tfunc(value T, path lawSpecPath) LawSpecValue {\n\t\t\tswitch name {\n\t\t\tcase \"Unit\":\n\t\t\t\t_ = any(value).(LawSpecUnit)\n\t\t\t\treturn lsAbsent(name)\n\t\t\tcase \"Null\":\n\t\t\t\t_ = any(value).(LawSpecNull)\n\t\t\t\treturn lsAbsent(name)\n\t\t\tcase \"Undefined\":\n\t\t\t\t_ = any(value).(LawSpecUndefined)\n\t\t\t\treturn lsAbsent(name)\n\t\t\tdefault:\n\t\t\t\treturn lsFromNative(name, value, bits)\n\t\t\t}\n\t\t})\n}\n\nfunc lsListCodec[T any](schema *lawSpecSchema, bits int, element lawSpecCodec[T], contexts ...map[string]*lawSpecSymbol) lawSpecCodec[[]T] {\n\tsymbols := lsSchemaSymbols(contexts)\n\ttypeRef := lsNamed(\"List\", element.typeRef)\n\treturn lsCodec(schema, bits, typeRef,\n\t\tfunc(value LawSpecValue) []T {\n\t\t\tvalues := value.Data.([]LawSpecValue)\n\t\t\tresult := make([]T, len(values))\n\t\t\tfor index, child := range values {\n\t\t\t\tresult[index] = lsNativeContext(fmt.Sprintf(\"List[%d]\", index), func() T {\n\t\t\t\t\treturn element.toNative(child)\n\t\t\t\t})\n\t\t\t}\n\t\t\treturn result\n\t\t},\n\t\tfunc(value []T, path lawSpecPath) LawSpecValue {\n\t\t\tdefer path.enter(value)()\n\t\t\tresult := make([]LawSpecValue, len(value))\n\t\t\tfor index, child := range value {\n\t\t\t\tresult[index] = lsSchemaContext(fmt.Sprintf(\"List[%d]\", index), func() LawSpecValue {\n\t\t\t\t\treturn element.encode(child, path)\n\t\t\t\t})\n\t\t\t}\n\t\t\treturn LawSpecValue{typeRef.key(), result}\n\t\t}, symbols)\n}\n\nfunc lsMaybeCodec[T any](schema *lawSpecSchema, bits int, element lawSpecCodec[T], contexts ...map[string]*lawSpecSymbol) lawSpecCodec[LawSpecMaybe[T]] {\n\tsymbols := lsSchemaSymbols(contexts)\n\ttypeRef := lsNamed(\"Maybe\", element.typeRef)\n\treturn lsCodec(schema, bits, typeRef,\n\t\tfunc(value LawSpecValue) LawSpecMaybe[T] {\n\t\t\tdata := value.Data.(lawSpecData)\n\t\t\tif data.tag == \"Maybe::Nothing\" {\n\t\t\t\treturn LawSpecNothing[T]()\n\t\t\t}\n\t\t\treturn LawSpecJust(element.toNative(data.fields[0]))\n\t\t},\n\t\tfunc(value LawSpecMaybe[T], path lawSpecPath) LawSpecValue {\n\t\t\tif !value.present {\n\t\t\t\treturn schema.construct(typeRef, \"Maybe::Nothing\", nil, bits, symbols)\n\t\t\t}\n\t\t\treturn schema.construct(typeRef, \"Maybe::Just\",\n\t\t\t\t[]LawSpecValue{element.encode(value.value, path)}, bits, symbols)\n\t\t}, symbols)\n}\n\nfunc lsEitherCodec[L, R any](schema *lawSpecSchema, bits int, left lawSpecCodec[L], right lawSpecCodec[R], contexts ...map[string]*lawSpecSymbol) lawSpecCodec[LawSpecEither[L, R]] {\n\tsymbols := lsSchemaSymbols(contexts)\n\ttypeRef := lsNamed(\"Either\", left.typeRef, right.typeRef)\n\treturn lsCodec(schema, bits, typeRef,\n\t\tfunc(value LawSpecValue) LawSpecEither[L, R] {\n\t\t\tdata := value.Data.(lawSpecData)\n\t\t\tif data.tag == \"Either::Left\" {\n\t\t\t\treturn LawSpecLeft[L, R](left.toNative(data.fields[0]))\n\t\t\t}\n\t\t\treturn LawSpecRight[L, R](right.toNative(data.fields[0]))\n\t\t},\n\t\tfunc(value LawSpecEither[L, R], path lawSpecPath) LawSpecValue {\n\t\t\tswitch value.tag {\n\t\t\tcase 1:\n\t\t\t\treturn schema.construct(typeRef, \"Either::Left\",\n\t\t\t\t\t[]LawSpecValue{left.encode(value.left, path)}, bits, symbols)\n\t\t\tcase 2:\n\t\t\t\treturn schema.construct(typeRef, \"Either::Right\",\n\t\t\t\t\t[]LawSpecValue{right.encode(value.right, path)}, bits, symbols)\n\t\t\tdefault:\n\t\t\t\tpanic(\"Either requires Left or Right\")\n\t\t\t}\n\t\t}, symbols)\n}\n\nfunc lsNullableCodec[T any](schema *lawSpecSchema, bits int, element lawSpecCodec[T], contexts ...map[string]*lawSpecSymbol) lawSpecCodec[LawSpecNullable[T]] {\n\tsymbols := lsSchemaSymbols(contexts)\n\ttypeRef := lsNamed(\"Nullable\", element.typeRef)\n\treturn lsCodec(schema, bits, typeRef,\n\t\tfunc(value LawSpecValue) LawSpecNullable[T] {\n\t\t\tpresence := value.Data.(lawSpecPresence)\n\t\t\tif presence.value == nil {\n\t\t\t\treturn LawSpecNullable[T]{}\n\t\t\t}\n\t\t\treturn LawSpecNullable[T]{true, element.toNative(*presence.value)}\n\t\t},\n\t\tfunc(value LawSpecNullable[T], path lawSpecPath) LawSpecValue {\n\t\t\tif !value.Present {\n\t\t\t\treturn lsPresent(typeRef.key(), nil)\n\t\t\t}\n\t\t\tchild := element.encode(value.Value, path)\n\t\t\treturn lsPresent(typeRef.key(), &child)\n\t\t}, symbols)\n}\n\nfunc lsOptionalCodec[T any](schema *lawSpecSchema, bits int, element lawSpecCodec[T], contexts ...map[string]*lawSpecSymbol) lawSpecCodec[LawSpecOptional[T]] {\n\tsymbols := lsSchemaSymbols(contexts)\n\ttypeRef := lsNamed(\"Optional\", element.typeRef)\n\treturn lsCodec(schema, bits, typeRef,\n\t\tfunc(value LawSpecValue) LawSpecOptional[T] {\n\t\t\tpresence := value.Data.(lawSpecPresence)\n\t\t\tif presence.value == nil {\n\t\t\t\treturn LawSpecOptional[T]{}\n\t\t\t}\n\t\t\treturn LawSpecOptional[T]{true, element.toNative(*presence.value)}\n\t\t},\n\t\tfunc(value LawSpecOptional[T], path lawSpecPath) LawSpecValue {\n\t\t\tif !value.Present {\n\t\t\t\treturn lsPresent(typeRef.key(), nil)\n\t\t\t}\n\t\t\tchild := element.encode(value.Value, path)\n\t\t\treturn lsPresent(typeRef.key(), &child)\n\t\t}, symbols)\n}\n"
runtimeSource "go-data-strategies" = "// Native Rapid combinators retain framework generation and shrinking.\npackage RUNTIME_PACKAGE\n\nimport (\n\t\"flag\"\n\t\"fmt\"\n\t\"strconv\"\n\t\"sync\"\n\n\t\"pgregory.net/rapid\"\n)\n\n// Generated tests are sequential. Serialize scoped flag changes as well, and\n// restore them before another generated check or a parallel user test can run.\nvar lawSpecRapidSettings sync.Mutex\n\nfunc lsRapidCheck(t rapid.TB, cases int, property func(*rapid.T)) {\n\tt.Helper()\n\tif cases < 1 {\n\t\tt.Fatalf(\"property case count must be positive\")\n\t\treturn\n\t}\n\tlawSpecRapidSettings.Lock()\n\tdefer lawSpecRapidSettings.Unlock()\n\tsetting := flag.Lookup(\"rapid.checks\")\n\tprevious := setting.Value.String()\n\tdefer func() { _ = setting.Value.Set(previous) }()\n\tif err := setting.Value.Set(strconv.Itoa(cases)); err != nil {\n\t\tt.Fatalf(\"configuring Rapid: %v\", err)\n\t\treturn\n\t}\n\trapid.Check(t, property)\n}\n\n// Rapid 1.2.0 caps each native filter at five attempts. Smaller requested\n// limits use native discards, preserving replay and invalid-shrink handling.\n// The surrounding native generators and engine retain their own retry limits.\nfunc lsBoundedFilter[T any](source *rapid.Generator[T], attempts int, predicate func(T) bool) *rapid.Generator[T] {\n\tif attempts < 1 {\n\t\tpanic(\"filter attempt limit must be positive\")\n\t}\n\tif attempts >= 5 {\n\t\treturn source.Filter(predicate)\n\t}\n\treturn rapid.Custom(func(t *rapid.T) T {\n\t\tdraws := 0\n\t\tbounded := rapid.Custom(func(inner *rapid.T) T {\n\t\t\tif draws >= attempts {\n\t\t\t\tinner.SkipNow()\n\t\t\t}\n\t\t\tdraws++\n\t\t\treturn source.Draw(inner, \"candidate\")\n\t\t})\n\t\treturn bounded.Filter(predicate).Draw(t, \"accepted\")\n\t})\n}\n\ntype lawSpecGeneratorKey struct {\n\ttypeName string\n\tbudget   int\n}\n\nfunc lsDataStrategy(schema *lawSpecSchema, reference lawSpecTypeRef, bits, budget int,\n\tscalar func(string) *rapid.Generator[LawSpecValue]) *rapid.Generator[LawSpecValue] {\n\tif schema.hasContracts() {\n\t\tpanic(\"constructor contracts require checked strategies\")\n\t}\n\treturn lsBuildDataStrategy(schema, reference, bits, budget, scalar, nil)\n}\n\ntype lawSpecCheckedValue struct {\n\tvalue    LawSpecValue\n\tproblem  any\n\trejected bool\n}\n\nfunc (c lawSpecCheckedValue) requireValue() LawSpecValue {\n\tif c.problem != nil {\n\t\tpanic(c.problem)\n\t}\n\tif c.rejected {\n\t\tpanic(\"rejected constructor candidate escaped filtering\")\n\t}\n\treturn c.value\n}\n\n// Catch validation failures only. Never intercept Rapid's internal discard panics.\nfunc lsCheckCandidate(schema *lawSpecSchema, reference lawSpecTypeRef, value LawSpecValue,\n\tbits int, symbols map[string]*lawSpecSymbol) (result lawSpecCheckedValue) {\n\tresult.value = value\n\tdefer func() {\n\t\tif problem := recover(); problem != nil {\n\t\t\tif _, rejected := problem.(lawSpecRefinementViolation); rejected {\n\t\t\t\tresult.rejected = true\n\t\t\t} else {\n\t\t\t\tresult.problem = problem\n\t\t\t}\n\t\t}\n\t}()\n\tresult.value = schema.validate(reference, value, bits, symbols)\n\treturn result\n}\n\n// Native factories compose Rapid generators rather than sampling into a new RNG.\ntype lawSpecNativeFactory func(*lawSpecSchema, lawSpecTypeRef, int,\n\tmap[string]*lawSpecSymbol, []*rapid.Generator[LawSpecValue]) *rapid.Generator[LawSpecValue]\n\ntype lawSpecNativeGeneratorFailure struct {\n\ttypeName string\n\tproblem  any\n}\n\nfunc (e lawSpecNativeGeneratorFailure) Error() string {\n\treturn fmt.Sprintf(\"native generator %s: %v\", e.typeName, e.problem)\n}\n\nfunc lsNativeGeneratorConvert[T any](reference lawSpecTypeRef, convert func() T) (value T) {\n\tdefer func() {\n\t\tif problem := recover(); problem != nil {\n\t\t\tpanic(lawSpecNativeGeneratorFailure{reference.key(), problem})\n\t\t}\n\t}()\n\treturn convert()\n}\n\nfunc lsNativeGeneratorValues[T any](codec lawSpecCodec[T], source *rapid.Generator[T]) *rapid.Generator[LawSpecValue] {\n\treturn rapid.Map(source, func(value T) LawSpecValue {\n\t\treturn lsNativeGeneratorConvert(codec.typeRef, func() LawSpecValue { return codec.fromNative(value) })\n\t})\n}\n\nfunc lsNativeGeneratorArguments[T any](codec lawSpecCodec[T], source *rapid.Generator[LawSpecValue]) *rapid.Generator[T] {\n\treturn rapid.Map(source, func(value LawSpecValue) T {\n\t\treturn lsNativeGeneratorConvert(codec.typeRef, func() T { return codec.toNative(value) })\n\t})\n}\n\ntype lawSpecCheckedStrategy struct {\n\tfactories map[string]lawSpecNativeFactory\n\tattempts  int\n\tproblem   any\n\tsymbols   map[string]*lawSpecSymbol\n\twitnesses map[string][]LawSpecValue\n}\n\nfunc lsDataNodes(value LawSpecValue) int {\n\tcount := 1\n\tswitch data := value.Data.(type) {\n\tcase lawSpecData:\n\t\tfor _, child := range data.fields {\n\t\t\tcount += lsDataNodes(child)\n\t\t}\n\tcase []LawSpecValue:\n\t\tfor _, child := range data {\n\t\t\tcount += lsDataNodes(child)\n\t\t}\n\tcase lawSpecPresence:\n\t\tif data.value != nil {\n\t\t\tcount += lsDataNodes(*data.value)\n\t\t}\n\t}\n\treturn count\n}\n\nfunc (c *lawSpecCheckedStrategy) addWitness(schema *lawSpecSchema, reference lawSpecTypeRef,\n\tvalue LawSpecValue) {\n\tc.witnesses[reference.key()] = append(c.witnesses[reference.key()], value)\n\tswitch data := value.Data.(type) {\n\tcase []LawSpecValue:\n\t\tfor _, child := range data {\n\t\t\tc.addWitness(schema, reference.arguments[0], child)\n\t\t}\n\tcase lawSpecPresence:\n\t\tif data.value != nil {\n\t\t\tc.addWitness(schema, reference.arguments[0], *data.value)\n\t\t}\n\tcase lawSpecData:\n\t\tconstructors, custom := schema.constructors(reference)\n\t\tif custom {\n\t\t\tfor _, constructor := range constructors {\n\t\t\t\tif constructor.tag == data.tag {\n\t\t\t\t\tfor index, field := range constructor.fields {\n\t\t\t\t\t\tc.addWitness(schema, field.typeRef, data.fields[index])\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t} else if len(data.fields) != 0 {\n\t\t\tindex := 0\n\t\t\tif data.tag == \"Either::Right\" {\n\t\t\t\tindex = 1\n\t\t\t}\n\t\t\tc.addWitness(schema, reference.arguments[index], data.fields[0])\n\t\t}\n\t}\n}\n\n// Rapid's native Filter bounds retries and discards invalid replay candidates.\n// Seed alternatives use native SampledFrom, preserving the framework's shrinker.\nfunc lsCheckedDataStrategy(schema *lawSpecSchema, reference lawSpecTypeRef, bits, budget int,\n\tsymbols map[string]*lawSpecSymbol, witnesses []LawSpecValue,\n\tscalar func(string) *rapid.Generator[LawSpecValue]) *rapid.Generator[lawSpecCheckedValue] {\n\treturn lsCheckedDataStrategyWithAttempts(schema, reference, bits, budget, 5, symbols, witnesses, scalar)\n}\n\nfunc lsCheckedDataStrategyWithAttempts(schema *lawSpecSchema, reference lawSpecTypeRef, bits, budget, attempts int,\n\tsymbols map[string]*lawSpecSymbol, witnesses []LawSpecValue,\n\tscalar func(string) *rapid.Generator[LawSpecValue], factories ...map[string]lawSpecNativeFactory) *rapid.Generator[lawSpecCheckedValue] {\n\tif attempts < 1 {\n\t\tpanic(\"filter attempt limit must be positive\")\n\t}\n\tcontext := &lawSpecCheckedStrategy{attempts: attempts, symbols: lsSchemaSymbols([]map[string]*lawSpecSymbol{symbols}),\n\t\twitnesses: map[string][]LawSpecValue{}}\n\tif len(factories) > 1 {\n\t\tpanic(\"only one native factory registry is allowed\")\n\t}\n\tif len(factories) == 1 {\n\t\tcontext.factories = factories[0]\n\t}\n\tfor _, witness := range witnesses {\n\t\tcontext.addWitness(schema, reference, schema.validate(reference, witness, bits, context.symbols))\n\t}\n\t// Validate the plan now; every sample/replay gets its own error state.\n\t_ = lsBuildDataStrategy(schema, reference, bits, budget, scalar, context)\n\treturn rapid.Custom(func(t *rapid.T) (result lawSpecCheckedValue) {\n\t\tdefer func() {\n\t\t\tif problem := recover(); problem != nil {\n\t\t\t\tif _, native := problem.(lawSpecNativeGeneratorFailure); native {\n\t\t\t\t\tresult = lawSpecCheckedValue{problem: problem}\n\t\t\t\t} else {\n\t\t\t\t\tpanic(problem) // Rapid discards and replay control remain Rapid-owned.\n\t\t\t\t}\n\t\t\t}\n\t\t}()\n\t\tsample := *context\n\t\traw := lsBuildDataStrategy(schema, reference, bits, budget, scalar, &sample)\n\t\tvalue := raw.Draw(t, \"candidate\")\n\t\tif sample.problem != nil {\n\t\t\treturn lawSpecCheckedValue{problem: sample.problem}\n\t\t}\n\t\treturn lsCheckCandidate(schema, reference, value, bits, sample.symbols)\n\t})\n}\n\nfunc lsBuildDataStrategy(schema *lawSpecSchema, reference lawSpecTypeRef, bits, budget int,\n\tscalar func(string) *rapid.Generator[LawSpecValue], checked *lawSpecCheckedStrategy) *rapid.Generator[LawSpecValue] {\n\tif budget < 1 {\n\t\tpanic(\"structural node budget must be positive\")\n\t}\n\tif bits != 32 && bits != 64 {\n\t\tpanic(\"machineBits must be 32 or 64\")\n\t}\n\tschema.check(reference, 0)\n\tconstruct := func(t lawSpecTypeRef, tag string, values []LawSpecValue, bits int) LawSpecValue {\n\t\tif checked != nil {\n\t\t\treturn LawSpecValue{t.key(), lawSpecData{tag, values}}\n\t\t}\n\t\treturn schema.construct(t, tag, values, bits)\n\t}\n\tminima := map[lawSpecGeneratorKey]int{}\n\tinhabitants := map[lawSpecGeneratorKey]bool{}\n\tarbitraries := map[lawSpecGeneratorKey]*rapid.Generator[LawSpecValue]{}\n\tvar minimum func(lawSpecTypeRef, int) int\n\tvar inhabited func(lawSpecTypeRef, int) bool\n\tvar allocation func([]lawSpecFieldSchema, int) ([]int, bool)\n\tvar build func(lawSpecTypeRef, int) *rapid.Generator[LawSpecValue]\n\tminimum = func(typeRef lawSpecTypeRef, limit int) int {\n\t\tkey := lawSpecGeneratorKey{typeRef.key(), limit}\n\t\tif cost, exists := minima[key]; exists {\n\t\t\treturn cost\n\t\t}\n\t\tfor cost := 1; cost <= limit; cost++ {\n\t\t\tif inhabited(typeRef, cost) {\n\t\t\t\tminima[key] = cost\n\t\t\t\treturn cost\n\t\t\t}\n\t\t}\n\t\tminima[key] = 0\n\t\treturn 0\n\t}\n\tallocation = func(fields []lawSpecFieldSchema, available int) ([]int, bool) {\n\t\tcosts := make([]int, len(fields))\n\t\tfor index, field := range fields {\n\t\t\tcost := minimum(field.typeRef, available)\n\t\t\tif cost == 0 {\n\t\t\t\treturn nil, false\n\t\t\t}\n\t\t\tcosts[index] = cost\n\t\t\tavailable -= cost\n\t\t}\n\t\tfor index := range costs {\n\t\t\tcosts[index] += available / len(costs)\n\t\t\tif index < available%len(costs) {\n\t\t\t\tcosts[index]++\n\t\t\t}\n\t\t}\n\t\treturn costs, true\n\t}\n\tinhabited = func(typeRef lawSpecTypeRef, available int) bool {\n\t\tif available < 1 {\n\t\t\treturn false\n\t\t}\n\t\tkey := lawSpecGeneratorKey{typeRef.key(), available}\n\t\tif result, exists := inhabitants[key]; exists {\n\t\t\treturn result\n\t\t}\n\t\tif checked != nil && checked.factories[typeRef.name] != nil {\n\t\t\treturn true\n\t\t}\n\t\tconstructors, custom := schema.constructors(typeRef)\n\t\tresult := false\n\t\tif custom {\n\t\t\tfor _, constructor := range constructors {\n\t\t\t\tif _, ok := allocation(constructor.fields, available-1); ok {\n\t\t\t\t\tresult = true\n\t\t\t\t\tbreak\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tswitch typeRef.name {\n\t\t\tcase \"List\", \"Maybe\", \"Nullable\", \"Optional\":\n\t\t\t\tresult = true\n\t\t\tcase \"Either\":\n\t\t\t\tresult = inhabited(typeRef.arguments[0], available-1) || inhabited(typeRef.arguments[1], available-1)\n\t\t\tdefault:\n\t\t\t\tresult = len(typeRef.arguments) == 0\n\t\t\t}\n\t\t}\n\t\tinhabitants[key] = result\n\t\treturn result\n\t}\n\tbuild = func(typeRef lawSpecTypeRef, available int) *rapid.Generator[LawSpecValue] {\n\t\tkey := lawSpecGeneratorKey{typeRef.key(), available}\n\t\tif result, exists := arbitraries[key]; exists {\n\t\t\treturn result\n\t\t}\n\t\tif !inhabited(typeRef, available) {\n\t\t\tpanic(fmt.Sprintf(\"no value of %s within structural node budget %d\", typeRef.key(), available))\n\t\t}\n\t\tif checked != nil && checked.factories[typeRef.name] != nil {\n\t\t\targuments := make([]*rapid.Generator[LawSpecValue], len(typeRef.arguments))\n\t\t\tfor i, argument := range typeRef.arguments {\n\t\t\t\tif inhabited(argument, available) {\n\t\t\t\t\targuments[i] = build(argument, available)\n\t\t\t\t} else {\n\t\t\t\t\t// Phantom parameters may be empty. Rapid owns discards if\n\t\t\t\t\t// the native factory actually draws this argument.\n\t\t\t\t\targuments[i] = rapid.Custom(func(t *rapid.T) LawSpecValue {\n\t\t\t\t\t\tt.Skipf(\"no native generator argument for %s within node budget %d\", argument.key(), available)\n\t\t\t\t\t\treturn LawSpecValue{} // Skipf does not return.\n\t\t\t\t\t})\n\t\t\t\t}\n\t\t\t}\n\t\t\tsource := checked.factories[typeRef.name](schema, typeRef, bits, checked.symbols, arguments)\n\t\t\tresult := rapid.Map(source, func(value LawSpecValue) LawSpecValue {\n\t\t\t\treturn lsNativeGeneratorConvert(typeRef, func() LawSpecValue {\n\t\t\t\t\treturn schema.validate(typeRef, value, bits, checked.symbols)\n\t\t\t\t})\n\t\t\t})\n\t\t\tarbitraries[key] = result\n\t\t\treturn result // Custom distributions never use witness fallback or contract rejection.\n\t\t}\n\t\tconstructors, custom := schema.constructors(typeRef)\n\t\tvar result *rapid.Generator[LawSpecValue]\n\t\tif custom {\n\t\t\talternatives := []*rapid.Generator[LawSpecValue]{}\n\t\t\tfor _, constructor := range constructors {\n\t\t\t\tcosts, ok := allocation(constructor.fields, available-1)\n\t\t\t\tif !ok {\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\tif len(costs) == 0 {\n\t\t\t\t\talternatives = append(alternatives, rapid.Just(construct(typeRef, constructor.tag, nil, bits)))\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\tfields := make([]*rapid.Generator[LawSpecValue], len(costs))\n\t\t\t\tfor index, field := range constructor.fields {\n\t\t\t\t\tfields[index] = build(field.typeRef, costs[index])\n\t\t\t\t}\n\t\t\t\talternatives = append(alternatives, rapid.Custom(func(t *rapid.T) LawSpecValue {\n\t\t\t\t\tvalues := make([]LawSpecValue, len(fields))\n\t\t\t\t\tfor index, field := range fields {\n\t\t\t\t\t\tvalues[index] = field.Draw(t, constructor.fields[index].name)\n\t\t\t\t\t}\n\t\t\t\t\treturn construct(typeRef, constructor.tag, values, bits)\n\t\t\t\t}))\n\t\t\t}\n\t\t\tresult = rapid.OneOf(alternatives...)\n\t\t} else if len(typeRef.arguments) == 0 {\n\t\t\tresult = rapid.Map(scalar(typeRef.name), func(value LawSpecValue) LawSpecValue {\n\t\t\t\tif checked != nil {\n\t\t\t\t\treturn value\n\t\t\t\t}\n\t\t\t\treturn schema.validate(typeRef, value, bits)\n\t\t\t})\n\t\t} else {\n\t\t\tswitch typeRef.name {\n\t\t\tcase \"List\":\n\t\t\t\tremaining := available - 1\n\t\t\t\tcost := minimum(typeRef.arguments[0], remaining)\n\t\t\t\tmaximum := 0\n\t\t\t\tif cost != 0 {\n\t\t\t\t\tmaximum = remaining / cost\n\t\t\t\t}\n\t\t\t\t// Prebuild choices so draws never mutate the construction caches.\n\t\t\t\tlists := make([]*rapid.Generator[[]LawSpecValue], maximum+1)\n\t\t\t\tlists[0] = rapid.Just([]LawSpecValue{})\n\t\t\t\tfor length := 1; length <= maximum; length++ {\n\t\t\t\t\tlists[length] = rapid.SliceOfN(build(typeRef.arguments[0], remaining/length), length, length)\n\t\t\t\t}\n\t\t\t\tresult = rapid.Custom(func(t *rapid.T) LawSpecValue {\n\t\t\t\t\tlength := rapid.IntRange(0, maximum).Draw(t, \"length\")\n\t\t\t\t\treturn LawSpecValue{typeRef.key(), lists[length].Draw(t, \"items\")}\n\t\t\t\t})\n\t\t\tcase \"Maybe\", \"Nullable\", \"Optional\":\n\t\t\t\tabsent := lsPresent(typeRef.key(), nil)\n\t\t\t\tif typeRef.name == \"Maybe\" {\n\t\t\t\t\tabsent = construct(typeRef, \"Maybe::Nothing\", nil, bits)\n\t\t\t\t}\n\t\t\t\tresult = rapid.Just(absent)\n\t\t\t\tif inhabited(typeRef.arguments[0], available-1) {\n\t\t\t\t\tpresent := rapid.Map(build(typeRef.arguments[0], available-1), func(value LawSpecValue) LawSpecValue {\n\t\t\t\t\t\tif typeRef.name == \"Maybe\" {\n\t\t\t\t\t\t\treturn construct(typeRef, \"Maybe::Just\", []LawSpecValue{value}, bits)\n\t\t\t\t\t\t}\n\t\t\t\t\t\treturn lsPresent(typeRef.key(), &value)\n\t\t\t\t\t})\n\t\t\t\t\tresult = rapid.OneOf(result, present)\n\t\t\t\t}\n\t\t\tcase \"Either\":\n\t\t\t\talternatives := []*rapid.Generator[LawSpecValue]{}\n\t\t\t\tfor index, child := range typeRef.arguments {\n\t\t\t\t\tif inhabited(child, available-1) {\n\t\t\t\t\t\ttag := []string{\"Either::Left\", \"Either::Right\"}[index]\n\t\t\t\t\t\talternatives = append(alternatives, rapid.Map(build(child, available-1), func(value LawSpecValue) LawSpecValue {\n\t\t\t\t\t\t\treturn construct(typeRef, tag, []LawSpecValue{value}, bits)\n\t\t\t\t\t\t}))\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tresult = rapid.OneOf(alternatives...)\n\t\t\tdefault:\n\t\t\t\tpanic(\"unsupported data generator: \" + typeRef.name)\n\t\t\t}\n\t\t}\n\t\tif checked != nil {\n\t\t\tseeds := []LawSpecValue{}\n\t\t\tfor _, witness := range checked.witnesses[typeRef.key()] {\n\t\t\t\tif lsDataNodes(witness) <= available {\n\t\t\t\t\tseeds = append(seeds, witness)\n\t\t\t\t}\n\t\t\t}\n\t\t\tif len(seeds) != 0 {\n\t\t\t\tresult = rapid.OneOf(result, rapid.SampledFrom(seeds))\n\t\t\t}\n\t\t\tfiltered := lsBoundedFilter(result, checked.attempts, func(value LawSpecValue) bool {\n\t\t\t\tif checked.problem != nil {\n\t\t\t\t\treturn true\n\t\t\t\t}\n\t\t\t\tcandidate := lsCheckCandidate(schema, typeRef, value, bits, checked.symbols)\n\t\t\t\tif candidate.problem != nil {\n\t\t\t\t\tchecked.problem = candidate.problem\n\t\t\t\t}\n\t\t\t\treturn !candidate.rejected\n\t\t\t})\n\t\t\tresult = rapid.Custom(func(t *rapid.T) LawSpecValue {\n\t\t\t\t// Do not draw more fields after an evaluator failure.\n\t\t\t\tif checked.problem != nil {\n\t\t\t\t\treturn rapid.Just(LawSpecValue{}).Draw(t, \"failed\")\n\t\t\t\t}\n\t\t\t\treturn filtered.Draw(t, \"checked\")\n\t\t\t})\n\t\t}\n\t\tarbitraries[key] = result\n\t\treturn result\n\t}\n\treturn build(reference, budget)\n}\n"
runtimeSource "haskell" = "{-# LANGUAGE FlexibleInstances, TypeSynonymInstances #-}\n-- The portable scalar domain. No test framework or target runtime dependencies.\nmodule LawSpecRuntime where\n\nimport Control.Exception (SomeException, catch, displayException)\nimport Control.Monad (foldM)\nimport Data.Unique (Unique, newUnique)\nimport Data.Char (ord, chr)\nimport Data.Int\nimport Data.ByteString (ByteString)\nimport qualified Data.ByteString as B\nimport Data.Complex (Complex((:+)))\nimport Data.Word\nimport Data.Bits (finiteBitSize)\nimport Data.Text (Text)\nimport qualified Data.Text as T\nimport Data.List (find, stripPrefix)\nimport Data.Ratio\nimport GHC.Float\n  ( castFloatToWord32, castDoubleToWord64, castWord32ToFloat\n  , castWord64ToDouble, float2Double, double2Float\n  )\nimport Numeric (showHex, readHex)\n\ndata Family\n  = Boolean | IntegerFamily | Exact | Floating | Complex | Character\n  | Sequence | Identity | Absence\n  deriving (Eq, Show)\n\ndata Primitive = Primitive\n  { primitiveName :: String\n  , family :: Family\n  , width :: Maybe Int\n  , signed :: Bool\n  } deriving (Eq, Show)\n\nprimitives :: [Primitive]\nprimitives = [Primitive \"Bool\" Boolean Nothing False]\n  ++ [Primitive (p ++ show w) IntegerFamily (Just w) s\n     | (p,s) <- [(\"Int\",True),(\"UInt\",False)], w <- [8,16,32,64]]\n  ++ [Primitive n IntegerFamily Nothing s\n     | (n,s) <- [(\"IntSize\",True),(\"UIntSize\",False),(\"UIntPtr\",False),\n                 (\"Integer\",True),(\"BigInt\",True),(\"BigUInt\",False)]]\n  ++ [Primitive n f w False\n     | (n,f,w) <- [(\"Decimal\",Exact,Nothing),(\"Rational\",Exact,Nothing),\n                   (\"Float32\",Floating,Just 32),(\"Float64\",Floating,Just 64),\n                   (\"Complex64\",Complex,Just 32),\n                   (\"Complex128\",Complex,Just 64)]]\n  ++ [Primitive n f Nothing False\n     | (f,ns) <- [(Character,[\"Char\",\"CodePoint\",\"CodeUnit16\"]),\n                  (Sequence,[\"Text\",\"CodePointText\",\"Utf16Text\",\"Bytes\"]),\n                  (Identity,[\"Symbol\"]),(Absence,[\"Unit\",\"Null\",\"Undefined\"])],\n       n <- ns]\nprimitive :: String -> Maybe Primitive\nprimitive n = find ((== n) . primitiveName) primitives\nisInteger, isExact, isInexact, isNumeric :: String -> Bool\nisInteger n = maybe False ((== IntegerFamily) . family) (primitive n)\nisExact n = isInteger n || n `elem` [\"Decimal\",\"Rational\"]\nisInexact n = n `elem` [\"Float32\",\"Float64\",\"Complex64\",\"Complex128\"]\nisNumeric n = isExact n || isInexact n\nintegerBounds :: Int -> String -> Maybe (Integer, Integer)\nintegerBounds machine n = do\n  p <- primitive n\n  w <- if n `elem` [\"IntSize\",\"UIntSize\",\"UIntPtr\"]\n    then Just machine else width p\n  if family p /= IntegerFamily then Nothing else pure $\n    if signed p then (negate (2^(w-1)),2^(w-1)-1) else (0,2^w-1)\n\n-- Raw strings travel as numeric code points/units,\n-- never JSON surrogate strings.\ndata Scalar = SInteger String Integer | SBool Bool | SDecimal Integer Integer\n  | SRational Integer Integer | SFloat String String\n  | SComplex String Scalar Scalar\n  | SSequence String [Int] | SCharacter String Int | SSymbol String String\n  | SScopedSymbol SymbolContext String String\n  | SAbsent String | SPresent String (Maybe Scalar)\n  | SList [Scalar] | SData String [Scalar] deriving (Eq, Show)\nscalarName :: Scalar -> String\nscalarName (SInteger t _) = t\nscalarName (SBool _) = \"Bool\"\nscalarName (SDecimal _ _) = \"Decimal\"\nscalarName (SRational _ _) = \"Rational\"\nscalarName (SFloat t _) = t\nscalarName (SComplex t _ _) = t\nscalarName (SSequence t _) = t\nscalarName (SCharacter t _) = t\nscalarName (SSymbol _ _) = \"Symbol\"\nscalarName (SScopedSymbol _ _ _) = \"Symbol\"\nscalarName (SAbsent t) = t\nscalarName (SPresent t _) = t\nscalarName (SList _) = \"List\"\nscalarName (SData tag _) = takeWhile (/= ':') tag\nfloatScalar :: String -> Double -> Scalar\nfloatScalar t x = SFloat t $ pad (if t == \"Float32\" then 8 else 16) $\n  if t == \"Float32\"\n    then showHex (castFloatToWord32 (double2Float x)) \"\"\n    else showHex (castDoubleToWord64 x) \"\"\n  where pad n s = replicate (n-length s) '0' ++ s\nfloatValue :: Scalar -> Double\nfloatValue (SFloat t bits) = case readHex bits of\n  [(n,\"\")] -> if t == \"Float32\"\n    then float2Double (castWord32ToFloat (fromInteger n))\n    else castWord64ToDouble (fromInteger n)\n  _ -> error \"invalid internal float bits\"\nfloatValue _ = error \"not a float\"\nexactValue :: Scalar -> Either String Rational\nexactValue (SInteger _ n) = Right (n % 1)\nexactValue (SRational n d) | d /= 0 = Right (n % d)\nexactValue (SDecimal c e) = Right (if e >= 0 then c * 10^e % 1 else c % 10^(-e))\nexactValue _ = Left \"requires an exact numeric value\"\nreduced :: Rational -> Scalar\nreduced r = SRational (numerator r) (denominator r)\ndecimal :: Rational -> Either String Scalar\ndecimal r = go (denominator r) 0 0 where\n  go d a b | d `mod` 2 == 0 = go (d `div` 2) (a+1) b\n           | d `mod` 5 == 0 = go (d `div` 5) a (b+1)\n           | d /= 1 =\n               Left \"conversion to Decimal is not finite; use prelude.round\"\n           | otherwise = let scale = max a b\n                         in Right (SDecimal\n                           (numerator r * 2^(scale-a) * 5^(scale-b)) (-scale))\nvalidateScalar :: Int -> Scalar -> Either String Scalar\nvalidateScalar machine s = case s of\n  SInteger t n | not (isInteger t) -> Left \"unknown integer type\"\n               | t == \"BigUInt\" && n < 0 -> Left \"BigUInt cannot be negative\"\n               | Just (lo,hi) <- integerBounds machine t,\n                 n < lo || n > hi -> Left (\"integer outside \" ++ t ++ \" range\")\n               | otherwise -> Right s\n  SRational n d | d == 0 -> Left \"Rational denominator cannot be zero\"\n                | otherwise -> Right (reduced (n % d))\n  SCharacter t c | validUnit t c -> Right s\n                 | otherwise -> Left (\"invalid \" ++ t ++ \" representation\")\n  SSequence t xs | t `elem` [\"Text\",\"CodePointText\",\"Utf16Text\",\"Bytes\"],\n                  all (validUnit t) xs -> Right s\n                | otherwise -> Left (\"invalid \" ++ t ++ \" representation\")\n  SFloat t bits | t `elem` [\"Float32\",\"Float64\"],\n                 length bits == (if t == \"Float32\" then 8 else 16),\n                 [(_,\"\")] <- (readHex bits :: [(Integer,String)]) -> Right s\n               | otherwise -> Left \"invalid IEEE bit representation\"\n  SComplex t r i | t `elem` [\"Complex64\",\"Complex128\"],\n                  all ((== if t == \"Complex64\" then \"Float32\" else \"Float64\") .\n                    scalarName) [r,i] ->\n                    SComplex t <$> validateScalar machine r\n                      <*> validateScalar machine i\n                 | otherwise -> Left \"complex component precision mismatch\"\n  SScopedSymbol _ i d\n    | all (validUnit \"Text\" . ord) (i ++ d) -> Right s\n    | otherwise -> Left\n        \"Symbol IDs and descriptions must contain Unicode scalars\"\n  SSymbol i d | all (validUnit \"Text\" . ord) (i ++ d) -> Right s\n              | otherwise -> Left\n                  \"Symbol IDs and descriptions must contain Unicode scalars\"\n  SAbsent t | t `elem` [\"Unit\",\"Null\",\"Undefined\"] -> Right s\n            | otherwise -> Left \"unknown absence value\"\n  SPresent t v | t `elem` [\"Nullable\",\"Optional\"] ->\n                 SPresent t <$> traverse (validateScalar machine) v\n               | otherwise -> Left \"unknown presence type\"\n  _ -> Right s\nvalidUnit :: String -> Int -> Bool\nvalidUnit t c\n  | t == \"Bytes\" = c >= 0 && c <= 255\n  | t `elem` [\"CodeUnit16\",\"Utf16Text\"] = c >= 0 && c <= 65535\n  | t `elem` [\"CodePoint\",\"CodePointText\"] = c >= 0 && c <= 1114111\n  | t `elem` [\"Char\",\"Text\"] =\n      c >= 0 && c <= 1114111 && (c < 55296 || c > 57343)\n  | otherwise = False\npromote :: String -> String -> String -> Either String String\npromote op a b\n  | not (isNumeric a && isNumeric b) =\n      Left \"arithmetic requires numeric operands (Bool is not an integer)\"\n  | isExact a /= isExact b =\n      Left \"exact/inexact mixing requires an explicit conversion\"\n  | op `elem` [\"quot\",\"rem\"] =\n      if isInteger a && isInteger b then Right \"Integer\"\n      else Left \"quot/rem require integer operands\"\n  | isExact a = Right $\n      if op == \"/\" || \"Rational\" `elem` [a,b] then \"Rational\"\n      else if \"Decimal\" `elem` [a,b] then \"Decimal\" else \"Integer\"\n  | otherwise = Right $ if any (`elem` [\"Complex64\",\"Complex128\"]) [a,b]\n      then if any (`elem` [\"Float64\",\"Complex128\"]) [a,b]\n        then \"Complex128\" else \"Complex64\"\n      else if \"Float64\" `elem` [a,b] then \"Float64\" else \"Float32\"\nconvertScalar :: Int -> String -> Scalar -> Either String Scalar\nconvertScalar machine t s\n  | t == scalarName s = validateScalar machine s\n  | isInteger t = do\n      r <- exactValue s\n      if denominator r /= 1 then Left (\"fractional conversion to \" ++ t)\n      else validateScalar machine (SInteger t (numerator r))\n  | t == \"Rational\" = reduced <$> exactValue s\n  | t == \"Decimal\" = exactValue s >>= decimal\n  | t `elem` [\"Float32\",\"Float64\"] = if isExact (scalarName s)\n      then (\\r -> if t == \"Float32\"\n        then SFloat t (pad8 (showHex (castFloatToWord32 (fromRational r)) \"\"))\n        else floatScalar t (fromRational r)) <$> exactValue s\n      else case s of\n      SFloat _ _ -> Right (floatScalar t (floatValue s))\n      _ -> Left \"conversion requires a real number\"\n  | t `elem` [\"Complex64\",\"Complex128\"] =\n      let component = if t == \"Complex64\" then \"Float32\" else \"Float64\"\n      in case s of\n        SComplex _ r i -> SComplex t <$> convertScalar machine component r\n          <*> convertScalar machine component i\n        _ -> SComplex t <$> convertScalar machine component s\n          <*> pure (floatScalar component 0)\n  | otherwise = Left (\"cannot convert \" ++ scalarName s ++ \" to \" ++ t)\nscalarBoundaries :: Int -> String -> [Scalar]\nscalarBoundaries machine t\n  | isInteger t = map (SInteger t) $ case integerBounds machine t of\n      Just (lo,hi) -> [lo, max lo (-1),0,hi]\n      Nothing -> if t == \"BigUInt\" then [0,1,2^(128::Int)]\n        else [-2^(128::Int),-1,0,2^(128::Int)]\n  | otherwise = case t of\n      \"Bool\" -> map SBool [False,True]\n      \"Decimal\" -> [SDecimal 0 0,SDecimal 1 (-1),SDecimal (-123) 100]\n      \"Rational\" -> [SRational 0 1,SRational 1 2,SRational (-2) 3]\n      \"Float32\" -> floats t\n      \"Float64\" -> floats t\n      \"Complex64\" -> [SComplex t x y\n        | (x,y) <- zip (floats \"Float32\") (reverse (floats \"Float32\"))]\n      \"Complex128\" -> [SComplex t x y\n        | (x,y) <- zip (floats \"Float64\") (reverse (floats \"Float64\"))]\n      \"Symbol\" -> [SSymbol \"a\" \"same\", SSymbol \"b\" \"same\"]\n      _ | Just p <- primitive t, family p == Character ->\n          map (SCharacter t) (units t)\n        | Just p <- primitive t, family p == Sequence ->\n          map (SSequence t) [[],units t]\n        | otherwise -> [SAbsent t]\n  where floats n = map (SFloat n) $ if n == \"Float32\"\n          then [\"00000000\",\"80000000\",\"3f800000\",\"bf800000\",\n                \"7f800000\",\"ff800000\",\"7fc00000\",\"00000001\",\n                \"007fffff\",\"00800000\",\"7f7fffff\",\"ff7fffff\"]\n          else [\"0000000000000000\",\"8000000000000000\",\"3ff0000000000000\",\n                \"bff0000000000000\",\"7ff0000000000000\",\"fff0000000000000\",\n                \"7ff8000000000000\",\"0000000000000001\",\"000fffffffffffff\",\n                \"0010000000000000\",\"7fefffffffffffff\",\"ffefffffffffffff\"]\n        units n | n == \"Bytes\" = [0,127,128,255]\n                | n `elem` [\"Utf16Text\",\"CodeUnit16\"] = [0,55296,56320,65535]\n                | n `elem` [\"CodePointText\",\"CodePoint\"] =\n                    [0,55296,128512,1114111]\n                | otherwise = [0,97,955,128512,1114111]\ntextScalar :: String -> Scalar\ntextScalar = SSequence \"Text\" . map ord\n\ntype Value = Scalar\nallElements :: Scalar -> (Scalar -> Scalar) -> Scalar\nallElements (SList values) predicate = SBool (all (truth . predicate) values)\nallElements _ _ = error \"expected List in element predicate\"\n\nconstruct :: String -> [Scalar] -> Scalar\nconstruct \"List::Nil\" [] = SList []\nconstruct \"List::Cons\" [headValue, SList tailValues] =\n  SList (headValue : tailValues)\nconstruct \"Maybe::Nothing\" [] = SData \"Maybe::Nothing\" []\nconstruct tag [value]\n  | tag `elem` [\"Maybe::Just\", \"Either::Left\", \"Either::Right\"] =\n      SData tag [value]\nconstruct tag _ = error (\"invalid constructor or arity: \" ++ tag)\n\n-- Decode the compiler's parenthesized two-argument runtime type key.\neitherArguments :: String -> (String, String)\neitherArguments t = case stripPrefix \"Either \" t of\n  Just body -> case arguments body of\n    [a,b] | not (null a), not (null b) -> (a,b)\n    _ -> error \"invalid Either type key\"\n  Nothing -> error \"Either type required\"\n  where\n    arguments [] = []\n    arguments (' ':rest) = arguments rest\n    arguments ('(':rest) = let (value,remaining) = consume (1 :: Int) [] rest\n                          in value : arguments remaining\n    arguments _ = error \"invalid Either type key\"\n    consume 1 value (')':rest) = (reverse value,rest)\n    consume depth value ('(':rest) = consume (depth+1) ('(':value) rest\n    consume depth value (')':rest) = consume (depth-1) (')':value) rest\n    consume depth value (c:rest) = consume depth (c:value) rest\n    consume _ _ [] = error \"invalid Either type key\"\n\nmapSumFields :: (String -> Scalar -> Scalar) -> String -> Scalar -> Scalar\nmapSumFields field t value = forceScalar result `seq` result\n  where\n    result | Just inner <- stripPrefix \"Maybe \" t = case value of\n             SData \"Maybe::Nothing\" [] -> value\n             SData \"Maybe::Just\" [payload] ->\n               SData \"Maybe::Just\" [field inner payload]\n             _ -> error \"invalid Maybe constructor or arity\"\n           | otherwise = let (left,right) = eitherArguments t in case value of\n             SData \"Either::Left\" [payload] ->\n               SData \"Either::Left\" [field left payload]\n             SData \"Either::Right\" [payload] ->\n               SData \"Either::Right\" [field right payload]\n             _ -> error \"invalid Either constructor or arity\"\n\nconvert :: String -> Scalar -> Int -> Scalar\nconvert t s bits\n  | take 6 t == \"Maybe \" || take 7 t == \"Either \" =\n      mapSumFields (\\inner value -> convert inner value bits) t s\n  | Just inner <- stripPrefix \"List \" t = case s of\n      SList xs -> let result = SList (map (\\x -> convert inner x bits) xs)\n                  in forceScalar result `seq` result\n      _ -> error \"List required\"\n  | Just inner <- strip \"Nullable \" t = presence \"Nullable\" \"Null\" inner\n  | Just inner <- strip \"Optional \" t = presence \"Optional\" \"Undefined\" inner\n  | isExact t, SFloat _ _ <- s = let x = floatValue s\n    in if isNaN x || isInfinite x then error \"non-finite exact conversion\"\n       else either error id (convertScalar bits t (reduced (toRational x)))\n  | otherwise = either error id (convertScalar bits t s)\n  where presence n absent inner = case s of\n          SAbsent a | a == absent -> SPresent n Nothing\n          SPresent k v | k == n ->\n            SPresent n (fmap (\\x -> convert inner x bits) v)\n          _ -> error \"tagged presence required\"\n        strip [] xs = Just xs\n        strip (a:as) (b:bs) | a == b = strip as bs\n        strip _ _ = Nothing\nvalidate :: String -> Scalar -> Int -> Scalar\nvalidate t s bits\n  | take 6 t == \"Maybe \" || take 7 t == \"Either \" =\n      mapSumFields (\\inner value -> validate inner value bits) t s\n  | Just inner <- stripPrefix \"List \" t = case s of\n      SList xs -> let result = SList (map (\\x -> validate inner x bits) xs)\n                  in forceScalar result `seq` result\n      _ -> error \"List required\"\n  | take 9 t == \"Nullable \" || take 9 t == \"Optional \" = convert t s bits\n  | scalarName s /= t = error (\"invalid \" ++ t ++ \" representation\")\n  | otherwise = either error id (validateScalar bits s)\ntruth :: Scalar -> Bool\ntruth (SBool b) = b\ntruth _ = error \"Bool required\"\nequal :: Scalar -> Scalar -> Bool\nequal a b\n  | SData tag xs <- a, SData other ys <- b =\n      tag == other && length xs == length ys && and (zipWith equal xs ys)\n  | SList xs <- a, SList ys <- b =\n      length xs == length ys && and (zipWith equal xs ys)\n  | isInexact (scalarName a) && isInexact (scalarName b) =\n      truth (binary \"==\" a b)\n  | isExact (scalarName a) && isExact (scalarName b) =\n      exactValue a == exactValue b\n  | SFloat _ _ <- a, SFloat _ _ <- b = floatValue a == floatValue b\n  | SComplex _ r i <- a, SComplex _ s j <- b = equal r s && equal i j\n  | SPresent n x <- a, SPresent m y <- b = n == m && case (x,y) of\n      (Nothing,Nothing) -> True\n      (Just p,Just q) -> equal p q\n      _ -> False\n  | SSymbol i _ <- a, SSymbol j _ <- b = i == j\n  | SScopedSymbol scope i _ <- a, SScopedSymbol other j _ <- b =\n      scope == other && i == j\n  | otherwise = a == b\nbinary :: String -> Scalar -> Scalar -> Scalar\nbinary op a b | op `elem` [\"==\",\"!=\"], not (isNumeric (scalarName a)) =\n  SBool (if op == \"==\" then equal a b else not (equal a b))\nbinary op a b = either error run (promote op (scalarName a) (scalarName b))\n  where\n  run t\n    | isExact (scalarName a) =\n        let x = either error id (exactValue a)\n            y = either error id (exactValue b)\n            result = case op of\n              \"+\" -> x+y\n              \"-\" -> x-y\n              \"*\" -> x*y\n              \"/\" -> x/y\n              _ -> error \"unknown arithmetic operator\"\n        in if op `elem` [\"<\",\"<=\",\">\",\">=\",\"==\",\"!=\"]\n          then SBool (compareWith op x y)\n        else if op == \"quot\"\n          then SInteger \"Integer\" (numerator x `quot` numerator y)\n        else if op == \"rem\"\n          then SInteger \"Integer\" (numerator x `rem` numerator y)\n        else convert t (reduced result) 64\n    | t `elem` [\"Complex64\",\"Complex128\"] =\n        let component = if t == \"Complex64\" then \"Float32\" else \"Float64\"\n            pair (SComplex _ r i) = (floatValue r,floatValue i)\n            pair s = (floatValue s,0)\n            (ar,ai) = pair a; (br,bi) = pair b\n            rnd = floatValue . floatScalar component\n            d = rnd (rnd (br*br)+rnd (bi*bi))\n            (re,im) = case op of\n              \"+\" -> (ar+br,ai+bi)\n              \"-\" -> (ar-br,ai-bi)\n              \"*\" -> (rnd (ar*br)-rnd (ai*bi),rnd (ar*bi)+rnd (ai*br))\n              \"/\" ->\n                (rnd (rnd (ar*br)+rnd (ai*bi))/d,\n                 rnd (rnd (ai*br)-rnd (ar*bi))/d)\n              _ -> error \"complex values are not ordered\"\n        in if op == \"==\" then SBool (ar==br && ai==bi)\n           else if op == \"!=\" then SBool (ar/=br || ai/=bi)\n           else SComplex t (floatScalar component re) (floatScalar component im)\n    | otherwise = let x = floatValue a; y = floatValue b\n                      result = case op of\n                        \"+\" -> x+y\n                        \"-\" -> x-y\n                        \"*\" -> x*y\n                        \"/\" -> x/y\n                        _ -> error \"unknown operator\"\n                  in if op `elem` [\"<\",\"<=\",\">\",\">=\",\"==\",\"!=\"]\n                     then SBool (compareWith op x y) else floatScalar t result\n  compareWith \"<\" x y = x < y\n  compareWith \"<=\" x y = x <= y\n  compareWith \">\" x y = x > y\n  compareWith \">=\" x y = x >= y\n  compareWith \"==\" x y = x == y\n  compareWith \"!=\" x y = x /= y\n  compareWith _ _ _ = error \"unknown comparison\"\nhelper :: String -> [Scalar] -> Int -> Scalar\nhelper n args bits = case (n,args) of\n  (\"checked\",[v]) -> forceScalar v `seq` SBool True\n  (\"length\",[SSequence _ xs]) -> SInteger \"Integer\" (fromIntegral (length xs))\n  (\"length\",[SList xs]) -> SInteger \"Integer\" (fromIntegral (length xs))\n  (\"isPresent\",[SPresent _ v]) -> SBool (case v of Just _ -> True; _ -> False)\n  (\"presentValue\",[SPresent _ (Just v)]) -> v\n  (\"real\",[SComplex _ r _]) -> r\n  (\"imag\",[SComplex _ _ i]) -> i\n  (\"quot\",[a,b]) -> binary \"quot\" a b\n  (\"rem\",[a,b]) -> binary \"rem\" a b\n  (\"negate\",[a]) | isExact (scalarName a) -> binary \"-\" (SInteger \"BigInt\" 0) a\n  (\"negate\",[SComplex t r i]) ->\n    SComplex t (helper \"negate\" [r] bits) (helper \"negate\" [i] bits)\n  (\"negate\",[a]) -> floatScalar (scalarName a) (negate (floatValue a))\n  (\"isNaN\",[a]) -> SBool (isNaN (floatValue a))\n  (\"isInfinite\",[a]) -> SBool (isInfinite (floatValue a))\n  (\"isFinite\",[a]) ->\n    SBool (not (isNaN (floatValue a) || isInfinite (floatValue a)))\n  (\"isNegativeZero\",[a]) -> SBool (isNegativeZero (floatValue a))\n  (\"round\",[a,b]) ->\n    let { x = either error id (exactValue a)\n        ; scale = either error numerator (exactValue (convert \"Int32\" b bits))\n        ; factor = if scale >= 0 then 10^scale % 1 else 1 % 10^(-scale)\n        }\n    in either error id (decimal (fromInteger (round (x*factor)) / factor))\n  (_,[a]) -> convert n a bits\n  _ -> error \"unknown helper or wrong arity\"\n\nsample :: String -> Int -> Int -> Scalar\nsample t seed bits\n  | take 9 t == \"Nullable \" || take 9 t == \"Optional \" =\n      SPresent (take 8 t) (if even seed then Nothing\n        else Just (sample (drop 9 t) (seed `div` 2) bits))\n  | isInteger t =\n      let { bounds = integerBounds bits t\n          ; n = case bounds of\n              Just (lo,hi) -> lo + randomN `mod` (hi-lo+1)\n              Nothing -> if t == \"BigUInt\" then randomN\n                else randomN - 2^(255::Int)\n          }\n      in SInteger t n\n  | t == \"Bool\" = SBool (even seed)\n  | t == \"Decimal\" =\n      SDecimal (randomN - 2^(255::Int)) (fromIntegral (seed `mod` 41 - 20))\n  | t == \"Rational\" =\n      reduced ((randomN - 2^(255::Int)) % (randomN `mod` 2^(128::Int) + 1))\n  | t == \"Float32\" = SFloat t (pad 8 (showHex (randomN `mod` 2^(32::Int)) \"\"))\n  | t == \"Float64\" = SFloat t (pad 16 (showHex (randomN `mod` 2^(64::Int)) \"\"))\n  | t == \"Complex64\" || t == \"Complex128\" =\n      let c = if t == \"Complex64\" then \"Float32\" else \"Float64\"\n      in SComplex t (sample c seed bits) (sample c (seed `div` 7) bits)\n  | t == \"Symbol\" = SSymbol (show seed) \"same\"\n  | t `elem` [\"Unit\",\"Null\",\"Undefined\"] = SAbsent t\n  | t `elem` [\"Char\",\"CodePoint\",\"CodeUnit16\"] = SCharacter t (unit randomN)\n  | otherwise = SSequence t (map unit (take (seed `mod` 40) stream))\n  where stream = tail (iterate\n          (\\n -> (n*6364136223846793005+1442695040888963407) `mod` 2^(256::Int))\n          (fromIntegral seed))\n        randomN = stream !! 7\n        maximumUnit = if t == \"Bytes\" then 256\n          else if t `elem` [\"CodeUnit16\",\"Utf16Text\"] then 65536 else 1114112\n        unit n = let c = fromInteger (n `mod` maximumUnit)\n                 in if validUnit t c then c else 0\n        pad n s = replicate (n-length s) '0' ++ s\n\n-- Native support types preserve domains that lack a faithful Prelude type.\nnewtype Decimal = Decimal Rational deriving (Eq, Show)\nnewtype CodePointText = CodePointText [Char] deriving (Eq, Show)\nnewtype Utf16Text = Utf16Text [Word16] deriving (Eq, Show)\n-- Context creation is the only effect needed for fixture Symbol identity.\n-- Equality uses Unique directly, never a potentially colliding hash or label.\nnewtype SymbolContext = SymbolContext Unique deriving (Eq)\ninstance Show SymbolContext where\n  show _ = \"<SymbolContext>\"\n\nnewSymbolContext :: IO SymbolContext\nnewSymbolContext = SymbolContext <$> newUnique\n\nscopeSymbols :: SymbolContext -> Scalar -> Scalar\nscopeSymbols scope value = case value of\n  SSymbol identity description -> SScopedSymbol scope identity description\n  SPresent name payload -> SPresent name (fmap (scopeSymbols scope) payload)\n  SList values -> SList (map (scopeSymbols scope) values)\n  SData tag fields -> SData tag (map (scopeSymbols scope) fields)\n  _ -> value\n\ndata Symbol = Symbol String String | ScopedSymbol SymbolContext String String\n  deriving (Show)\ninstance Eq Symbol where\n  Symbol identity _ == Symbol other _ = identity == other\n  ScopedSymbol scope identity _ == ScopedSymbol otherScope other _ =\n    scope == otherScope && identity == other\n  _ == _ = False\ndata Null = Null deriving (Eq, Show)\ndata Undefined = Undefined deriving (Eq, Show)\ndata Nullable a = NullValue | NullableValue a deriving (Eq, Show)\ndata Optional a = UndefinedValue | OptionalValue a deriving (Eq, Show)\n\nclass Native a where\n  toNative :: String -> Scalar -> Int -> a\n  fromNative :: String -> a -> Int -> Scalar\n\ncheckMachineBits :: Int -> ()\ncheckMachineBits bits\n  | bits == finiteBitSize (0 :: Int) = ()\n  | otherwise = error \"machineBits does not match native architecture\"\n\ninstance Native a => Native [a] where\n  toNative t s bits = case (stripPrefix \"List \" t, validate t s bits) of\n    (Just inner, SList xs) -> map (\\x -> toNative inner x bits) xs\n    _ -> error \"List required\"\n  fromNative t xs bits = case stripPrefix \"List \" t of\n    Just inner -> let result = SList (map (\\x -> fromNative inner x bits) xs)\n                  in forceScalar result `seq` result\n    Nothing -> error \"List required\"\ninstance Native a => Native (Maybe a) where\n  toNative t s bits = case (stripPrefix \"Maybe \" t, validate t s bits) of\n    (Just _, SData \"Maybe::Nothing\" []) -> Nothing\n    (Just inner, SData \"Maybe::Just\" [value]) ->\n      Just (toNative inner value bits)\n    _ -> error \"Maybe required\"\n  fromNative t value bits = case stripPrefix \"Maybe \" t of\n    Just inner -> let result = case value of\n                       Nothing -> SData \"Maybe::Nothing\" []\n                       Just payload ->\n                         SData \"Maybe::Just\" [fromNative inner payload bits]\n                  in forceScalar result `seq` result\n    Nothing -> error \"Maybe required\"\ninstance (Native a, Native b) => Native (Either a b) where\n  toNative t s bits = let (left,right) = eitherArguments t\n    in case validate t s bits of\n    SData \"Either::Left\" [value] -> Left (toNative left value bits)\n    SData \"Either::Right\" [value] -> Right (toNative right value bits)\n    _ -> error \"Either required\"\n  fromNative t value bits =\n    let (left,right) = eitherArguments t\n        result = case value of\n          Left payload -> SData \"Either::Left\" [fromNative left payload bits]\n          Right payload -> SData \"Either::Right\" [fromNative right payload bits]\n    in forceScalar result `seq` result\ninstance Native Scalar where\n  toNative = convert\n  fromNative = validate\ninstance Native Bool where\n  toNative t s bits = truth (validate t s bits)\n  fromNative t x bits = validate t (SBool x) bits\ninstance Native Text where\n  toNative t s bits = case validate t s bits of\n    SSequence _ xs -> T.pack (map chr xs)\n    _ -> error \"Text required\"\n  fromNative t x bits = validate t (textScalar (T.unpack x)) bits\ninstance Native Rational where\n  toNative t s bits = either error id (exactValue (convert t s bits))\n  fromNative t x bits = validate t (reduced x) bits\ninstance Native Float where\n  toNative t s bits = double2Float (floatValue (convert t s bits))\n  fromNative t x bits = validate t (floatScalar t (float2Double x)) bits\ninstance Native Double where\n  toNative t s bits = floatValue (convert t s bits)\n  fromNative t x bits = validate t (floatScalar t x) bits\ninstance Native Int8 where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    _ -> error \"integer required\"\n  fromNative t x bits = validate t (SInteger t (toInteger x)) bits\ninstance Native Int16 where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    _ -> error \"integer required\"\n  fromNative t x bits = validate t (SInteger t (toInteger x)) bits\ninstance Native Int32 where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    _ -> error \"integer required\"\n  fromNative t x bits = validate t (SInteger t (toInteger x)) bits\ninstance Native Int64 where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    _ -> error \"integer required\"\n  fromNative t x bits = validate t (SInteger t (toInteger x)) bits\ninstance Native Word8 where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    _ -> error \"integer required\"\n  fromNative t x bits = validate t (SInteger t (toInteger x)) bits\ninstance Native Word16 where\n  toNative \"CodeUnit16\" s bits = case validate \"CodeUnit16\" s bits of\n    SCharacter _ c -> fromIntegral c\n    _ -> error \"CodeUnit16 required\"\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    SCharacter \"CodeUnit16\" c -> fromIntegral c\n    _ -> error \"Word16 required\"\n  fromNative \"CodeUnit16\" x bits =\n    validate \"CodeUnit16\" (SCharacter \"CodeUnit16\" (fromIntegral x)) bits\n  fromNative t x bits = validate t\n    (if t == \"CodeUnit16\" then SCharacter t (fromIntegral x)\n     else SInteger t (toInteger x)) bits\ninstance Native Word32 where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    _ -> error \"integer required\"\n  fromNative t x bits = validate t (SInteger t (toInteger x)) bits\ninstance Native Word64 where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    _ -> error \"integer required\"\n  fromNative t x bits = validate t (SInteger t (toInteger x)) bits\ninstance Native Integer where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> fromInteger n\n    _ -> error \"integer required\"\n  fromNative t x bits = validate t (SInteger t (toInteger x)) bits\ninstance Native Int where\n  toNative t s bits = if bits /= finiteBitSize (0 :: Int)\n    then error \"machineBits does not match native architecture\"\n    else case convert t s bits of\n      SInteger _ n -> fromInteger n\n      _ -> error \"integer required\"\n  fromNative t x bits = if bits /= finiteBitSize (0 :: Int)\n    then error \"machineBits does not match native architecture\"\n    else validate t (SInteger t (toInteger x)) bits\ninstance Native Word where\n  toNative t s bits = if bits /= finiteBitSize (0 :: Word)\n    then error \"machineBits does not match native architecture\"\n    else case convert t s bits of\n      SInteger _ n -> fromInteger n\n      _ -> error \"integer required\"\n  fromNative t x bits = if bits /= finiteBitSize (0 :: Word)\n    then error \"machineBits does not match native architecture\"\n    else validate t (SInteger t (toInteger x)) bits\n\ninstance Native () where\n  toNative t s bits = validate t s bits `seq` ()\n  fromNative t x bits = x `seq` validate t (SAbsent \"Unit\") bits\n\npad8 :: String -> String\npad8 s = replicate (8-length s) '0' ++ s\n\ninstance Native Char where\n  toNative t s bits = case validate t s bits of\n    SCharacter _ c -> chr c\n    _ -> error \"character required\"\n  fromNative t c bits = validate t (SCharacter t (ord c)) bits\n\ninstance Native (Complex Float) where\n  toNative t s bits = case convert t s bits of\n    SComplex _ r i -> double2Float (floatValue r) :+ double2Float (floatValue i)\n    _ -> error \"complex required\"\n  fromNative t (r :+ i) bits = validate t\n    (SComplex t (floatScalar \"Float32\" (float2Double r))\n      (floatScalar \"Float32\" (float2Double i))) bits\ninstance Native (Complex Double) where\n  toNative t s bits = case convert t s bits of\n    SComplex _ r i -> floatValue r :+ floatValue i\n    _ -> error \"complex required\"\n  fromNative t (r :+ i) bits = validate t\n    (SComplex t (floatScalar \"Float64\" r) (floatScalar \"Float64\" i)) bits\n\ninstance Native ByteString where\n  toNative t s bits = case validate t s bits of\n    SSequence \"Bytes\" xs -> B.pack (map fromIntegral xs)\n    _ -> error \"Bytes required\"\n  fromNative t x bits =\n    validate t (SSequence \"Bytes\" (map fromIntegral (B.unpack x))) bits\n\ninstance Native Decimal where\n  toNative t value bits =\n    Decimal (either error id (exactValue (validate t value bits)))\n  fromNative t (Decimal value) bits =\n    validate t (either error id (decimal value)) bits\n\ninstance Native CodePointText where\n  toNative t value bits = case validate t value bits of\n    SSequence \"CodePointText\" units -> CodePointText (map chr units)\n    _ -> error \"CodePointText required\"\n  fromNative t (CodePointText value) bits =\n    validate t (SSequence \"CodePointText\" (map ord value)) bits\n\ninstance Native Utf16Text where\n  toNative t value bits = case validate t value bits of\n    SSequence \"Utf16Text\" units -> Utf16Text (map fromIntegral units)\n    _ -> error \"Utf16Text required\"\n  fromNative t (Utf16Text value) bits =\n    validate t (SSequence \"Utf16Text\" (map fromIntegral value)) bits\n\ninstance Native Symbol where\n  toNative t value bits = case validate t value bits of\n    SSymbol identity description -> Symbol identity description\n    SScopedSymbol scope identity description ->\n      ScopedSymbol scope identity description\n    _ -> error \"Symbol required\"\n  fromNative t (Symbol identity description) bits =\n    validate t (SSymbol identity description) bits\n  fromNative t (ScopedSymbol scope identity description) bits =\n    validate t (SScopedSymbol scope identity description) bits\n\ninstance Native Null where\n  toNative t value bits = validate t value bits `seq` Null\n  fromNative t value bits = value `seq` validate t (SAbsent \"Null\") bits\n\ninstance Native Undefined where\n  toNative t value bits = validate t value bits `seq` Undefined\n  fromNative t value bits = value `seq` validate t (SAbsent \"Undefined\") bits\n\ninstance Native a => Native (Nullable a) where\n  toNative t value bits = case\n      (stripPrefix \"Nullable \" t, validate t value bits) of\n    (Just _, SPresent \"Nullable\" Nothing) -> NullValue\n    (Just inner, SPresent \"Nullable\" (Just payload)) ->\n      NullableValue (toNative inner payload bits)\n    _ -> error \"Nullable required\"\n  fromNative t value bits = case stripPrefix \"Nullable \" t of\n    Just inner -> let result = case value of\n                       NullValue -> SPresent \"Nullable\" Nothing\n                       NullableValue payload ->\n                         SPresent \"Nullable\"\n                           (Just (fromNative inner payload bits))\n                  in forceScalar result `seq` result\n    _ -> error \"Nullable required\"\n\ninstance Native a => Native (Optional a) where\n  toNative t value bits = case\n      (stripPrefix \"Optional \" t, validate t value bits) of\n    (Just _, SPresent \"Optional\" Nothing) -> UndefinedValue\n    (Just inner, SPresent \"Optional\" (Just payload)) ->\n      OptionalValue (toNative inner payload bits)\n    _ -> error \"Optional required\"\n  fromNative t value bits = case stripPrefix \"Optional \" t of\n    Just inner -> let result = case value of\n                       UndefinedValue -> SPresent \"Optional\" Nothing\n                       OptionalValue payload ->\n                         SPresent \"Optional\"\n                           (Just (fromNative inner payload bits))\n                  in forceScalar result `seq` result\n    _ -> error \"Optional required\"\n\n-- An abstract integer result erases the native width without losing its value.\nnewtype IntegerValue = IntegerValue Integer deriving (Eq, Show)\nintegerValue :: Integral a => a -> IntegerValue\nintegerValue = IntegerValue . toInteger\ninstance Native IntegerValue where\n  toNative t s bits = case convert t s bits of\n    SInteger _ n -> IntegerValue n\n    _ -> error \"integer required\"\n  fromNative t (IntegerValue n) bits = validate t (SInteger t n) bits\n\ndata Domain = Domain ([Scalar] -> Int -> [Scalar]) ([Scalar] -> Bool)\ndomainCandidates :: String -> Int -> Int -> [(String,Scalar)]\n                 -> [Scalar] -> [Scalar]\ndomainCandidates t seed bits restrictions hints = rotate values where\n  rotate [] = []\n  rotate xs = let offset = seed `mod` length xs\n              in drop offset xs ++ take offset xs\n  values | isInteger t = case limits of\n             (Just lo,Just hi) | lo > hi -> []\n             (lo,hi) ->\n               let { lower = maybe (min 0 (maybe 0 id hi) - 2^(256::Int)) id lo\n                   ; upper = maybe (max 0 (maybe 0 id lo) + 2^(256::Int)) id hi\n                   ; ns = [lower,upper,0,1,-1,lower+1,upper-1] ++\n                       [lower + random j `mod` (upper-lower+1) | j <- [0..7]]\n                   }\n               in [SInteger t n | SInteger _ n <- hints ++ map (SInteger t) ns,\n                                   n >= lower, n <= upper]\n         | otherwise =\n             [v | hint <- hints, Right v <- [convertScalar bits t hint]] ++\n             [sample t (seed+j*7919) bits | j <- [0..7]]\n  initial = case integerBounds bits t of\n    Just (lo,hi) -> (Just lo,Just hi)\n    Nothing -> (if t == \"BigUInt\" then Just 0 else Nothing,Nothing)\n  limits = foldl restrict initial restrictions\n  restrict (lo,hi) (op,v) =\n    let { r = either error id (exactValue v)\n        ; lower = if op == \">\" then floor r + 1 else ceiling r\n        ; upper = if op == \"<\" then ceiling r - 1 else floor r\n        }\n    in (if op `elem` [\">\",\">=\",\"==\"]\n          then Just (maybe lower (max lower) lo) else lo,\n        if op `elem` [\"<\",\"<=\",\"==\"]\n          then Just (maybe upper (min upper) hi) else hi)\n  random j = (fromIntegral seed * 6364136223846793005 +\n              fromIntegral j * 1442695040888963407) ^ (8::Int)\n\ngenerateTuple :: [Domain] -> Int -> Int -> [Scalar] -> Either String [Scalar]\ngenerateTuple domains seed attempts prefix = retry 0 where\n  retry used\n    | used >= attempts = Left (\"refinement-generation-exhausted after \" ++\n        show used ++ \" attempts; prefix=\" ++ show prefix ++\n        \"; seed=\" ++ show seed)\n    | otherwise = case search used prefix of\n        (Just result,_) -> Right result\n        (Nothing,next) -> retry next\n  search used values | length values == length domains = (Just values,used)\n                     | used >= attempts = (Nothing,used)\n                     | otherwise =\n                         let Domain candidates accept = domains !! length values\n                         in walk accept (used+1) values\n                           (candidates values (seed+(used+1)*7919))\n  walk _ used _ [] = (Nothing,used)\n  walk accept used values (v:vs)\n    | used >= attempts = (Nothing,used)\n    | not (accept (values++[v])) = walk accept (used+1) values vs\n    | otherwise = case search (used+1) (values++[v]) of\n        (Just result,next) -> (Just result,next)\n        (Nothing,next) -> walk accept next values vs\n\ncontract :: String -> Bool -> Scalar -> Scalar\ncontract context condition result = if condition then result else error context\n\nrefinedCase :: [Domain] -> Int -> Int -> Int\n            -> ([Scalar] -> IO ()) -> String -> IO ()\nrefinedCase domains seed attempts shrinks check context = do\n  let values = either (error . ((context ++ \": \") ++)) id\n        (generateTuple domains seed attempts [])\n  outcome <- capture check values\n  case outcome of\n    Nothing -> pure ()\n    Just original -> do\n      (best,_) <- foldM shrinkAt (values,shrinks) [0..length values-1]\n      ioError (userError (context ++ \": \" ++ original ++\n        \"; refined counterexample=\" ++ show best ++ \"; seed=\" ++ show seed))\n  where\n    capture f xs = (f xs >> pure Nothing) `catch`\n      (\\e -> pure (Just (displayException (e :: SomeException))))\n    shrinkAt state@(best,_) i =\n      let { Domain candidates _ = domains !! i\n          ; additional = case best !! i of\n              SInteger t n -> map (SInteger t)\n                (0:signum n:takeWhile ((>1) . abs)\n                  (tail (iterate (`quot` 2) n)))\n              _ -> []\n          }\n      in foldM (tryCandidate i) state\n        (additional ++ candidates (take i best) 0)\n    tryCandidate i state@(best,budget) candidate\n      | budget <= 0 = pure state\n      | complexity candidate >= complexity (best !! i) = pure (best,budget-1)\n      | otherwise = do\n          let prefix = take i best ++ [candidate]\n              Domain _ accept = domains !! i\n          if not (accept prefix) then pure (best,budget-1)\n          else case generateTuple domains seed (min attempts 100) prefix of\n            Left _ -> pure (best,budget-1)\n            Right trial -> do\n              failed <- capture check trial\n              pure ((case failed of Just _ -> trial; Nothing -> best),budget-1)\n\ncomplexity :: Scalar -> Integer\ncomplexity (SInteger _ n) = abs n\ncomplexity (SBool b) = if b then 1 else 0\ncomplexity (SPresent _ Nothing) = 0\ncomplexity (SPresent _ (Just v)) = 1 + complexity v\ncomplexity (SSequence _ xs) = fromIntegral (length xs)\ncomplexity (SCharacter _ c) = fromIntegral c\ncomplexity v@(SFloat _ _) = toInteger (castDoubleToWord64 (abs (floatValue v)))\ncomplexity (SComplex _ r i) = complexity r + complexity i\ncomplexity (SAbsent _) = 0\ncomplexity (SSymbol _ _) = 1\ncomplexity (SScopedSymbol _ _ _) = 1\ncomplexity v = let r = either error id (exactValue v)\n               in abs (numerator r) + denominator r - 1\n\nbool :: Bool -> Scalar\nbool = SBool\n\n-- Standalone contracts must observe their result even when\n-- the predicate is true.\nforceScalar :: Scalar -> ()\nforceScalar (SInteger _ n) = n `seq` ()\nforceScalar (SBool b) = b `seq` ()\nforceScalar (SDecimal c e) = c `seq` e `seq` ()\nforceScalar (SRational n d) = n `seq` d `seq` ()\nforceScalar (SFloat _ bs) = foldr seq () bs\nforceScalar (SComplex _ r i) = forceScalar r `seq` forceScalar i\nforceScalar (SSequence _ xs) = foldr seq () xs\nforceScalar (SList xs) =\n  foldr (\\value rest -> forceScalar value `seq` rest) () xs\nforceScalar (SData tag xs) = foldr seq () tag `seq`\n  foldr (\\value rest -> forceScalar value `seq` rest) () xs\nforceScalar (SCharacter _ c) = c `seq` ()\nforceScalar (SSymbol ident description) =\n  foldr seq () ident `seq` foldr seq () description\nforceScalar (SScopedSymbol scope ident description) =\n  scope `seq` foldr seq () ident `seq` foldr seq () description\nforceScalar (SPresent _ (Just v)) = forceScalar v\nforceScalar _ = ()\n"
runtimeSource "haskell-schema" = "-- Checked structural values; no property-framework dependencies.\nmodule LawSpecSchema\n  ( TypeRef(..), Field(..), Constructor(..), Definition(..), Schema\n  , FieldPredicate, ValidationFailure(..), failureMessage\n  , create, createWithContracts, hasContracts, checkType\n  , constructors, substitute\n  , validate, validateWith, validateChecked\n  , allPayloads, allPayloadsWith\n  , construct, constructWith, equal, equalWith, match, matchWith\n  ) where\n\nimport Control.Monad (unless, forM_, zipWithM)\nimport Data.List (find, nub)\nimport qualified LawSpecRuntime as LS\n\ndata TypeRef = Parameter Int | Named String [TypeRef]\n  deriving (Eq, Ord, Show)\ndata Field = Field String TypeRef deriving (Eq, Show)\ndata Constructor = Constructor String [Field] deriving (Eq, Show)\ndata Definition = Definition String Int [Constructor] deriving (Eq, Show)\ntype FieldPredicate =\n  Schema -> [TypeRef] -> [LS.Scalar] -> Int -> Maybe LS.SymbolContext\n  -> Either String Bool\n\ndata ValidationFailure\n  = Rejected String\n  | EvaluationFailure String\n  deriving (Eq, Show)\n\nfailureMessage :: ValidationFailure -> String\nfailureMessage (Rejected message) = message\nfailureMessage (EvaluationFailure message) = message\n\ndata Schema = Schema [Definition] [(String, Int)] [(String, [FieldPredicate])]\n\nhasContracts :: Schema -> Bool\nhasContracts (Schema _ _ contracts) = any (not . null . snd) contracts\n\ncreate :: [Definition] -> [String] -> Either String Schema\ncreate definitions primitives = createWithContracts definitions primitives []\n\ncreateWithContracts :: [Definition] -> [String] -> [(String, [FieldPredicate])]\n                    -> Either String Schema\ncreateWithContracts definitions primitives contracts = do\n  let builtins = [(name, 0) | name <- primitives] ++\n        [(\"List\", 1), (\"Maybe\", 1), (\"Either\", 2),\n         (\"Nullable\", 1), (\"Optional\", 1)]\n      arities = builtins ++\n        [(name, count) | Definition name count _ <- definitions]\n      names = map fst arities\n      tags = [tag | Definition _ _ variants <- definitions,\n                    Constructor tag _ <- variants]\n      schema = Schema definitions arities contracts\n  unless (all (not . null) names && length names == length (nub names))\n    (Left \"duplicate or empty schema type\")\n  unless (all (not . null) tags && length tags == length (nub tags))\n    (Left \"duplicate or empty constructor identity\")\n  let contractTags = map fst contracts\n  unless (length contractTags == length (nub contractTags) &&\n          all (`elem` tags) contractTags)\n    (Left \"duplicate or unknown constructor contract\")\n  forM_ definitions $ \\(Definition name parameters variants) -> do\n    unless (parameters >= 0) (Left (\"negative parameter count: \" ++ name))\n    forM_ variants $ \\(Constructor tag fields) -> do\n      let fieldNames = [field | Field field _ <- fields]\n      unless (all (not . null) fieldNames &&\n              length fieldNames == length (nub fieldNames))\n        (Left (\"duplicate or empty field: \" ++ tag))\n      forM_ fields $ \\(Field _ typeRef) -> checkType schema parameters typeRef\n  pure schema\n\ncheckType :: Schema -> Int -> TypeRef -> Either String ()\ncheckType _ count (Parameter index) =\n  unless (index >= 0 && index < count) (Left \"unbound schema parameter\")\ncheckType schema@(Schema _ arities _) count (Named name arguments) = do\n  unless (lookup name arities == Just (length arguments))\n    (Left (\"unknown type or wrong arity: \" ++ name))\n  mapM_ (checkType schema count) arguments\n\nsubstitute :: [TypeRef] -> TypeRef -> TypeRef\nsubstitute arguments (Parameter index) = arguments !! index\nsubstitute arguments (Named name children) =\n  Named name (map (substitute arguments) children)\n\nconstructors :: Schema -> TypeRef -> Either String (Maybe [Constructor])\nconstructors schema@(Schema definitions _ _) typeRef = do\n  checkType schema 0 typeRef\n  case typeRef of\n    Named name arguments -> case\n        find (\\(Definition n _ _) -> n == name) definitions of\n      Nothing -> pure Nothing\n      Just (Definition _ _ variants) -> pure (Just\n        [Constructor tag [Field field (substitute arguments ty) |\n                          Field field ty <- fields] |\n         Constructor tag fields <- variants])\n    Parameter _ -> Left \"unbound schema parameter\"\n\nvalidate :: Schema -> TypeRef -> Int -> LS.Scalar -> Either String LS.Scalar\nvalidate schema = validateWith Nothing schema\n\nvalidateWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int -> LS.Scalar\n             -> Either String LS.Scalar\nvalidateWith scope schema typeRef bits value =\n  either (Left . failureMessage) Right\n    (validateChecked scope schema typeRef bits value)\n\nfromEvaluation :: Either String a -> Either ValidationFailure a\nfromEvaluation = either (Left . EvaluationFailure) Right\n\nfailureContext :: String -> Either ValidationFailure a\n               -> Either ValidationFailure a\nfailureContext label = either (Left . decorate) Right\n  where\n    decorate (Rejected message) = Rejected (label ++ \": \" ++ message)\n    decorate (EvaluationFailure message) =\n      EvaluationFailure (label ++ \": \" ++ message)\n\nvalidateChecked :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int\n                -> LS.Scalar -> Either ValidationFailure LS.Scalar\nvalidateChecked scope schema@(Schema _ _ contracts) typeRef bits value = do\n  unless (bits == 32 || bits == 64)\n    (Left (EvaluationFailure \"machineBits must be 32 or 64\"))\n  variants <- fromEvaluation (constructors schema typeRef)\n  case variants of\n    Just choices -> dataValue choices\n    Nothing -> case (typeRef, value) of\n      (Named \"List\" [element], LS.SList values) ->\n        LS.SList <$> zipWithM (\\index child ->\n          failureContext (\"List[\" ++ show index ++ \"]\")\n            (validateChecked scope schema element bits child))\n          [0 :: Int ..] values\n      (Named \"Maybe\" [element], _) -> dataValue\n        [Constructor \"Maybe::Nothing\" [],\n         Constructor \"Maybe::Just\" [Field \"value\" element]]\n      (Named \"Either\" [left, right], _) -> dataValue\n        [Constructor \"Either::Left\" [Field \"value\" left],\n         Constructor \"Either::Right\" [Field \"value\" right]]\n      (Named name [element], LS.SPresent wrapper payload)\n        | name `elem` [\"Nullable\", \"Optional\"] && name == wrapper ->\n          LS.SPresent wrapper <$> traverse\n            (failureContext name . validateChecked scope schema element bits)\n            payload\n      (Named name [], _) | scalarPayload value && LS.scalarName value == name ->\n        fromEvaluation (LS.validateScalar bits value)\n      _ -> Left (EvaluationFailure\n        (\"invalid representation for \" ++ show typeRef))\n  where\n    scalarPayload LS.SData{} = False\n    scalarPayload LS.SList{} = False\n    scalarPayload LS.SPresent{} = False\n    scalarPayload _ = True\n    dataValue choices = case value of\n      LS.SData tag fields -> case\n          find (\\(Constructor name _) -> name == tag) choices of\n        Nothing -> Left (EvaluationFailure\n          (\"unknown constructor \" ++ tag ++ \" for \" ++ show typeRef))\n        Just (Constructor _ expected) -> do\n          unless (length fields == length expected)\n            (Left (EvaluationFailure (\"wrong field count: \" ++ tag)))\n          checked <- zipWithM\n            (\\(Field name ty) field -> failureContext (tag ++ \".\" ++ name)\n              (validateChecked scope schema ty bits field)) expected fields\n          let arguments = case typeRef of\n                Named _ values -> values\n                Parameter _ -> []\n              predicates = maybe [] id (lookup tag contracts)\n          forM_ (zip [1 :: Int ..] predicates) $ \\(index, predicate) ->\n            failureContext (tag ++ \" predicate \" ++ show index) $ do\n              accepted <- fromEvaluation\n                (predicate schema arguments checked bits scope)\n              unless accepted\n                (Left (Rejected \"constructor field contract rejected\"))\n          pure (LS.SData tag checked)\n      _ -> Left (EvaluationFailure\n        (\"expected constructor payload for \" ++ show typeRef))\n\n\n-- Recipes follow declared parameters, not equality of instantiated types.\ndata PayloadPlan\n  = IgnorePayload\n  | PayloadSlot Int\n  | PayloadApplication String [PayloadPlan]\n\npayloadRecipe :: [PayloadPlan] -> TypeRef -> PayloadPlan\npayloadRecipe arguments (Parameter index) = arguments !! index\npayloadRecipe arguments (Named name children) =\n  let plans = map (payloadRecipe arguments) children\n  in if all ignored plans then IgnorePayload else PayloadApplication name plans\n  where\n    ignored IgnorePayload = True\n    ignored _ = False\n\nallPayloads :: Schema -> TypeRef -> Int -> LS.Scalar\n            -> [LS.Scalar -> Either String LS.Scalar]\n            -> Either String LS.Scalar\nallPayloads = allPayloadsWith Nothing\n\n-- Either sequences full representation/contract validation before callbacks.\nallPayloadsWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int\n                -> LS.Scalar -> [LS.Scalar -> Either String LS.Scalar]\n                -> Either String LS.Scalar\nallPayloadsWith scope schema@(Schema definitions _ _) typeRef bits value\n                predicates = do\n  checkType schema 0 typeRef\n  (name, arguments) <- case typeRef of\n    Named name arguments\n      | name `elem` [\"List\", \"Maybe\", \"Either\", \"Nullable\", \"Optional\"] ||\n        any (\\(Definition n _ _) -> n == name) definitions ->\n          Right (name, arguments)\n    _ -> Left \"payload predicates require a data type\"\n  unless (length arguments == length predicates)\n    (Left \"payload predicate arity mismatch\")\n  checked <- validateWith scope schema typeRef bits value\n  LS.SBool <$> walk\n    (PayloadApplication name (map PayloadSlot [0 .. length arguments - 1]))\n    checked\n  where\n    context label = either (Left . ((label ++ \": \") ++)) Right\n    every [] = Right True\n    every (step : steps) = do\n      accepted <- step\n      if accepted then every steps else Right False\n    walk IgnorePayload _ = Right True\n    walk (PayloadSlot index) stored = do\n      result <- (predicates !! index) stored\n      case result of\n        LS.SBool accepted -> Right accepted\n        _ -> Left \"Bool required in payload predicate\"\n    walk (PayloadApplication name arguments) stored = case (name, stored) of\n      (\"List\", LS.SList values) -> every\n        [context (\"List[\" ++ show index ++ \"]\") (walk (head arguments) child)\n        | (index, child) <- zip [0 :: Int ..] values]\n      (_, LS.SPresent wrapper payload)\n        | name `elem` [\"Nullable\", \"Optional\"] && wrapper == name ->\n          maybe (Right True)\n            (context (name ++ \".value\") . walk (head arguments)) payload\n      (\"Maybe\", LS.SData \"Maybe::Nothing\" []) -> Right True\n      (\"Maybe\", LS.SData \"Maybe::Just\" [child]) ->\n        context \"Maybe::Just.value\" (walk (head arguments) child)\n      (\"Either\", LS.SData tag [child]) ->\n        let index = if tag == \"Either::Left\" then 0 else 1\n        in context (tag ++ \".value\") (walk (arguments !! index) child)\n      (_, LS.SData tag fields) -> do\n        variants <- case find (\\(Definition n _ _) -> n == name) definitions of\n          Just (Definition _ _ variants) -> Right variants\n          Nothing -> Left \"unknown checked payload type\"\n        expected <- case find (\\(Constructor n _) -> n == tag) variants of\n          Just (Constructor _ expected) -> Right expected\n          Nothing -> Left \"unknown checked payload constructor\"\n        every [context (tag ++ \".\" ++ field)\n          (walk (payloadRecipe arguments ty) child)\n          | (Field field ty, child) <- zip expected fields]\n      _ -> Left \"invalid checked payload representation\"\n\nconstruct :: Schema -> TypeRef -> Int -> String -> [LS.Scalar]\n          -> Either String LS.Scalar\nconstruct = constructWith Nothing\n\nconstructWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int\n              -> String -> [LS.Scalar] -> Either String LS.Scalar\nconstructWith scope schema typeRef bits tag fields = case typeRef of\n  Named \"List\" [_] -> case (tag, fields) of\n    (\"List::Nil\", []) -> validateWith scope schema typeRef bits (LS.SList [])\n    (\"List::Cons\", [headValue, tailValue]) -> do\n      checked <- validateWith scope schema typeRef bits tailValue\n      case checked of\n        LS.SList values -> validateWith scope schema typeRef bits\n          (LS.SList (headValue : values))\n        _ -> Left \"invalid checked List representation\"\n    _ -> Left \"invalid List constructor or field count\"\n  _ -> validateWith scope schema typeRef bits (LS.SData tag fields)\n\nequal :: Schema -> TypeRef -> Int -> LS.Scalar -> LS.Scalar\n      -> Either String Bool\nequal = equalWith Nothing\n\nequalWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int\n          -> LS.Scalar -> LS.Scalar -> Either String Bool\nequalWith scope schema typeRef bits left right = do\n  a <- validateWith scope schema typeRef bits left\n  b <- validateWith scope schema typeRef bits right\n  pure (LS.equal a b)\n\n-- Validation precedes branch selection; unselected branch functions stay lazy.\nmatch :: Schema -> TypeRef -> Int -> LS.Scalar\n      -> [(String, [LS.Scalar] -> a)] -> Either String a\nmatch = matchWith Nothing\n\nmatchWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int -> LS.Scalar\n          -> [(String, [LS.Scalar] -> a)] -> Either String a\nmatchWith scope schema typeRef bits value branches = do\n  checked <- validateWith scope schema typeRef bits value\n  (tag, fields) <- case checked of\n    LS.SData name payload -> pure (name, payload)\n    LS.SList [] -> pure (\"List::Nil\", [])\n    LS.SList (headValue : tailValue) ->\n      pure (\"List::Cons\", [headValue, LS.SList tailValue])\n    _ -> Left \"matching requires a data constructor\"\n  case lookup tag branches of\n    Nothing -> Left (\"missing checked match branch: \" ++ tag)\n    Just action -> pure (action fields)\n"
runtimeSource "haskell-codecs" = "-- Typed native bridges with checked, contextual conversions.\nmodule LawSpecCodecs\n  ( Codec, reference, decode, encode, codec, codecWith, context\n  , integerCodec, boolCodec, decimalCodec, rationalCodec\n  , float32Codec, float64Codec, complex64Codec, complex128Codec\n  , characterCodec, codeUnitCodec, textCodec, bytesCodec\n  , codePointTextCodec, utf16TextCodec, symbolCodec\n  , unitCodec, nullCodec, undefinedCodec\n  , listCodec, maybeCodec, eitherCodec, nullableCodec, optionalCodec\n  , listCodecWith, maybeCodecWith, eitherCodecWith\n  , nullableCodecWith, optionalCodecWith\n  ) where\n\nimport Control.Monad (unless, foldM, zipWithM)\nimport Data.Bits (finiteBitSize)\nimport Data.Char (ord)\nimport Data.Complex (Complex((:+)))\nimport Data.Ratio (numerator, denominator)\nimport Data.Word (Word16)\nimport qualified Data.ByteString as B\nimport qualified Data.Text as T\nimport GHC.Float (float2Double)\nimport qualified LawSpecRuntime as LS\nimport qualified LawSpecSchema as S\n\ndata Codec a = Codec\n  { reference :: S.TypeRef\n  , decode :: LS.Scalar -> Either String a\n  , encode :: a -> Either String LS.Scalar\n  }\n\ncontext :: String -> Either String a -> Either String a\ncontext label = either (Left . ((label ++ \": \") ++)) Right\n\ncheckNativeProfile :: S.Schema -> S.TypeRef -> Int -> Either String ()\ncheckNativeProfile schema typeRef bits = do\n  unless (bits == 32 || bits == 64) (Left \"machineBits must be 32 or 64\")\n  S.checkType schema 0 typeRef\n  _ <- visit [] typeRef\n  pure ()\n  where\n    visit _ (S.Parameter _) = Left \"unbound native type parameter\"\n    visit seen current@(S.Named name arguments) = do\n      previous <- foldM visit seen arguments\n      unless (name `notElem` [\"IntSize\", \"UIntSize\", \"UIntPtr\"] ||\n              bits == finiteBitSize (0 :: Int))\n        (Left \"machineBits does not match native architecture\")\n      if name `elem` previous then pure previous else do\n        variants <- S.constructors schema current\n        let fields = [ty | S.Constructor _ items <- maybe [] id variants,\n                           S.Field _ ty <- items]\n        foldM visit (name : previous) fields\n\ncodec :: S.Schema -> Int -> S.TypeRef\n      -> (LS.Scalar -> Either String a)\n      -> (a -> Either String LS.Scalar) -> Codec a\ncodec = codecWith Nothing\n\ncodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int -> S.TypeRef\n          -> (LS.Scalar -> Either String a)\n          -> (a -> Either String LS.Scalar) -> Codec a\ncodecWith scope schema bits typeRef decoder encoder =\n  Codec typeRef fromValue toValue\n  where\n    checked = checkNativeProfile schema typeRef bits\n    fromValue value = context (show typeRef) $ do\n      checked\n      validated <- S.validateWith scope schema typeRef bits value\n      decoder validated\n    toValue value = context (show typeRef) $ do\n      checked\n      encoded <- encoder value\n      S.validateWith scope schema typeRef bits encoded\n\nscalar :: LS.Native a => S.Schema -> Int -> String\n       -> (a -> Either String LS.Scalar) -> Codec a\nscalar schema bits name encoder = codec schema bits (S.Named name [])\n  (\\value -> Right (LS.toNative name value bits)) encoder\n\nintegerCodec :: (Integral a, LS.Native a)\n             => S.Schema -> Int -> String -> Codec a\nintegerCodec schema bits name = scalar schema bits name\n  (Right . LS.SInteger name . toInteger)\n\nboolCodec :: S.Schema -> Int -> Codec Bool\nboolCodec schema bits = scalar schema bits \"Bool\" (Right . LS.SBool)\n\ndecimalCodec :: S.Schema -> Int -> Codec LS.Decimal\ndecimalCodec schema bits = scalar schema bits \"Decimal\"\n  (\\(LS.Decimal value) -> LS.decimal value)\n\nrationalCodec :: S.Schema -> Int -> Codec Rational\nrationalCodec schema bits = scalar schema bits \"Rational\"\n  (\\value -> Right (LS.SRational (numerator value) (denominator value)))\n\nfloat32Codec :: S.Schema -> Int -> Codec Float\nfloat32Codec schema bits = scalar schema bits \"Float32\"\n  (Right . LS.floatScalar \"Float32\" . float2Double)\n\nfloat64Codec :: S.Schema -> Int -> Codec Double\nfloat64Codec schema bits = scalar schema bits \"Float64\"\n  (Right . LS.floatScalar \"Float64\")\n\ncomplex64Codec :: S.Schema -> Int -> Codec (Complex Float)\ncomplex64Codec schema bits = scalar schema bits \"Complex64\"\n  (\\(r :+ i) -> Right (LS.SComplex \"Complex64\"\n    (LS.floatScalar \"Float32\" (float2Double r))\n    (LS.floatScalar \"Float32\" (float2Double i))))\n\ncomplex128Codec :: S.Schema -> Int -> Codec (Complex Double)\ncomplex128Codec schema bits = scalar schema bits \"Complex128\"\n  (\\(r :+ i) -> Right (LS.SComplex \"Complex128\"\n    (LS.floatScalar \"Float64\" r) (LS.floatScalar \"Float64\" i)))\n\ncharacterCodec :: S.Schema -> Int -> String -> Codec Char\ncharacterCodec schema bits name = scalar schema bits name\n  (Right . LS.SCharacter name . ord)\n\ncodeUnitCodec :: S.Schema -> Int -> Codec Word16\ncodeUnitCodec schema bits = scalar schema bits \"CodeUnit16\"\n  (Right . LS.SCharacter \"CodeUnit16\" . fromIntegral)\n\ntextCodec :: S.Schema -> Int -> Codec T.Text\ntextCodec schema bits = scalar schema bits \"Text\"\n  (Right . LS.SSequence \"Text\" . map ord . T.unpack)\n\nbytesCodec :: S.Schema -> Int -> Codec B.ByteString\nbytesCodec schema bits = scalar schema bits \"Bytes\"\n  (Right . LS.SSequence \"Bytes\" . map fromIntegral . B.unpack)\n\ncodePointTextCodec :: S.Schema -> Int -> Codec LS.CodePointText\ncodePointTextCodec schema bits = scalar schema bits \"CodePointText\"\n  (\\(LS.CodePointText value) ->\n    Right (LS.SSequence \"CodePointText\" (map ord value)))\n\nutf16TextCodec :: S.Schema -> Int -> Codec LS.Utf16Text\nutf16TextCodec schema bits = scalar schema bits \"Utf16Text\"\n  (\\(LS.Utf16Text value) ->\n    Right (LS.SSequence \"Utf16Text\" (map fromIntegral value)))\n\nsymbolCodec :: S.Schema -> Int -> Codec LS.Symbol\nsymbolCodec schema bits = scalar schema bits \"Symbol\"\n  encodeSymbol\n  where\n    encodeSymbol (LS.Symbol identity description) =\n      Right (LS.SSymbol identity description)\n    encodeSymbol (LS.ScopedSymbol scope identity description) =\n      Right (LS.SScopedSymbol scope identity description)\n\nunitCodec :: S.Schema -> Int -> Codec ()\nunitCodec schema bits = scalar schema bits \"Unit\"\n  (\\() -> Right (LS.SAbsent \"Unit\"))\n\nnullCodec :: S.Schema -> Int -> Codec LS.Null\nnullCodec schema bits = scalar schema bits \"Null\"\n  (\\LS.Null -> Right (LS.SAbsent \"Null\"))\n\nundefinedCodec :: S.Schema -> Int -> Codec LS.Undefined\nundefinedCodec schema bits = scalar schema bits \"Undefined\"\n  (\\LS.Undefined -> Right (LS.SAbsent \"Undefined\"))\n\nlistCodec :: S.Schema -> Int -> Codec a -> Codec [a]\nlistCodec = listCodecWith Nothing\n\nlistCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n              -> Codec a -> Codec [a]\nlistCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named \"List\" [reference element]) fromValue toValue\n  where\n    fromValue (LS.SList values) = zipWithM\n      (\\index value -> context (\"List[\" ++ show index ++ \"]\")\n        (decode element value)) [0 :: Int ..] values\n    fromValue _ = Left \"invalid checked List\"\n    toValue values = LS.SList <$> zipWithM\n      (\\index value -> context (\"List[\" ++ show index ++ \"]\")\n        (encode element value)) [0 :: Int ..] values\n\nmaybeCodec :: S.Schema -> Int -> Codec a -> Codec (Maybe a)\nmaybeCodec = maybeCodecWith Nothing\n\nmaybeCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n               -> Codec a -> Codec (Maybe a)\nmaybeCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named \"Maybe\" [reference element]) fromValue toValue\n  where\n    fromValue (LS.SData \"Maybe::Nothing\" []) = Right Nothing\n    fromValue (LS.SData \"Maybe::Just\" [value]) =\n      Just <$> context \"Maybe::Just.value\" (decode element value)\n    fromValue _ = Left \"invalid checked Maybe\"\n    toValue Nothing = Right (LS.SData \"Maybe::Nothing\" [])\n    toValue (Just value) = do\n      field <- context \"Maybe::Just.value\" (encode element value)\n      pure (LS.SData \"Maybe::Just\" [field])\n\neitherCodec :: S.Schema -> Int -> Codec a -> Codec b -> Codec (Either a b)\neitherCodec = eitherCodecWith Nothing\n\neitherCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n                -> Codec a -> Codec b -> Codec (Either a b)\neitherCodecWith scope schema bits left right = codecWith scope schema bits\n  (S.Named \"Either\" [reference left, reference right]) fromValue toValue\n  where\n    fromValue (LS.SData \"Either::Left\" [value]) =\n      Left <$> context \"Either::Left.value\" (decode left value)\n    fromValue (LS.SData \"Either::Right\" [value]) =\n      Right <$> context \"Either::Right.value\" (decode right value)\n    fromValue _ = Left \"invalid checked Either\"\n    toValue (Left value) = do\n      field <- context \"Either::Left.value\" (encode left value)\n      pure (LS.SData \"Either::Left\" [field])\n    toValue (Right value) = do\n      field <- context \"Either::Right.value\" (encode right value)\n      pure (LS.SData \"Either::Right\" [field])\n\nnullableCodec :: S.Schema -> Int -> Codec a -> Codec (LS.Nullable a)\nnullableCodec = nullableCodecWith Nothing\n\nnullableCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n                  -> Codec a -> Codec (LS.Nullable a)\nnullableCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named \"Nullable\" [reference element]) fromValue toValue\n  where\n    fromValue (LS.SPresent \"Nullable\" Nothing) = Right LS.NullValue\n    fromValue (LS.SPresent \"Nullable\" (Just value)) =\n      LS.NullableValue <$> context \"Nullable.value\" (decode element value)\n    fromValue _ = Left \"invalid checked Nullable\"\n    toValue LS.NullValue = Right (LS.SPresent \"Nullable\" Nothing)\n    toValue (LS.NullableValue value) = do\n      field <- context \"Nullable.value\" (encode element value)\n      pure (LS.SPresent \"Nullable\" (Just field))\n\noptionalCodec :: S.Schema -> Int -> Codec a -> Codec (LS.Optional a)\noptionalCodec = optionalCodecWith Nothing\n\noptionalCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n                  -> Codec a -> Codec (LS.Optional a)\noptionalCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named \"Optional\" [reference element]) fromValue toValue\n  where\n    fromValue (LS.SPresent \"Optional\" Nothing) = Right LS.UndefinedValue\n    fromValue (LS.SPresent \"Optional\" (Just value)) =\n      LS.OptionalValue <$> context \"Optional.value\" (decode element value)\n    fromValue _ = Left \"invalid checked Optional\"\n    toValue LS.UndefinedValue = Right (LS.SPresent \"Optional\" Nothing)\n    toValue (LS.OptionalValue value) = do\n      field <- context \"Optional.value\" (encode element value)\n      pure (LS.SPresent \"Optional\" (Just field))\n"
runtimeSource "haskell-data-strategies" = "-- Native Hedgehog generation and shrinking for checked Core schemas.\nmodule LawSpecDataStrategies\n  (strategy, checkedStrategy, checkedStrategyWith, primitiveStrategy\n  , NativeFactory, nativeValues, nativeArguments) where\n\nimport Control.Monad (unless, when, foldM)\nimport Control.Monad.State.Strict (StateT, evalStateT, get, modify, lift)\nimport Data.Maybe (catMaybes)\nimport Numeric (showHex)\nimport Data.Char (chr)\nimport Data.Ratio (numerator, denominator, (%))\nimport qualified Data.Map.Strict as Map\nimport Hedgehog (Gen)\nimport qualified Hedgehog.Gen as Gen\nimport qualified Hedgehog.Range as Range\nimport qualified LawSpecRuntime as LS\nimport qualified LawSpecSchema as S\nimport qualified LawSpecCodecs as Codec\n\n-- Factories return native Hedgehog trees; fmap preserves their shrink structure.\ntype NativeFactory = S.TypeRef -> [Gen LS.Scalar]\n                   -> Either String (Gen LS.Scalar)\n\nnativeValues :: Codec.Codec a -> Gen a -> Gen LS.Scalar\nnativeValues codec = fmap $ \\value ->\n  case Codec.encode codec value of\n    Left message -> error (\"native generator: \" ++ message)\n    Right logical -> LS.forceScalar logical `seq` logical\n\nnativeArguments :: Codec.Codec a -> Gen LS.Scalar -> Gen a\nnativeArguments codec = fmap $ \\value ->\n  either (error . (\"native generator argument: \" ++)) id\n    (Codec.decode codec value)\n\ntype Cache = Map.Map (S.TypeRef, Int) (Maybe (Gen LS.Scalar))\ntype Build = StateT Cache (Either String)\n\nstrategy :: S.Schema -> S.TypeRef -> Int -> Int\n         -> (String -> Either String (Gen LS.Scalar))\n         -> Either String (Gen LS.Scalar)\nstrategy schema reference bits budget scalar = do\n  when (S.hasContracts schema)\n    (Left \"constructor contracts require checked strategies\")\n  buildStrategy schema reference bits budget scalar (\\_ _ -> id)\n\n-- Predicate failures are native discards. Evaluation errors remain exceptions,\n-- which Hedgehog reports as property failures rather than retrying them.\n-- filterT prunes rejected shrink subtrees: searching every descendant of a\n-- sparse identity predicate can otherwise make shrinking effectively unbounded.\ncheckedStrategy :: S.Schema -> S.TypeRef -> Int -> Int -> Maybe LS.SymbolContext\n                -> [LS.Scalar] -> (String -> Either String (Gen LS.Scalar))\n                -> Either String (Gen LS.Scalar)\ncheckedStrategy = checkedStrategyWith []\n\ncheckedStrategyWith :: [(String, NativeFactory)]\n                    -> S.Schema -> S.TypeRef -> Int -> Int -> Maybe LS.SymbolContext\n                    -> [LS.Scalar] -> (String -> Either String (Gen LS.Scalar))\n                    -> Either String (Gen LS.Scalar)\ncheckedStrategyWith factories schema reference bits budget scope witnesses scalar = do\n  checked <- mapM (S.validateWith scope schema reference bits) witnesses\n  seeds <- foldM (indexWitness schema reference) Map.empty checked\n  let scoped = maybe id LS.scopeSymbols scope\n      accepted ty value = case S.validateChecked scope schema ty bits value of\n        Right _ -> True\n        Left (S.Rejected _) -> False\n        Left (S.EvaluationFailure message) -> error message\n      finish ty available generator =\n        let values = filter ((<= available) . valueNodes)\n              (Map.findWithDefault [] ty seeds)\n            native = scoped <$> generator\n            choices = if null values then native\n              else Gen.choice [native, Gen.element values]\n        in Gen.filterT (accepted ty) choices\n  generated <- buildStrategyWith factories schema reference bits budget scalar finish\n  pure\n    (either error id . S.validateWith scope schema reference bits <$> generated)\n\nvalueNodes :: LS.Scalar -> Int\nvalueNodes value = 1 + sum (map valueNodes (case value of\n  LS.SData _ fields -> fields\n  LS.SList values -> values\n  LS.SPresent _ payload -> maybe [] pure payload\n  _ -> []))\n\nindexWitness :: S.Schema -> S.TypeRef -> Map.Map S.TypeRef [LS.Scalar]\n             -> LS.Scalar -> Either String (Map.Map S.TypeRef [LS.Scalar])\nindexWitness schema reference witnesses value = do\n  let indexed = Map.insertWith (++) reference [value] witnesses\n      descend ty values = foldM (indexWitness schema ty) indexed values\n  case (reference, value) of\n    (S.Named \"List\" [element], LS.SList values) -> descend element values\n    (S.Named name [element], LS.SPresent _ payload)\n      | name `elem` [\"Nullable\", \"Optional\"] ->\n        descend element (maybe [] pure payload)\n    (S.Named \"Maybe\" [element], LS.SData \"Maybe::Just\" [child]) ->\n      descend element [child]\n    (S.Named \"Either\" [left, _], LS.SData \"Either::Left\" [child]) ->\n      descend left [child]\n    (S.Named \"Either\" [_, right], LS.SData \"Either::Right\" [child]) ->\n      descend right [child]\n    (_, LS.SData tag fields) -> do\n      constructors <- S.constructors schema reference\n      let matches =\n            [expected | S.Constructor name expected <- maybe [] id constructors,\n                        name == tag]\n      case matches of\n        expected:_ -> foldM\n          (\\acc (S.Field _ ty, child) -> indexWitness schema ty acc child)\n          indexed (zip expected fields)\n        [] -> pure indexed\n    _ -> pure indexed\n\nbuildStrategy :: S.Schema -> S.TypeRef -> Int -> Int\n              -> (String -> Either String (Gen LS.Scalar))\n              -> (S.TypeRef -> Int -> Gen LS.Scalar -> Gen LS.Scalar)\n              -> Either String (Gen LS.Scalar)\nbuildStrategy = buildStrategyWith []\n\nbuildStrategyWith :: [(String, NativeFactory)]\n                  -> S.Schema -> S.TypeRef -> Int -> Int\n                  -> (String -> Either String (Gen LS.Scalar))\n                  -> (S.TypeRef -> Int -> Gen LS.Scalar -> Gen LS.Scalar)\n                  -> Either String (Gen LS.Scalar)\nbuildStrategyWith factories schema reference bits budget scalar finish = do\n  unless (budget > 0) (Left \"structural node budget must be positive\")\n  unless (bits == 32 || bits == 64) (Left \"machineBits must be 32 or 64\")\n  S.checkType schema 0 reference\n  result <- evalStateT (build reference budget) Map.empty\n  maybe (Left (\"no value of \" ++ show reference ++\n               \" within structural node budget \" ++ show budget)) Right result\n  where\n    build :: S.TypeRef -> Int -> Build (Maybe (Gen LS.Scalar))\n    build _ available | available < 1 = pure Nothing\n    build ty available = do\n      cached <- Map.lookup (ty, available) <$> get\n      case cached of\n        Just result -> pure result\n        Nothing -> do\n          -- A custom distribution owns its samples and shrink tree. It must\n          -- never acquire fallback witnesses or discard invalid native values.\n          result <- case ty of\n            S.Named name arguments | Just factory <- lookup name factories -> do\n              -- A native factory may ignore a phantom parameter. Discard only\n              -- if it actually requests a value from an uninhabited child.\n              children <- mapM (\\child -> maybe Gen.discard id <$>\n                build child (available - 1)) arguments\n              Just <$> lift (factory ty children)\n            _ -> fmap (finish ty available) <$> assemble ty available\n          modify (Map.insert (ty, available) result)\n          pure result\n\n    minimumCost ty limit = search 1\n      where\n        search cost | cost > limit = pure Nothing\n        search cost = do\n          candidate <- build ty cost\n          case candidate of\n            Just _ -> pure (Just cost)\n            Nothing -> search (cost + 1)\n\n    -- Reserve every field's minimum before distributing spare nodes.\n    allocation [] _ = pure (Just [])\n    allocation fields available = do\n      minima <- reserve fields available\n      pure $ fmap distribute minima\n      where\n        reserve [] _ = pure (Just [])\n        reserve (S.Field _ ty : rest) remaining = do\n          cost <- minimumCost ty remaining\n          case cost of\n            Nothing -> pure Nothing\n            Just amount -> fmap (amount :) <$> reserve rest (remaining - amount)\n        distribute costs =\n          let (share, extra) = (available - sum costs) `divMod` length costs\n          in zipWith (\\index cost -> cost + share + fromEnum (index < extra))\n               [0 ..] costs\n\n    alternatives = pure . choose . catMaybes\n    choose [] = Nothing\n    choose [only] = Just only\n    choose choices = Just (Gen.choice choices)\n\n    variant available (S.Constructor tag fields) = do\n      costs <- allocation fields (available - 1)\n      case costs of\n        Nothing -> pure Nothing\n        Just amounts -> do\n          children <- sequence <$> sequence\n            [build ty amount | (S.Field _ ty, amount) <- zip fields amounts]\n          pure\n            ((\\generators -> LS.SData tag <$> sequence generators) <$> children)\n\n    assemble ty available = do\n      constructors <- lift (S.constructors schema ty)\n      case constructors of\n        Just variants -> mapM (variant available) variants >>= alternatives\n        Nothing -> builtin ty available\n\n    builtin (S.Named name []) _ = do\n      generator <- lift (scalar name)\n      -- Scalar generators come from the target's typed primitive registry.\n      pure (Just generator)\n    builtin (S.Named \"List\" [element]) available = do\n      cost <- minimumCost element (available - 1)\n      let maximumLength = maybe 0 ((available - 1) `div`) cost\n      sized <- mapM (listOfLength element (available - 1)) [1 .. maximumLength]\n      let generators = pure (LS.SList []) : sized\n      pure (Just (Gen.int (Range.linear 0 maximumLength) >>= (generators !!)))\n    builtin (S.Named name [element]) available\n      | name `elem` [\"Maybe\", \"Nullable\", \"Optional\"] = do\n          child <- build element (available - 1)\n          let absent = if name == \"Maybe\"\n                then LS.SData \"Maybe::Nothing\" [] else LS.SPresent name Nothing\n              present value = if name == \"Maybe\"\n                then LS.SData \"Maybe::Just\" [value]\n                else LS.SPresent name (Just value)\n          alternatives [Just (pure absent), fmap (fmap present) child]\n    builtin (S.Named \"Either\" [left, right]) available =\n      mapM (variant available)\n        [S.Constructor \"Either::Left\" [S.Field \"value\" left],\n         S.Constructor \"Either::Right\" [S.Field \"value\" right]] >>= alternatives\n    builtin ty _ = lift (Left (\"unsupported generator type: \" ++ show ty))\n\n    listOfLength element remaining count = do\n      child <- build element (remaining `div` count)\n      case child of\n        Nothing -> lift (Left \"internal list budget allocation failure\")\n        Just generator -> pure\n          (LS.SList <$> Gen.list (Range.singleton count) generator)\n\n-- Primitive shrinkers remain in Hedgehog: integers, lists, and IEEE bit words.\nprimitiveStrategy :: Int -> String -> Either String (Gen LS.Scalar)\nprimitiveStrategy bits name\n  | bits /= 32 && bits /= 64 = Left \"machineBits must be 32 or 64\"\n  | LS.isInteger name =\n      let (lo, hi) = maybe\n            (if name == \"BigUInt\" then (0, 2^(256 :: Int))\n             else (-2^(256 :: Int), 2^(256 :: Int))) id\n            (LS.integerBounds bits name)\n      in Right (LS.SInteger name <$> Gen.integral (Range.linearFrom 0 lo hi))\n  | name == \"Bool\" = Right (LS.SBool <$> Gen.bool)\n  | name `elem` [\"Unit\", \"Null\", \"Undefined\"] =\n      Right (pure (LS.SAbsent name))\n  | name `elem` [\"Char\", \"CodePoint\", \"CodeUnit16\"] =\n      Right (LS.SCharacter name <$> unit name)\n  | name `elem` [\"Text\", \"CodePointText\", \"Utf16Text\", \"Bytes\"] =\n      Right (LS.SSequence name <$> Gen.list (Range.linear 0 100) (unit name))\n  | name == \"Decimal\" = Right\n      (LS.SDecimal <$> integer <*> Gen.integral (Range.linearFrom 0 (-20) 20))\n  | name == \"Rational\" = Right $ do\n      n <- integer\n      d <- Gen.integral (Range.linear 1 (2^(256 :: Int)))\n      let reduced = n % d\n      pure (LS.SRational (numerator reduced) (denominator reduced))\n  | name `elem` [\"Float32\", \"Float64\"] =\n      let digits = if name == \"Float32\" then 8 else 16\n          patternGenerator = Gen.integral (Range.constant 0 (16^digits - 1))\n          encode word =\n            let hex = showHex (word :: Integer) \"\"\n            in LS.SFloat name (replicate (digits - length hex) '0' ++ hex)\n      in Right (encode <$> patternGenerator)\n  | name `elem` [\"Complex64\", \"Complex128\"] = do\n      component <- primitiveStrategy bits\n        (if name == \"Complex64\" then \"Float32\" else \"Float64\")\n      Right (LS.SComplex name <$> component <*> component)\n  | name == \"Symbol\" = Right\n      (LS.SSymbol <$> Gen.string (Range.linear 0 40) Gen.alphaNum <*>\n        (map chr <$> Gen.list (Range.linear 0 40) (unit \"Text\")))\n  | otherwise = Left (\"unknown scalar generator: \" ++ name)\n  where\n    integer = Gen.integral (Range.linearFrom 0\n      (-2^(256 :: Int)) (2^(256 :: Int)))\n    unit kind =\n      let upper = if kind == \"Bytes\" then 255\n                  else if kind `elem` [\"CodeUnit16\", \"Utf16Text\"] then 65535\n                  else 1114111\n          generator = Gen.int (Range.linear 0 upper)\n      in if kind `elem` [\"Char\", \"Text\"]\n         then Gen.filter (\\point -> point < 55296 || point > 57343) generator\n         else generator\n"
