t n = exact.integer()?;\n        let (lo, hi) = if signed {\n            let bound = BigInt::one() << (width - 1);\n            (-&bound, &bound - 1u8)\n        } else {\n            (BigInt::zero(), (BigInt::one() << width) - 1u8)\n        };\n        if n < lo || n > hi {\n            return Err(format!(\"integer outside {target} range\"));\n        }\n        Ok(Self::Integer(n))\n    }\n}\n\n/// Round the exact ratio once, directly into an IEEE significand and exponent.\npub fn exact_float_bits(ratio: &BigRational, single: bool) -> Result<u64> {\n    let (precision, bias, sign_shift) = if single {\n        (24i64, 127i64, 31)\n    } else {\n        (53i64, 1023i64, 63)\n    };\n    let sign = u64::from(ratio.is_negative()) << sign_shift;\n    if ratio.is_zero() {\n        return Ok(sign);\n    }\n    let n = ratio.numer().abs();\n    let d = ratio.denom().clone();\n    let mut exponent = n.bits() as i64 - d.bits() as i64;\n    if if exponent >= 0 {\n        n < (&d << exponent as usize)\n    } else {\n        (&n << (-exponent) as usize) < d\n    } {\n        exponent -= 1;\n    }\n    let infinity = sign | (((2 * bias + 1) as u64) << (precision - 1));\n    if exponent > bias {\n        return Ok(infinity);\n    }\n    let minimum = 1 - bias;\n    if exponent < minimum - precision {\n        return Ok(sign);\n    }\n    let scale = exponent.max(minimum) - (precision - 1);\n    let num = if scale < 0 { n << (-scale) as usize } else { n };\n    let den = if scale > 0 { d << scale as usize } else { d };\n    let mut q = &num / &den;\n    let twice = (&num % &den) * 2u8;\n    if twice > den || twice == den && !(&q % 2u8).is_zero() {\n        q += 1u8;\n    }\n    exponent = exponent.max(minimum);\n    if q == (BigInt::one() << precision as usize) {\n        q >>= 1usize;\n        exponent += 1;\n    }\n    if exponent > bias {\n        return Ok(infinity);\n    }\n    let hidden = 1u64 << (precision - 1);\n    let significand = q.to_u64().ok_or(\"invalid IEEE significand\")?;\n    let (exp, mantissa) = if significand < hidden {\n        (0, significand)\n    } else {\n        ((exponent + bias) as u64, significand - hidden)\n    };\n    Ok(sign | (exp << (precision - 1)) | mantissa)\n}\n\nfn numeric_class(value: &Value) -> Option<bool> {\n    match value {\n        Value::Integer(_) | Value::Decimal(_) | Value::Rational(_) => Some(true),\n        Value::Float32(_) | Value::Float64(_) | Value::Complex32(_) | Value::Complex64(_) => {\n            Some(false)\n        }\n        _ => None,\n    }\n}\n\npub fn equal(a: &Value, b: &Value) -> Result<bool> {\n    if let (Some(x), Some(y)) = (numeric_class(a), numeric_class(b)) {\n        if x != y {\n            return Err(\"exact/inexact mixing requires an explicit conversion\".into());\n        }\n    }\n    match (a, b) {\n        (\n            Value::Integer(_) | Value::Decimal(_) | Value::Rational(_),\n            Value::Integer(_) | Value::Decimal(_) | Value::Rational(_),\n        ) => Ok(a.exact()? == b.exact()?),\n        (Value::Float32(_) | Value::Float64(_), Value::Float32(_) | Value::Float64(_)) => {\n            Ok(a.real64()? == b.real64()?)\n        }\n        (\n            Value::Complex32(_) | Value::Complex64(_) | Value::Float32(_) | Value::Float64(_),\n            Value::Complex32(_) | Value::Complex64(_) | Value::Float32(_) | Value::Float64(_),\n        ) => Ok(a.complex64()? == b.complex64()?),\n        (Value::Nullable(Some(x)), Value::Nullable(Some(y)))\n        | (Value::Optional(Some(x)), Value::Optional(Some(y)))\n        | (Value::Maybe(Some(x)), Value::Maybe(Some(y)))\n        | (Value::Left(x), Value::Left(y))\n        | (Value::Right(x), Value::Right(y)) => equal(x, y),\n        (Value::Data(left_tag, _), Value::Data(right_tag, _)) if left_tag != right_tag => Ok(false),\n        (Value::List(xs), Value::List(ys)) | (Value::Data(_, xs), Value::Data(_, ys)) => {\n            if xs.len() != ys.len() {\n                return Ok(false);\n            }\n            for (x, y) in xs.iter().zip(ys) {\n                if !equal(x, y)? {\n                    return Ok(false);\n                }\n            }\n            Ok(true)\n        }\n        _ => Ok(a == b),\n    }\n}\n\n/// `domain` is the compiler-resolved arithmetic evidence, never inferred here.\npub fn binary(op: &str, domain: &str, a: Value, b: Value) -> Result<Value> {\n    use Value::*;\n    if op == \"==\" || op == \"!=\" {\n        return Ok(Bool(equal(&a, &b)? == (op == \"==\")));\n    }\n    let exact_domain = !matches!(domain, \"Float32\" | \"Float64\" | \"Complex64\" | \"Complex128\");\n    if numeric_class(&a) != Some(exact_domain) || numeric_class(&b) != Some(exact_domain) {\n        return Err(\"numeric operands must match the resolved arithmetic domain; use an explicit conversion\".into());\n    }\n    macro_rules! calculate {\n        ($x:expr,$y:expr,$variant:ident) => {{\n            let x = $x;\n            let y = $y;\n            match op {\n                \"+\" => Ok($variant(x + y)),\n                \"-\" => Ok($variant(x - y)),\n                \"*\" => Ok($variant(x * y)),\n                \"/\" => Ok($variant(x / y)),\n                \"<\" => Ok(Bool(x < y)),\n                \"<=\" => Ok(Bool(x <= y)),\n                \">\" => Ok(Bool(x > y)),\n                \">=\" => Ok(Bool(x >= y)),\n                _ => Err(\"invalid arithmetic operation\".into()),\n            }\n        }};\n    }\n    if domain == \"Float32\" {\n        return calculate!(\n            f32::from_value(a.convert(\"Float32\", 64)?)?,\n            f32::from_value(b.convert(\"Float32\", 64)?)?,\n            Float32\n        );\n    }\n    if domain == \"Float64\" {\n        return calculate!(a.real64()?, b.real64()?, Float64);\n    }\n    macro_rules! complex {\n        ($x:expr,$y:expr,$variant:ident) => {{\n            let x = $x;\n            let y = $y;\n            match op {\n                \"+\" => Ok($variant(x + y)),\n                \"-\" => Ok($variant(x - y)),\n                \"*\" => Ok($variant(x * y)),\n                \"/\" => {\n                    // Match portable componentwise IEEE operations at declared precision.\n                    let d = y.re * y.re + y.im * y.im;\n                    Ok($variant(num_complex::Complex::new(\n                        (x.re * y.re + x.im * y.im) / d,\n                        (x.im * y.re - x.re * y.im) / d,\n                    )))\n                }\n                _ => Err(\"complex values are not ordered\".into()),\n            }\n        }};\n    }\n    if domain == \"Complex64\" {\n        return complex!(\n            num_complex::Complex32::from_value(a.convert(\"Complex64\", 64)?)?,\n            num_complex::Complex32::from_value(b.convert(\"Complex64\", 64)?)?,\n            Complex32\n        );\n    }\n    if domain == \"Complex128\" {\n        return complex!(a.complex64()?, b.complex64()?, Complex64);\n    }\n    let x = a.exact()?;\n    let y = b.exact()?;\n    if matches!(op, \"/\" | \"quot\" | \"rem\") && y.is_zero() {\n        return Err(\"exact division by zero\".into());\n    }\n    let result = match op {\n        \"+\" => x + y,\n        \"-\" => x - y,\n        \"*\" => x * y,\n        \"/\" => x / y,\n        \"quot\" => return Ok(Integer(a.integer()? / b.integer()?)),\n        \"rem\" => return Ok(Integer(a.integer()? % b.integer()?)),\n        \"<\" => return Ok(Bool(x < y)),\n        \"<=\" => return Ok(Bool(x <= y)),\n        \">\" => return Ok(Bool(x > y)),\n        \">=\" => return Ok(Bool(x >= y)),\n        _ => return Err(\"invalid arithmetic operation\".into()),\n    };\n    Rational(result).convert(domain, 64)\n}\n\npub fn negate(value: Value) -> Result<Value> {\n    Ok(match value {\n        Value::Integer(x) => Value::Integer(-x),\n        Value::Rational(x) => Value::Rational(-x),\n        Value::Decimal(x) => Value::Decimal(Decimal::new(-x.coefficient, x.exponent)),\n        Value::Float32(x) => Value::Float32(-x),\n        Value::Float64(x) => Value::Float64(-x),\n        Value::Complex32(x) => Value::Complex32(-x),\n        Value::Complex64(x) => Value::Complex64(-x),\n        _ => return Err(\"negation requires numeric operand\".into()),\n    })\n}\n\npub trait IntoValue {\n    fn into_value(self) -> Value;\n}\npub trait FromValue: Sized {\n    fn from_value(value: Value) -> Result<Self>;\n}\nmacro_rules! native {\n    ($t:ty,$variant:ident) => {\n        impl IntoValue for $t {\n            fn into_value(self) -> Value {\n                Value::$variant(self)\n            }\n        }\n        impl FromValue for $t {\n            fn from_value(value: Value) -> Result<Self> {\n                if let Value::$variant(x) = value {\n                    Ok(x)\n                } else {\n                    Err(concat!(\"expected \", stringify!($t)).into())\n                }\n            }\n        }\n    };\n}\nnative!(BigInt, Integer);\nnative!(Decimal, Decimal);\nnative!(BigRational, Rational);\nnative!(f32, Float32);\nnative!(f64, Float64);\nnative!(Complex32, Complex32);\nnative!(Complex64, Complex64);\nnative!(bool, Bool);\nnative!(char, Char);\nnative!(String, Text);\n\nnative!(Symbol, Symbol);\nimpl IntoValue for Integer {\n    fn into_value(self) -> Value {\n        Value::Integer(self.0)\n    }\n}\nimpl FromValue for Integer {\n    fn from_value(value: Value) -> Result<Self> {\n        Ok(Self(value.integer()?))\n    }\n}\nimpl IntoValue for BigUint {\n    fn into_value(self) -> Value {\n        Value::Integer(self.into())\n    }\n}\nimpl FromValue for BigUint {\n    fn from_value(value: Value) -> Result<Self> {\n        value\n            .integer()?\n            .to_biguint()\n            .ok_or_else(|| \"BigUInt cannot be negative\".into())\n    }\n}\nmacro_rules! primitive_int {\n    ($($t:ty),*) => {$ (\n        impl IntoValue for $t { fn into_value(self)->Value { Value::Integer(BigInt::from(self)) } }\n        impl FromValue for $t { fn from_value(value:Value)->Result<Self> {\n            Self::try_from(value.integer()?).map_err(|_|concat!(\"integer outside \",stringify!($t),\" range\").into())\n        } }\n    )*};\n}\nprimitive_int!(\n    i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize\n);\nmacro_rules! raw {\n    ($t:ident,$variant:ident,$valid:expr) => {\n        impl IntoValue for $t {\n            fn into_value(self) -> Value {\n                Value::$variant(self.0)\n            }\n        }\n        impl FromValue for $t {\n            fn from_value(value: Value) -> Result<Self> {\n                match value {\n                    Value::$variant(x) if ($valid)(&x) => Ok(Self(x)),\n                    _ => Err(concat!(\"invalid \", stringify!($t)).into()),\n                }\n            }\n        }\n    };\n}\nraw!(CodePoint, CodePoint, |x: &u32| *x <= 0x10ffff);\nraw!(CodePointText, CodePointText, |x: &Vec<u32>| x\n    .iter()\n    .all(|c| *c <= 0x10ffff));\nraw!(Utf16Text, Utf16Text, |_: &Vec<u16>| true);\nmacro_rules! absence {\n    ($t:ty,$variant:ident,$value:expr) => {\n        impl IntoValue for $t {\n            fn into_value(self) -> Value {\n                Value::$variant\n            }\n        }\n        impl FromValue for $t {\n            fn from_value(value: Value) -> Result<Self> {\n                if matches!(value, Value::$variant) {\n                    Ok($value)\n                } else {\n                    Err(concat!(\"expected \", stringify!($t)).into())\n                }\n            }\n        }\n    };\n}\nabsence!((), Unit, ());\nabsence!(Null, Null, Null);\nabsence!(Undefined, Undefined, Undefined);\nmacro_rules! presence {\n    ($t:ident,$absent:ident) => {\n        impl<T: IntoValue> IntoValue for $t<T> {\n            fn into_value(self) -> Value {\n                Value::$t(match self {\n                    Self::$absent => None,\n                    Self::Present(x) => Some(Box::new(x.into_value())),\n                })\n            }\n        }\n        impl<T: FromValue> FromValue for $t<T> {\n            fn from_value(value: Value) -> Result<Self> {\n                match value {\n                    Value::$t(None) => Ok(Self::$absent),\n                    Value::$t(Some(x)) => Ok(Self::Present(T::from_value(*x)?)),\n                    _ => Err(\"presence type mismatch\".into()),\n                }\n            }\n        }\n    };\n}\npresence!(Nullable, Null);\npresence!(Optional, Undefined);\n\n/// Algebraic Either is independent of interoperability absence wrappers.\n#[derive(Clone, Debug, PartialEq)]\npub enum Either<L, R> {\n    Left(L),\n    Right(R),\n}\nimpl<T: IntoValue> IntoValue for Box<T> {\n    fn into_value(self) -> Value {\n        (*self).into_value()\n    }\n}\nimpl<T: FromValue> FromValue for Box<T> {\n    fn from_value(value: Value) -> Result<Self> {\n        T::from_value(value).map(Box::new)\n    }\n}\nimpl<T: IntoValue> IntoValue for Vec<T> {\n    fn into_value(self) -> Value {\n        Value::List(self.into_iter().map(IntoValue::into_value).collect())\n    }\n}\nimpl<T: FromValue> FromValue for Vec<T> {\n    fn from_value(value: Value) -> Result<Self> {\n        let values = match value {\n            Value::List(values) => values,\n            Value::Bytes(values) => values\n                .into_iter()\n                .map(|v| Value::Integer(v.into()))\n                .collect(),\n            _ => return Err(\"expected List or Bytes\".into()),\n        };\n        values.into_iter().map(T::from_value).collect()\n    }\n}\nimpl<T: IntoValue> IntoValue for Option<T> {\n    fn into_value(self) -> Value {\n        Value::Maybe(self.map(|x| Box::new(x.into_value())))\n    }\n}\nimpl<T: FromValue> FromValue for Option<T> {\n    fn from_value(value: Value) -> Result<Self> {\n        match value {\n            Value::Maybe(value) => value.map(|x| T::from_value(*x)).transpose(),\n            _ => Err(\"expected Maybe\".into()),\n        }\n    }\n}\nimpl<L: IntoValue, R: IntoValue> IntoValue for Either<L, R> {\n    fn into_value(self) -> Value {\n        match self {\n            Self::Left(x) => Value::Left(Box::new(x.into_value())),\n            Self::Right(x) => Value::Right(Box::new(x.into_value())),\n        }\n    }\n}\nimpl<L: FromValue, R: FromValue> FromValue for Either<L, R> {\n    fn from_value(value: Value) -> Result<Self> {\n        match value {\n            Value::Left(x) => Ok(Self::Left(L::from_value(*x)?)),\n            Value::Right(x) => Ok(Self::Right(R::from_value(*x)?)),\n            _ => Err(\"expected Either\".into()),\n        }\n    }\n}\n\n/// A fully applied type, or a parameter in a constructor's field schema.\n#[derive(Clone, Debug, PartialEq, Eq, Hash)]\npub enum TypeRef {\n    Named(&'static str, Vec<TypeRef>),\n    Parameter(usize),\n}\n\nimpl TypeRef {\n    pub fn named(name: &'static str, arguments: Vec<TypeRef>) -> Self {\n        Self::Named(name, arguments)\n    }\n\n    /// Expression runtime spelling, after schema type arguments are substituted.\n    pub fn expression_key(&self) -> Result<String> {\n        match self {\n            Self::Parameter(index) => Err(format!(\"unbound expression type parameter {index}\")),\n            Self::Named(name, arguments) => {\n                let mut parts = vec![(*name).to_owned()];\n                for argument in arguments {\n                    parts.push(argument.expression_key()?);\n                }\n                Ok(parts.join(\" \"))\n            }\n        }\n    }\n\n    pub fn instantiate(&self, arguments: &[TypeRef]) -> Result<Self> {\n        match self {\n            Self::Parameter(index) => arguments\n                .get(*index)\n                .cloned()\n                .ok_or_else(|| format!(\"unbound data type parameter {index}\")),\n            Self::Named(name, fields) => Ok(Self::Named(\n                name,\n                fields\n                    .iter()\n                    .map(|field| field.instantiate(arguments))\n                    .collect::<Result<_>>()?,\n            )),\n        }\n    }\n}\n\n#[derive(Clone, Debug)]\npub struct ConstructorSchema {\n    pub tag: &'static str,\n    pub fields: Vec<TypeRef>,\n}\n\n#[derive(Clone, Debug)]\npub struct DataSchema {\n    pub name: &'static str,\n    pub parameters: usize,\n    pub constructors: Vec<ConstructorSchema>,\n}\n\n/// Typed constructor predicates receive instantiated type arguments and logical\n/// fields. A false result rejects a candidate; an error is an evaluation failure.\npub type FieldPredicate = fn(&Schema, &[TypeRef], &[Value], u32, &mut Context) -> Result<bool>;\n\n#[derive(Clone, Debug)]\npub struct ConstructorContract {\n    pub tag: &'static str,\n    pub predicates: Vec<FieldPredicate>,\n}\n\n#[derive(Clone, Debug, PartialEq)]\npub enum ValueCheck {\n    Accepted(Value),\n    Rejected(String),\n}\n\n#[derive(Debug)]\nenum ValidationFailure {\n    Rejected(String),\n    Error(String),\n}\n\nimpl ValidationFailure {\n    fn context(self, prefix: String) -> Self {\n        match self {\n            Self::Rejected(message) => Self::Rejected(format!(\"{prefix}: {message}\")),\n            Self::Error(message) => Self::Error(format!(\"{prefix}: {message}\")),\n        }\n    }\n\n    fn message(self) -> String {\n        match self {\n            Self::Rejected(message) | Self::Error(message) => message,\n        }\n    }\n}\n\nimpl From<String> for ValidationFailure {\n    fn from(message: String) -> Self {\n        Self::Error(message)\n    }\n}\n\n/// Compiler-provided data definitions. Validation is framework-independent and\n/// follows instantiated field types, rather than guessing from Rust payloads.\n#[derive(Clone, Debug)]\npub struct Schema {\n    definitions: HashMap<&'static str, DataSchema>,\n    contracts: HashMap<&'static str, Vec<FieldPredicate>>,\n}\n\nfn builtin_arity(name: &str) -> Option<usize> {\n    match name {\n        \"List\" | \"Maybe\" | \"Nullable\" | \"Optional\" => Some(1),\n        \"Either\" => Some(2),\n        \"Bool\" | \"Int8\" | \"Int16\" | \"Int32\" | \"Int64\" | \"UInt8\" | \"UInt16\" | \"UInt32\"\n        | \"UInt64\" | \"IntSize\" | \"UIntSize\" | \"UIntPtr\" | \"Integer\" | \"BigInt\" | \"BigUInt\"\n        | \"Decimal\" | \"Rational\" | \"Float32\" | \"Float64\" | \"Complex64\" | \"Complex128\" | \"Char\"\n        | \"CodePoint\" | \"CodeUnit16\" | \"Text\" | \"CodePointText\" | \"Utf16Text\" | \"Bytes\"\n        | \"Symbol\" | \"Unit\" | \"Null\" | \"Undefined\" => Some(0),\n        _ => None,\n    }\n}\n\n// Recipes describe parameter positions rather than instantiated field types.\n#[derive(Clone, Debug)]\nenum PayloadPlan {\n    Ignore,\n    Parameter(usize),\n    Applied(&'static str, Vec<PayloadPlan>),\n}\n\nimpl PayloadPlan {\n    fn field(ty: &TypeRef, arguments: &[Self]) -> Result<Self> {\n        match ty {\n            TypeRef::Parameter(index) => arguments\n                .get(*index)\n                .cloned()\n                .ok_or_else(|| \"unbound payload parameter\".into()),\n            TypeRef::Named(name, fields) => {\n                let children = fields\n                    .iter()\n                    .map(|field| Self::field(field, arguments))\n                    .collect::<Result<Vec<_>>>()?;\n                Ok(\n                    if children.iter().all(|child| matches!(child, Self::Ignore)) {\n                        Self::Ignore\n                    } else {\n                        Self::Applied(name, children)\n                    },\n                )\n            }\n        }\n    }\n}\n\nimpl Schema {\n    pub fn has_contracts(&self) -> bool {\n        self.contracts\n            .values()\n            .any(|predicates| !predicates.is_empty())\n    }\n\n    pub fn new(definitions: Vec<DataSchema>) -> Result<Self> {\n        Self::with_contracts(definitions, vec![])\n    }\n\n    pub fn with_contracts(\n        definitions: Vec<DataSchema>,\n        contracts: Vec<ConstructorContract>,\n    ) -> Result<Self> {\n        let mut types = HashMap::new();\n        let mut tags = std::collections::HashSet::new();\n        for definition in definitions {\n            let name = definition.name;\n            if builtin_arity(name).is_some() || types.contains_key(name) {\n                return Err(format!(\"duplicate or reserved data type: {name}\"));\n            }\n            for constructor in &definition.constructors {\n                if !tags.insert(constructor.tag) {\n                    return Err(format!(\"duplicate constructor: {}\", constructor.tag));\n                }\n            }\n            types.insert(name, definition);\n        }\n        let mut predicates = HashMap::new();\n        for contract in contracts {\n            if !tags.contains(contract.tag) {\n                return Err(format!(\"unknown constructor contract: {}\", contract.tag));\n            }\n            if predicates\n                .insert(contract.tag, contract.predicates)\n                .is_some()\n            {\n                return Err(format!(\"duplicate constructor contract: {}\", contract.tag));\n            }\n        }\n        let schema = Self {\n            definitions: types,\n            contracts: predicates,\n        };\n        for definition in schema.definitions.values() {\n            for constructor in &definition.constructors {\n                for field in &constructor.fields {\n                    schema.check_type(field, definition.parameters)?;\n                }\n            }\n        }\n        Ok(schema)\n    }\n\n    fn check_type(&self, ty: &TypeRef, parameters: usize) -> Result<()> {\n        match ty {\n            TypeRef::Parameter(index) if *index < parameters => Ok(()),\n            TypeRef::Parameter(index) => Err(format!(\"unbound data type parameter {index}\")),\n            TypeRef::Named(name, arguments) => {\n                let arity = builtin_arity(name)\n                    .or_else(|| self.definitions.get(name).map(|d| d.parameters))\n                    .ok_or_else(|| format!(\"unknown data type: {name}\"))?;\n                if arity != arguments.len() {\n                    return Err(format!(\"expected {arity} type arguments for {name}\"));\n                }\n                for argument in arguments {\n                    self.check_type(argument, parameters)?;\n                }\n                Ok(())\n            }\n        }\n    }\n\n    /// Instantiated fields for composing native generators. None denotes a\n    /// built-in type; an empty list denotes a user type with no constructors.\n    pub fn constructor_fields(&self, ty: &TypeRef) -> Result<Option<Vec<ConstructorSchema>>> {\n        self.check_type(ty, 0)?;\n        let TypeRef::Named(name, arguments) = ty else {\n            return Err(\"uninstantiated generator type\".into());\n        };\n        self.definitions\n            .get(name)\n            .map(|definition| {\n                definition\n                    .constructors\n                    .iter()\n                    .map(|constructor| {\n                        Ok(ConstructorSchema {\n                            tag: constructor.tag,\n                            fields: constructor\n                                .fields\n                                .iter()\n                                .map(|field| field.instantiate(arguments))\n                                .collect::<Result<_>>()?,\n                        })\n                    })\n                    .collect::<Result<_>>()\n            })\n            .transpose()\n    }\n\n    /// Validate first, then check only stored occurrences of type arguments.\n    /// The dispatcher shares one mutable context without aliasing callback borrows.\n    pub fn all_payloads_with_context(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        predicate_count: usize,\n        bits: u32,\n        context: &mut Context,\n        mut predicate: impl FnMut(usize, Value, &mut Context) -> Result<Value>,\n    ) -> Result<Value> {\n        self.check_type(ty, 0)?;\n        let TypeRef::Named(name, arguments) = ty else {\n            return Err(\"payload predicates require an instantiated data type\".into());\n        };\n        if !self.definitions.contains_key(name)\n            && !matches!(*name, \"List\" | \"Maybe\" | \"Either\" | \"Nullable\" | \"Optional\")\n        {\n            return Err(\"payload predicates require a data type\".into());\n        }\n        if arguments.len() != predicate_count {\n            return Err(\"payload predicate arity mismatch\".into());\n        }\n        let checked = self.validate_with_context(value, ty, bits, context)?;\n        let plan = PayloadPlan::Applied(\n            name,\n            (0..predicate_count).map(PayloadPlan::Parameter).collect(),\n        );\n        self.walk_payload(&plan, checked, context, &mut predicate)\n            .map(Value::Bool)\n    }\n\n    fn walk_payload(\n        &self,\n        plan: &PayloadPlan,\n        value: Value,\n        context: &mut Context,\n        predicate: &mut impl FnMut(usize, Value, &mut Context) -> Result<Value>,\n    ) -> Result<bool> {\n        let (name, arguments) = match plan {\n            PayloadPlan::Ignore => return Ok(true),\n            PayloadPlan::Parameter(index) => return predicate(*index, value, context)?.boolean(),\n            PayloadPlan::Applied(name, arguments) => (*name, arguments),\n        };\n        match (name, value) {\n            (\"List\", Value::List(values)) => {\n                for (index, value) in values.into_iter().enumerate() {\n                    if !self\n                        .walk_payload(&arguments[0], value, context, predicate)\n                        .map_err(|error| format!(\"List element {index}: {error}\"))?\n                    {\n                        return Ok(false);\n                    }\n                }\n                Ok(true)\n            }\n            (\"Maybe\", Value::Maybe(value))\n            | (\"Nullable\", Value::Nullable(value))\n            | (\"Optional\", Value::Optional(value)) => match value {\n                None => Ok(true),\n                Some(value) => self\n                    .walk_payload(&arguments[0], *value, context, predicate)\n                    .map_err(|error| format!(\"{name} payload: {error}\")),\n            },\n            (\"Either\", Value::Left(value)) => self\n                .walk_payload(&arguments[0], *value, context, predicate)\n                .map_err(|error| format!(\"Either Left payload: {error}\")),\n            (\"Either\", Value::Right(value)) => self\n                .walk_payload(&arguments[1], *value, context, predicate)\n                .map_err(|error| format!(\"Either Right payload: {error}\")),\n            (_, Value::Data(tag, values)) => {\n                let definition = self\n                    .definitions\n                    .get(name)\n                    .ok_or_else(|| format!(\"unknown payload data type: {name}\"))?;\n                let constructor = definition\n                    .constructors\n                    .iter()\n                    .find(|item| item.tag == tag)\n                    .ok_or_else(|| format!(\"unknown payload constructor: {tag}\"))?;\n                for (index, (field, value)) in constructor.fields.iter().zip(values).enumerate() {\n                    let plan = PayloadPlan::field(field, arguments)?;\n                    if !self\n                        .walk_payload(&plan, value, context, predicate)\n                        .map_err(|error| format!(\"{tag} field {index}: {error}\"))?\n                    {\n                        return Ok(false);\n                    }\n                }\n                Ok(true)\n            }\n            _ => Err(\"payload traversal requires a matching structural value\".into()),\n        }\n    }\n\n    pub fn validate(&self, value: Value, ty: &TypeRef, bits: u32) -> Result<Value> {\n        self.validate_with_context(value, ty, bits, &mut Context::default())\n    }\n\n    pub fn check_with_context(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        bits: u32,\n        context: &mut Context,\n    ) -> Result<ValueCheck> {\n        self.check_type(ty, 0)?;\n        if !matches!(bits, 32 | 64) {\n            return Err(\"machineBits must be 32 or 64\".into());\n        }\n        match self.walk(value, ty, bits, false, context) {\n            Ok(value) => Ok(ValueCheck::Accepted(value)),\n            Err(ValidationFailure::Rejected(message)) => Ok(ValueCheck::Rejected(message)),\n            Err(ValidationFailure::Error(message)) => Err(message),\n        }\n    }\n\n    pub fn validate_with_context(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        bits: u32,\n        context: &mut Context,\n    ) -> Result<Value> {\n        match self.check_with_context(value, ty, bits, context)? {\n            ValueCheck::Accepted(value) => Ok(value),\n            ValueCheck::Rejected(message) => Err(message),\n        }\n    }\n\n    /// Check logical fields before adapting raw code units to native integers.\n    pub fn native_value(&self, value: Value, ty: &TypeRef, bits: u32) -> Result<Value> {\n        self.native_value_with_context(value, ty, bits, &mut Context::default())\n    }\n\n    pub fn native_value_with_context(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        bits: u32,\n        context: &mut Context,\n    ) -> Result<Value> {\n        let checked = self.validate_with_context(value, ty, bits, context)?;\n        self.walk(checked, ty, bits, true, context)\n            .map_err(ValidationFailure::message)\n    }\n\n    fn walk(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        bits: u32,\n        native: bool,\n        context: &mut Context,\n    ) -> std::result::Result<Value, ValidationFailure> {\n        let TypeRef::Named(name, arguments) = ty else {\n            return Err(\"uninstantiated data type parameter\".to_string().into());\n        };\n        if let Some(definition) = self.definitions.get(name) {\n            let Value::Data(tag, fields) = value else {\n                return Err(format!(\"expected data value of type {name}\").into());\n            };\n            let constructor = definition\n                .constructors\n                .iter()\n                .find(|constructor| constructor.tag == tag)\n                .ok_or_else(|| format!(\"constructor {tag} does not belong to {name}\"))?;\n            if fields.len() != constructor.fields.len() {\n                return Err(format!(\"wrong field count for {tag}\").into());\n            }\n            let checked: Vec<Value> = fields\n                .into_iter()\n                .zip(&constructor.fields)\n                .enumerate()\n                .map(|(index, (field, field_type))| {\n                    self.walk(\n                        field,\n                        &field_type.instantiate(arguments)?,\n                        bits,\n                        native,\n                        context,\n                    )\n                    .map_err(|error| error.context(format!(\"{tag} field {index}\")))\n                })\n                .collect::<std::result::Result<_, ValidationFailure>>()?;\n            if !native {\n                if let Some(predicates) = self.contracts.get(constructor.tag) {\n                    for (index, predicate) in predicates.iter().enumerate() {\n                        let label = format!(\"{tag}: field refinement {}\", index + 1);\n                        let accepted = predicate(self, arguments, &checked, bits, context)\n                            .map_err(|message| {\n                                ValidationFailure::Error(format!(\"{label}: {message}\"))\n                            })?;\n                        if !accepted {\n                            return Err(ValidationFailure::Rejected(format!(\"{label} failed\")));\n                        }\n                    }\n                }\n            }\n            return Ok(Value::Data(tag, checked));\n        }\n        if arguments.is_empty() {\n            let checked = validate(value, name, bits)?;\n            return if native {\n                native_value(checked, name).map_err(ValidationFailure::Error)\n            } else {\n                Ok(checked)\n            };\n        }\n        match (*name, arguments.as_slice(), value) {\n            (\"List\", [element], Value::List(values)) => Ok(Value::List(\n                values\n                    .into_iter()\n                    .enumerate()\n                    .map(|(index, value)| {\n                        self.walk(value, element, bits, native, context)\n                            .map_err(|error| error.context(format!(\"List element {index}\")))\n                    })\n                    .collect::<std::result::Result<_, ValidationFailure>>()?,\n            )),\n            (\"Maybe\", [element], Value::Maybe(value)) => Ok(Value::Maybe(\n                value\n                    .map(|value| {\n                        self.walk(*value, element, bits, native, context)\n                            .map(Box::new)\n                    })\n                    .transpose()?,\n            )),\n            (\"Nullable\", [element], Value::Nullable(value)) => Ok(Value::Nullable(\n                value\n                    .map(|value| {\n                        self.walk(*value, element, bits, native, context)\n                            .map(Box::new)\n                    })\n                    .transpose()?,\n            )),\n            (\"Optional\", [element], Value::Optional(value)) => Ok(Value::Optional(\n                value\n                    .map(|value| {\n                        self.walk(*value, element, bits, native, context)\n                            .map(Box::new)\n                    })\n                    .transpose()?,\n            )),\n            (\"Either\", [left, _], Value::Left(value)) => Ok(Value::Left(Box::new(\n                self.walk(*value, left, bits, native, context)?,\n            ))),\n            (\"Either\", [_, right], Value::Right(value)) => Ok(Value::Right(Box::new(\n                self.walk(*value, right, bits, native, context)?,\n            ))),\n            _ => Err(format!(\"invalid value for {name}\").into()),\n        }\n    }\n}\n\n/// Build a user constructor selected and typed by the compiler. This does not\n/// validate its payload; generated bridges check each field at native boundaries.\npub fn construct_data(tag: &str, fields: Vec<Value>) -> Value {\n    Value::Data(tag.into(), fields)\n}\n\n/// Extract exactly one constructor's fields before typed field conversion.\n/// Tag and arity checks prevent cross-constructor coercion and dropped fields.\npub fn data_fields(value: Value, tag: &str, arity: usize) -> Result<Vec<Value>> {\n    match value {\n        Value::Data(actual, fields) if actual == tag && fields.len() == arity => Ok(fields),\n        Value::Data(actual, fields) => Err(format!(\n            \"expected {tag} with {arity} fields, found {actual} with {} fields\",\n            fields.len()\n        )),\n        _ => Err(format!(\"expected data constructor {tag}\")),\n    }\n}\n\npub fn all_elements(\n    value: Value,\n    mut predicate: impl FnMut(Value) -> Result<Value>,\n) -> Result<Value> {\n    let Value::List(values) = value else {\n        return Err(\"expected List in element predicate\".into());\n    };\n    for (index, item) in values.into_iter().enumerate() {\n        let accepted = predicate(item)\n            .and_then(|result| result.boolean())\n            .map_err(|error| format!(\"List element {index}: {error}\"))?;\n        if !accepted {\n            return Ok(Value::Bool(false));\n        }\n    }\n    Ok(Value::Bool(true))\n}\n\npub fn construct(tag: &str, mut fields: Vec<Value>) -> Result<Value> {\n    Ok(match (tag, fields.len()) {\n        (\"List::Nil\", 0) => Value::List(vec![]),\n        (\"List::Cons\", 2) => {\n            let Value::List(mut tail) = fields.pop().unwrap() else {\n                return Err(\"expected List tail\".into());\n            };\n            tail.insert(0, fields.pop().unwrap());\n            Value::List(tail)\n        }\n        (\"Maybe::Nothing\", 0) => Value::Maybe(None),\n        (\"Maybe::Just\", 1) => Value::Maybe(Some(Box::new(fields.pop().unwrap()))),\n        (\"Either::Left\", 1) => Value::Left(Box::new(fields.pop().unwrap())),\n        (\"Either::Right\", 1) => Value::Right(Box::new(fields.pop().unwrap())),\n        _ => return Err(format!(\"invalid constructor or arity: {tag}\")),\n    })\n}\n\n// Read one saturated type from the compiler's prefix encoding. Both arguments\n// of Either may themselves contain binary and unary type constructors.\nfn split_type(input: &str) -> Result<(&str, &str)> {\n    let (head, mut remaining) = input.split_once(' ').unwrap_or((input, \"\"));\n    if head.is_empty() {\n        return Err(\"missing type argument\".into());\n    }\n    let arity = match head {\n        \"Either\" => 2,\n        \"List\" | \"Maybe\" | \"Nullable\" | \"Optional\" => 1,\n        _ => 0,\n    };\n    for _ in 0..arity {\n        remaining = split_type(remaining)?.1;\n    }\n    Ok((input[..input.len() - remaining.len()].trim_end(), remaining))\n}\npub fn either_types(arguments: &str) -> Result<(&str, &str)> {\n    let (left, rest) = split_type(arguments)?;\n    let (right, extra) = split_type(rest)?;\n    if !extra.is_empty() {\n        return Err(\"extra Either type arguments\".into());\n    }\n    Ok((left, right))\n}\n\npub fn require_architecture(machine_bits: u32) -> Result<()> {\n    if usize::BITS == machine_bits {\n        Ok(())\n    } else {\n        Err(format!(\n            \"machineBits does not match native architecture: profile {machine_bits}, native {}\",\n            usize::BITS\n        ))\n    }\n}\n\npub fn helper(name: &str, mut args: Vec<Value>) -> Result<Value> {\n    use Value::*;\n    if name == \"round\" && args.len() == 2 {\n        let scale = i32::from_value(args.pop().unwrap())?;\n        return Ok(Decimal(self::Decimal::round(args[0].exact()?, scale)?));\n    }\n    if args.len() != 1 {\n        return Err(format!(\"invalid {name} arguments\"));\n    }\n    let value = args.pop().unwrap();\n    Ok(match name {\n        \"checked\" => Bool(true),\n        \"length\" => Integer(BigInt::from(match value {\n            Text(s) => s.chars().count(),\n            CodePointText(s) => s.len(),\n            Utf16Text(s) => s.len(),\n            Bytes(s) => s.len(),\n            List(s) => s.len(),\n            _ => return Err(\"length requires sequence\".into()),\n        })),\n        \"isPresent\" => Bool(match value {\n            Nullable(v) | Optional(v) => v.is_some(),\n            _ => return Err(\"expected presence\".into()),\n        }),\n        \"presentValue\" => match value {\n            Nullable(Some(v)) | Optional(Some(v)) => *v,\n            _ => return Err(\"absent value has no payload\".into()),\n        },\n        \"real\" => match value {\n            Complex32(c) => Float32(c.re),\n            Complex64(c) => Float64(c.re),\n            _ => return Err(\"expected complex value\".into()),\n        },\n        \"imag\" => match value {\n            Complex32(c) => Float32(c.im),\n            Complex64(c) => Float64(c.im),\n            _ => return Err(\"expected complex value\".into()),\n        },\n        \"isNaN\" => Bool(value.real64()?.is_nan()),\n        \"isInfinite\" => Bool(value.real64()?.is_infinite()),\n        \"isFinite\" => Bool(value.real64()?.is_finite()),\n        \"isNegativeZero\" => {\n            let x = value.real64()?;\n            Bool(x == 0.0 && x.is_sign_negative())\n        }\n        _ => return Err(format!(\"unknown helper: {name}\")),\n    })\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    fn int(n: i64) -> Value {\n        Value::Integer(n.into())\n    }\n    fn decimal(c: i64, e: i64) -> Value {\n        Value::Decimal(Decimal::new(c.into(), e.into()))\n    }\n    #[test]\n    fn data_bridges_check_constructor_identity_arity_and_typed_fields() {\n        let tag = \"example::type::Pair::Pair\";\n        let value = construct_data(tag, vec![int(127), Value::Bool(true)]);\n        let fields = data_fields(value.clone(), tag, 2).unwrap();\n        assert_eq!(i8::from_value(fields[0].clone()).unwrap(), 127);\n        assert!(data_fields(value.clone(), \"other::type::Pair::Pair\", 2).is_err());\n        assert!(data_fields(value.clone(), tag, 1).is_err());\n        assert!(data_fields(value, tag, 3).is_err());\n        assert!(data_fields(Value::List(vec![]), tag, 0).is_err());\n        let overflow = data_fields(construct_data(tag, vec![int(128)]), tag, 1).unwrap();\n        assert!(i8::from_value(overflow[0].clone()).is_err());\n    }\n\n    #[test]\n    fn data_equality_preserves_ieee_and_constructor_semantics() {\n        let tag = \"example::type::Box::Box\";\n        let boxed = |value| construct_data(tag, vec![value]);\n        let nan = boxed(Value::List(vec![Value::Float32(f32::NAN)]));\n        assert!(!equal(&nan, &nan).unwrap());\n        assert!(equal(&boxed(Value::Float64(-0.0)), &boxed(Value::Float64(0.0))).unwrap());\n        assert!(!equal(&boxed(int(1)), &construct_data(tag, vec![int(1), int(2)])).unwrap());\n        assert!(\n            !equal(\n                &boxed(int(1)),\n                &construct_data(\"example::type::Other::Box\", vec![int(1)])\n            )\n            .unwrap()\n        );\n        assert!(equal(&boxed(int(1)), &boxed(Value::Float64(1.0))).is_err());\n    }\n\n    #[test]\n    fn nested_data_keeps_absence_raw_units_and_symbol_identity() {\n        let tag = \"example::type::Record::Record\";\n        let symbol = Symbol::new(\"same description\".into());\n        let record = |symbol| {\n            construct_data(\n                tag,\n                vec![\n                    Value::Maybe(Some(Box::new(Value::Maybe(None)))),\n                    Value::Utf16Text(vec![0xd800, 0, 0xdfff]),\n                    Value::Bytes(vec![0, 0xff]),\n                    Value::Symbol(symbol),\n                ],\n            )\n        };\n        let original = record(symbol.clone());\n        assert!(equal(&original, &record(symbol)).unwrap());\n        assert!(!equal(&original, &record(Symbol::new(\"same description\".into()))).unwrap());\n        let mut fields = data_fields(original.clone(), tag, 4).unwrap();\n        fields[0] = Value::Maybe(None);\n        assert!(!equal(&original, &construct_data(tag, fields)).unwrap());\n    }\n\n    #[test]\n    fn integer_promotion_and_checked_bridges() {\n        let result = binary(\"+\", \"Integer\", 127i8.into_value(), int(1)).unwrap();\n        assert_eq!(result, int(128));\n        assert!(i8::from_value(result).is_err());\n        assert_eq!(\n            u64::from_value(Value::Integer(u64::MAX.into())).unwrap(),\n            u64::MAX\n        );\n        assert_eq!(Integer::from(u128::MAX).0, BigInt::from(u128::MAX));\n        assert!(u64::from_value(int(-1)).is_err());\n        assert!(i32::from_value(Value::Rational(BigRational::new(1.into(), 2.into()))).is_err());\n    }\n    #[test]\n    fn exact_decimal_and_rational_arithmetic() {\n        assert!(\n            equal(\n                &binary(\"+\", \"Decimal\", decimal(1, -1), decimal(2, -1)).unwrap(),\n                &decimal(3, -1)\n            )\n            .unwrap()\n        );\n        let half = binary(\"/\", \"Rational\", int(1), int(2)).unwrap();\n        assert_eq!(half, Value::Rational(BigRational::new(1.into(), 2.into())));\n        assert!(binary(\"/\", \"Rational\", int(1), int(0)).is_err());\n        assert!(\n            Value::Rational(BigRational::new(1.into(), 3.into()))\n                .convert(\"Decimal\", 64)\n                .is_err()\n        );\n        assert_eq!(binary(\"quot\", \"Integer\", int(-7), int(3)).unwrap(), int(-2));\n        assert_eq!(binary(\"rem\", \"Integer\", int(-7), int(3)).unwrap(), int(-1));\n    }\n    #[test]\n    fn decimal_rounds_half_even_at_requested_scale() {\n        for (numerator, expected) in [(125, 12), (135, 14), (-125, -12), (-135, -14)] {\n            let d = Decimal::round(BigRational::new(numerator.into(), 100.into()), 1).unwrap();\n            assert!(equal(&Value::Decimal(d), &decimal(expected, -1)).unwrap());\n        }\n        let hundred = Decimal::round(BigRational::from_integer(250.into()), -2).unwrap();\n        assert!(equal(&Value::Decimal(hundred), &int(200)).unwrap());\n    }\n    #[test]\n    fn ieee_equality_classification_and_precision() {\n        assert!(binary(\"+\", \"Float32\", int(1), Value::Float32(1.0)).is_err());\n        assert!(equal(&int(1), &Value::Float32(1.0)).is_err());\n        assert!(!equal(&Value::Float32(f32::NAN), &Value::Float32(f32::NAN)).unwrap());\n        assert!(equal(&Value::Float64(0.0), &Value::Float64(-0.0)).unwrap());\n        assert_eq!(\n            helper(\"isNegativeZero\", vec![Value::Float32(-0.0)]).unwrap(),\n            Value::Bool(true)\n        );\n        assert_eq!(\n            binary(\n                \"+\",\n                \"Float32\",\n                Value::Float32(16777216.0),\n                Value::Float32(1.0)\n            )\n            .unwrap(),\n            Value::Float32(16777216.0)\n        );\n        assert_eq!(\n            binary(\"/\", \"Float64\", Value::Float64(1.0), Value::Float64(0.0)).unwrap(),\n            Value::Float64(f64::INFINITY)\n        );\n        assert!(\n            Value::Float64(f64::INFINITY)\n                .convert(\"Integer\", 64)\n                .is_err()\n        );\n        assert_eq!(\n            Value::Float64(0.5).convert(\"Rational\", 64).unwrap(),\n            Value::Rational(BigRational::new(1.into(), 2.into()))\n        );\n    }\n    #[test]\n    fn nested_code_units_cross_native_bridges_without_losing_the_domain() {\n        let native: Optional<Nullable<u16>> = Optional::Present(Nullable::Present(0xd800));\n        let value = validate(\n            native.clone().into_value(),\n            \"Optional Nullable CodeUnit16\",\n            64,\n        )\n        .unwrap();\n        assert_eq!(\n            value,\n            Value::Optional(Some(Box::new(Value::Nullable(Some(Box::new(\n                Value::CodeUnit16(0xd800)\n            ))))))\n        );\n        let round_trip = Optional::<Nullable<u16>>::from_value(\n            native_value(value, \"Optional Nullable CodeUnit16\").unwrap(),\n        )\n        .unwrap();\n        assert_eq!(round_trip, native);\n        assert!(validate(Value::CodePoint(0x110000), \"CodePoint\", 64).is_err());\n    }\n    #[test]\n    fn exact_float_conversion_avoids_double_rounding() {\n        let n = BigInt::parse_bytes(b\"1208925891672223212634113\", 10).unwrap();\n        let d = BigInt::parse_bytes(b\"1208925819614629174706176\", 10).unwrap();\n        assert_eq!(\n            exact_float_bits(&BigRational::new(n, d), true).unwrap(),\n            0x3f800001\n        );\n        assert_eq!(\n            exact_float_bits(&BigRational::new(16777217.into(), 16777216.into()), true).unwrap(),\n            0x3f800000\n        );\n        assert_eq!(\n            exact_float_bits(&BigRational::new(1.into(), BigInt::one() << 150usize), true).unwrap(),\n            0\n        );\n        assert_eq!(\n            exact_float_bits(\n                &BigRational::new((-1).into(), BigInt::one() << 150usize),\n                true\n            )\n            .unwrap(),\n            0x80000000\n        );\n        assert_eq!(\n            exact_float_bits(\n                &BigRational::from_integer(BigInt::one() << 1024usize),\n                false\n            )\n            .unwrap(),\n            f64::INFINITY.to_bits()\n        );\n    }\n    #[test]\n    fn raw_text_symbols_and_nested_presence_remain_distinct() {\n        let raw = Utf16Text(vec![0xd800, 0, 0xdc00]);\n        assert_eq!(\n            Utf16Text::from_value(raw.clone().into_value()).unwrap(),\n            raw\n        );\n        assert!(CodePoint::from_value(Value::CodePoint(0xd800)).is_ok());\n        assert!(CodePoint::from_value(Value::CodePoint(0x110000)).is_err());\n        let mut context = Context::default();\n        assert_eq!(context.symbol(\"a\", \"same\"), context.symbol(\"a\", \"same\"));\n        assert_ne!(context.symbol(\"a\", \"same\"), context.symbol(\"b\", \"same\"));\n        let absent: Optional<Nullable<i8>> = Optional::Undefined;\n        let null: Optional<Nullable<i8>> = Optional::Present(Nullable::Null);\n        let some: Optional<Nullable<i8>> = Optional::Present(Nullable::Present(0));\n        assert_ne!(absent.clone().into_value(), null.clone().into_value());\n        assert_ne!(null.clone().into_value(), some.clone().into_value());\n        for x in [absent, null, some] {\n            assert_eq!(\n                Optional::<Nullable<i8>>::from_value(x.clone().into_value()).unwrap(),\n                x\n            );\n        }\n    }\n}\n\npub fn validate(value: Value, name: &str, bits: u32) -> Result<Value> {\n    if let Some(inner) = name.strip_prefix(\"List \") {\n        return match value {\n            Value::List(values) => Ok(Value::List(\n                values\n                    .into_iter()\n                    .map(|x| validate(x, inner, bits))\n                    .collect::<Result<_>>()?,\n            )),\n            _ => Err(\"expected List\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Maybe \") {\n        return match value {\n            Value::Maybe(value) => Ok(Value::Maybe(\n                value\n                    .map(|x| validate(*x, inner, bits).map(Box::new))\n                    .transpose()?,\n            )),\n            _ => Err(\"expected Maybe\".into()),\n        };\n    }\n    if let Some(arguments) = name.strip_prefix(\"Either \") {\n        let (left, right) = either_types(arguments)?;\n        return match value {\n            Value::Left(x) => Ok(Value::Left(Box::new(validate(*x, left, bits)?))),\n            Value::Right(x) => Ok(Value::Right(Box::new(validate(*x, right, bits)?))),\n            _ => Err(\"expected Either\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Nullable \") {\n        return match value {\n            Value::Nullable(None) => Ok(Value::Nullable(None)),\n            Value::Nullable(Some(x)) => {\n                Ok(Value::Nullable(Some(Box::new(validate(*x, inner, bits)?))))\n            }\n            _ => Err(\"expected Nullable\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Optional \") {\n        return match value {\n            Value::Optional(None) => Ok(Value::Optional(None)),\n            Value::Optional(Some(x)) => {\n                Ok(Value::Optional(Some(Box::new(validate(*x, inner, bits)?))))\n            }\n            _ => Err(\"expected Optional\".into()),\n        };\n    }\n    if name == \"Bytes\" {\n        if let Value::List(values) = value {\n            return Ok(Value::Bytes(\n                values\n                    .into_iter()\n                    .map(u8::from_value)\n                    .collect::<Result<_>>()?,\n            ));\n        }\n    }\n    if name == \"CodeUnit16\" {\n        return match value {\n            Value::CodeUnit16(x) => Ok(Value::CodeUnit16(x)),\n            x => Ok(Value::CodeUnit16(u16::from_value(x)?)),\n        };\n    }\n    let valid = match (&value, name) {\n        (Value::Integer(_), _) => return value.convert(name, bits),\n        (Value::Decimal(d), \"Decimal\") => {\n            d.ratio()?;\n            true\n        }\n        (Value::Rational(_), \"Rational\")\n        | (Value::Float32(_), \"Float32\")\n        | (Value::Float64(_), \"Float64\")\n        | (Value::Complex32(_), \"Complex64\")\n        | (Value::Complex64(_), \"Complex128\")\n        | (Value::Bool(_), \"Bool\")\n        | (Value::Char(_), \"Char\")\n        | (Value::CodeUnit16(_), \"CodeUnit16\")\n        | (Value::Text(_), \"Text\")\n        | (Value::Bytes(_), \"Bytes\")\n        | (Value::Utf16Text(_), \"Utf16Text\")\n        | (Value::Symbol(_), \"Symbol\")\n        | (Value::Unit, \"Unit\")\n        | (Value::Null, \"Null\")\n        | (Value::Undefined, \"Undefined\") => true,\n        (Value::CodePoint(c), \"CodePoint\") => *c <= 0x10ffff,\n        (Value::CodePointText(cs), \"CodePointText\") => cs.iter().all(|c| *c <= 0x10ffff),\n        _ => false,\n    };\n    if valid {\n        Ok(value)\n    } else {\n        Err(format!(\"invalid {name} representation returned by adapter\"))\n    }\n}\n\n/// Type-directed native bridge for nested domains that share a Rust primitive.\npub fn native_value(value: Value, name: &str) -> Result<Value> {\n    if let Some(inner) = name.strip_prefix(\"List \") {\n        return match value {\n            Value::List(values) => Ok(Value::List(\n                values\n                    .into_iter()\n                    .map(|x| native_value(x, inner))\n                    .collect::<Result<_>>()?,\n            )),\n            _ => Err(\"expected List\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Maybe \") {\n        return match value {\n            Value::Maybe(value) => Ok(Value::Maybe(\n                value\n                    .map(|x| native_value(*x, inner).map(Box::new))\n                    .transpose()?,\n            )),\n            _ => Err(\"expected Maybe\".into()),\n        };\n    }\n    if let Some(arguments) = name.strip_prefix(\"Either \") {\n        let (left, right) = either_types(arguments)?;\n        return match value {\n            Value::Left(x) => Ok(Value::Left(Box::new(native_value(*x, left)?))),\n            Value::Right(x) => Ok(Value::Right(Box::new(native_value(*x, right)?))),\n            _ => Err(\"expected Either\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Nullable \") {\n        return match value {\n            Value::Nullable(Some(x)) => {\n                Ok(Value::Nullable(Some(Box::new(native_value(*x, inner)?))))\n            }\n            Value::Nullable(None) => Ok(Value::Nullable(None)),\n            _ => Err(\"expected Nullable\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Optional \") {\n        return match value {\n            Value::Optional(Some(x)) => {\n                Ok(Value::Optional(Some(Box::new(native_value(*x, inner)?))))\n            }\n            Value::Optional(None) => Ok(Value::Optional(None)),\n            _ => Err(\"expected Optional\".into()),\n        };\n    }\n    match (value, name) {\n        (Value::CodeUnit16(x), \"CodeUnit16\") => Ok(Value::Integer(x.into())),\n        (v, _) => Ok(v),\n    }\n}\n\n#[cfg(test)]\nmod collection_tests {\n    use super::*;\n\n    #[test]\n    fn nested_collections_preserve_code_units_and_bytes() {\n        let native: Vec<Option<Either<u16, Vec<u8>>>> = vec![\n            None,\n            Some(Either::Left(0xd800)),\n            Some(Either::Right(vec![0, 255])),\n        ];\n        let domain = \"List Maybe Either CodeUnit16 Bytes\";\n        let value = validate(native.clone().into_value(), domain, 64).unwrap();\n        let Value::List(ref items) = value else {\n            panic!(\"expected List\");\n        };\n        assert_eq!(items[0], Value::Maybe(None));\n        assert_eq!(\n            items[1],\n            Value::Maybe(Some(Box::new(Value::Left(Box::new(Value::CodeUnit16(\n                0xd800\n            ))))))\n        );\n        assert_eq!(\n            items[2],\n            Value::Maybe(Some(Box::new(Value::Right(Box::new(Value::Bytes(vec![\n                0, 255\n            ]))))))\n        );\n        let actual =\n            Vec::<Option<Either<u16, Vec<u8>>>>::from_value(native_value(value, domain).unwrap())\n                .unwrap();\n        assert_eq!(actual, native);\n    }\n\n    #[test]\n    fn structural_equality_preserves_tags_ieee_rules_and_length() {\n        let nan = Value::List(vec![Value::Float32(f32::NAN)]);\n        assert!(!equal(&nan, &nan).unwrap());\n        assert!(\n            equal(\n                &Value::List(vec![Value::Float64(-0.0)]),\n                &Value::List(vec![Value::Float64(0.0)])\n            )\n            .unwrap()\n        );\n        assert!(\n            !equal(\n                &Value::Left(Box::new(Value::Bool(true))),\n                &Value::Right(Box::new(Value::Bool(true)))\n            )\n            .unwrap()\n        );\n        assert!(!equal(&Value::List(vec![]), &Value::List(vec![Value::Unit])).unwrap());\n        assert!(\n            !equal(\n                &Value::Maybe(None),\n                &Value::Maybe(Some(Box::new(Value::Maybe(None))))\n            )\n            .unwrap()\n        );\n    }\n\n    #[test]\n    fn collection_domains_reject_bad_payloads_and_do_not_collapse_presence() {\n        assert!(\n            validate(\n                Value::List(vec![Value::Integer(128.into())]),\n                \"List Int8\",\n                64\n            )\n            .is_err()\n        );\n        assert!(validate(Value::Nullable(None), \"Maybe Bool\", 64).is_err());\n        assert!(validate(Value::Maybe(None), \"Nullable Bool\", 64).is_err());\n        assert!(\n            validate(\n                Value::Left(Box::new(Value::Bool(true))),\n                \"Either Int8 Bool\",\n                64\n            )\n            .is_err()\n        );\n        assert!(construct(\"List::Cons\", vec![Value::Bool(true), Value::Bool(false)]).is_err());\n        assert_eq!(\n            validate(vec![0u8, 255].into_value(), \"Bytes\", 64).unwrap(),\n            Value::Bytes(vec![0, 255])\n        );\n        assert!(matches!(\n            validate(vec![0u8, 255].into_value(), \"List UInt8\", 64).unwrap(),\n            Value::List(_)\n        ));\n        assert_eq!(\n            either_types(\"Either Bool Unit List Maybe Int8\").unwrap(),\n            (\"Either Bool Unit\", \"List Maybe Int8\")\n        );\n    }\n}\n\n#[cfg(test)]\nmod schema_tests {\n    use super::*;\n\n    fn ty(name: &'static str) -> TypeRef {\n        TypeRef::named(name, vec![])\n    }\n\n    fn box_type(element: TypeRef) -> TypeRef {\n        TypeRef::named(\"example::Box\", vec![element])\n    }\n\n    fn schema() -> Schema {\n        Schema::new(vec![\n            DataSchema {\n                name: \"example::Box\",\n                parameters: 1,\n                constructors: vec![ConstructorSchema {\n                    tag: \"example::Box::Box\",\n                    fields: vec![TypeRef::Parameter(0)],\n                }],\n            },\n            DataSchema {\n                name: \"example::Tree\",\n                parameters: 1,\n                constructors: vec![\n                    ConstructorSchema {\n                        tag: \"example::Tree::Leaf\",\n                        fields: vec![TypeRef::Parameter(0)],\n                    },\n                    ConstructorSchema {\n                        tag: \"example::Tree::Branch\",\n                        fields: vec![TypeRef::named(\n                            \"List\",\n                            vec![TypeRef::named(\"example::Tree\", vec![TypeRef::Parameter(0)])],\n                        )],\n                    },\n                ],\n            },\n        ])\n        .unwrap()\n    }\n\n    #[test]\n    fn validates_recursive_instantiated_fields_and_reports_the_payload_path() {\n        let schema = schema();\n        let tree = TypeRef::named(\"example::Tree\", vec![ty(\"Int8\")]);\n        let value = |integer: i64| {\n            construct_data(\n                \"example::Tree::Branch\",\n                vec![Value::List(vec![construct_data(\n                    \"example::Tree::Leaf\",\n                    vec![Value::Integer(integer.into())],\n                )])],\n            )\n        };\n        assert_eq!(schema.validate(value(127), &tree, 64).unwrap(), value(127));\n        let error = schema.validate(value(128), &tree, 64).unwrap_err();\n        assert!(error.contains(\"example::Tree::Branch field 0\"));\n        assert!(error.contains(\"List element 0\"));\n        assert!(error.contains(\"example::Tree::Leaf field 0\"));\n        assert!(\n            schema\n                .validate(\n                    construct_data(\"example::Box::Box\", vec![Value::Integer(1.into())]),\n                    &tree,\n                    64,\n                )\n                .is_err()\n        );\n        assert!(\n            schema\n                .validate(construct_data(\"example::Tree::Leaf\", vec![]), &tree, 64)\n                .is_err()\n        );\n    }\n\n    #[test]\n    fn preserves_nested_raw_domains_across_native_bridges() {\n        let schema = schema();\n        let element = box_type(ty(\"CodeUnit16\"));\n        let logical = TypeRef::named(\"Maybe\", vec![TypeRef::named(\"List\", vec![element])]);\n        let value = Value::Maybe(Some(Box::new(Value::List(vec![construct_data(\n            \"example::Box::Box\",\n            vec![Value::CodeUnit16(0xd800)],\n        )]))));\n        let native = schema.native_value(value.clone(), &logical, 64).unwrap();\n        assert_ne!(value, native);\n        assert_eq!(schema.validate(native, &logical, 64).unwrap(), value);\n        let bytes = box_type(ty(\"Bytes\"));\n        let native_bytes = construct_data(\"example::Box::Box\", vec![vec![0u8, 255u8].into_value()]);\n        assert_eq!(\n            schema.validate(native_bytes, &bytes, 64).unwrap(),\n            construct_data(\"example::Box::Box\", vec![Value::Bytes(vec![0, 255])])\n        );\n        assert!(schema.validate(Value::Maybe(None), &logical, 64).is_ok());\n    }\n\n    #[test]\n    fn checks_machine_width_and_scalar_domains_inside_user_values() {\n        let schema = schema();\n        let value = construct_data(\n            \"example::Box::Box\",\n            vec![Value::Integer((1u64 << 32).into())],\n        );\n        let target = box_type(ty(\"UIntSize\"));\n        assert!(schema.validate(value.clone(), &target, 32).is_err());\n        assert!(schema.validate(value.clone(), &target, 64).is_ok());\n        assert!(schema.validate(value.clone(), &target, 16).is_err());\n        assert!(schema.native_value(value, &target, 16).is_err());\n        assert!(\n            schema\n                .validate(\n                    construct_data(\"example::Box::Box\", vec![Value::Float32(1.0)]),\n                    &box_type(ty(\"Int8\")),\n                    64,\n                )\n                .is_err()\n        );\n    }\n\n    #[test]\n    fn rejects_corrupt_schemas_and_unapplied_types() {\n        let definition = |name, field| DataSchema {\n            name,\n            parameters: 1,\n            constructors: vec![ConstructorSchema {\n                tag: \"unique::Tag\",\n                fields: vec![field],\n            }],\n        };\n        assert!(Schema::new(vec![definition(\"Bad\", TypeRef::Parameter(1))]).is_err());\n        assert!(Schema::new(vec![definition(\"Bad\", ty(\"Unknown\"))]).is_err());\n        assert!(Schema::new(vec![definition(\"Bad\", ty(\"Maybe\"))]).is_err());\n        assert!(Schema::new(vec![definition(\"Bool\", TypeRef::Parameter(0))]).is_err());\n        assert!(\n            Schema::new(vec![\n                definition(\"First\", TypeRef::Parameter(0)),\n                definition(\"Second\", TypeRef::Parameter(0)),\n            ])\n            .is_err()\n        );\n        let schema = schema();\n        let value = construct_data(\"example::Box::Box\", vec![Value::Bool(true)]);\n        assert!(\n            schema\n                .validate(value.clone(), &ty(\"example::Box\"), 64)\n                .is_err()\n        );\n        assert!(schema.validate(value, &TypeRef::Parameter(0), 64).is_err());\n    }\n}\n\n#[cfg(test)]\nmod constructor_contract_tests {\n    use super::*;\n\n    fn ty(name: &'static str) -> TypeRef {\n        TypeRef::named(name, vec![])\n    }\n\n    fn schema(predicates: Vec<FieldPredicate>, element: &'static str) -> Schema {\n        Schema::with_contracts(\n            vec![DataSchema {\n                name: \"Box\",\n                parameters: 1,\n                constructors: vec![ConstructorSchema {\n                    tag: \"Box::Box\",\n                    fields: vec![TypeRef::Parameter(0)],\n                }],\n            }],\n            vec![ConstructorContract {\n                tag: \"Box::Box\",\n                predicates,\n            }],\n        )\n        .and_then(|schema| {\n            schema.check_type(&TypeRef::named(\"Box\", vec![ty(element)]), 0)?;\n            Ok(schema)\n        })\n        .unwrap()\n    }\n\n    fn value(field: Value) -> Value {\n        construct_data(\"Box::Box\", vec![field])\n    }\n\n    fn positive(\n        _: &Schema,\n        arguments: &[TypeRef],\n        fields: &[Value],\n        bits: u32,\n        _: &mut Context,\n    ) -> Result<bool> {\n        assert_eq!(arguments, &[ty(\"IntSize\")]);\n        assert!(matches!(bits, 32 | 64));\n        let [Value::Integer(n)] = fields else {\n            return Err(\"expected logical integer\".into());\n        };\n        Ok(n > &BigInt::zero())\n    }\n\n    #[test]\n    fn contracts_check_native_and_logical_boundaries_at_both_widths() {\n        let schema = schema(vec![positive], \"IntSize\");\n        let ty = TypeRef::named(\"Box\", vec![ty(\"IntSize\")]);\n        for bits in [32, 64] {\n            let good = value(Value::Integer(1.into()));\n            let bad = value(Value::Integer(0.into()));\n            assert_eq!(schema.validate(good.clone(), &ty, bits).unwrap(), good);\n            assert_eq!(schema.native_value(good.clone(), &ty, bits).unwrap(), good);\n            assert!(schema.validate(bad.clone(), &ty, bits).is_err());\n            assert!(schema.native_value(bad.clone(), &ty, bits).is_err());\n            assert!(matches!(\n                schema\n                    .check_with_context(bad, &ty, bits, &mut Context::default())\n                    .unwrap(),\n                ValueCheck::Rejected(_)\n            ));\n        }\n        let large = value(Value::Integer(BigInt::from(1u64 << 40)));\n        assert!(schema.validate(large.clone(), &ty, 32).is_err());\n        assert!(schema.validate(large, &ty, 64).is_ok());\n    }\n\n    #[test]\n    fn predicates_short_circuit_and_do_not_hide_evaluator_errors() {\n        fn reject(_: &Schema, _: &[TypeRef], _: &[Value], _: u32, _: &mut Context) -> Result<bool> {\n            Ok(false)\n        }\n        fn broken(_: &Schema, _: &[TypeRef], _: &[Value], _: u32, _: &mut Context) -> Result<bool> {\n            Err(\"broken predicate\".into())\n        }\n        let ty = TypeRef::named(\"Box\", vec![ty(\"Bool\")]);\n        let good = value(Value::Bool(true));\n        assert!(matches!(\n            schema(vec![reject, broken], \"Bool\")\n                .check_with_context(good.clone(), &ty, 64, &mut Context::default())\n                .unwrap(),\n            ValueCheck::Rejected(_)\n        ));\n        let error = schema(vec![broken], \"Bool\")\n            .check_with_context(good, &ty, 64, &mut Context::default())\n            .unwrap_err();\n        assert!(error.contains(\"field refinement 1: broken predicate\"));\n        assert!(\n            schema(vec![reject], \"Bool\")\n                .check_with_context(\n                    value(Value::Text(\"wrong\".into())),\n                    &ty,\n                    64,\n                    &mut Context::default()\n                )\n                .is_err()\n        );\n    }\n\n    #[test]\n    fn native_code_unit_conversion_follows_contract_validation() {\n        fn surrogate(\n            _: &Schema,\n            _: &[TypeRef],\n            fields: &[Value],\n            _: u32,\n            _: &mut Context,\n        ) -> Result<bool> {\n            match fields {\n                [Value::CodeUnit16(value)] => Ok(*value == 0xd800),\n                _ => Err(\"predicate must receive a logical code unit\".into()),\n            }\n        }\n        let schema = schema(vec![surrogate], \"CodeUnit16\");\n        let ty = TypeRef::named(\"Box\", vec![ty(\"CodeUnit16\")]);\n        let logical = value(Value::CodeUnit16(0xd800));\n        let native = schema.native_value(logical.clone(), &ty, 64).unwrap();\n        assert_eq!(native, value(Value::Integer(0xd800.into())));\n        assert_eq!(schema.validate(native, &ty, 64).unwrap(), logical);\n        assert!(\n            schema\n                .native_value(value(Value::CodeUnit16(0)), &ty, 64)\n                .is_err()\n        );\n    }\n\n    #[test]\n    fn nested_symbols_share_context_and_keep_rejection_paths() {\n        fn fixture(\n            _: &Schema,\n            _: &[TypeRef],\n            fields: &[Value],\n            _: u32,\n            context: &mut Context,\n        ) -> Result<bool> {\n            equal(\n                &fields[0],\n                &Value::Symbol(context.symbol(\"fixture\", \"same\")),\n            )\n        }\n        let schema = schema(vec![fixture], \"Symbol\");\n        let mut context = Context::default();\n        let box_type = TypeRef::named(\"Box\", vec![ty(\"Symbol\")]);\n        let expected = value(Value::Symbol(context.symbol(\"fixture\", \"same\")));\n        let cases = vec![\n            (\n                TypeRef::named(\"List\", vec![box_type.clone()]),\n                Value::List(vec![expected.clone()]),\n            ),\n            (\n                TypeRef::named(\"Maybe\", vec![box_type.clone()]),\n                Value::Maybe(Some(Box::new(expected.clone()))),\n            ),\n            (\n                TypeRef::named(\"Nullable\", vec![box_type.clone()]),\n                Value::Nullable(Some(Box::new(expected.clone()))),\n            ),\n            (\n                TypeRef::named(\"Optional\", vec![box_type.clone()]),\n                Value::Optional(Some(Box::new(expected.clone()))),\n            ),\n            (\n                TypeRef::named(\"Either\", vec![box_type.clone(), box_type.clone()]),\n                Value::Right(Box::new(expected.clone())),\n            ),\n        ];\n        for (ty, logical) in cases {\n            let native = schema\n                .native_value_with_context(logical.clone(), &ty, 64, &mut context)\n                .unwrap();\n            let restored = schema\n                .validate_with_context(native, &ty, 64, &mut context)\n                .unwrap();\n            assert!(equal(&logical, &restored).unwrap());\n            assert!(matches!(\n                schema\n                    .check_with_context(logical, &ty, 64, &mut Context::default())\n                    .unwrap(),\n                ValueCheck::Rejected(_)\n            ));\n        }\n        let list = TypeRef::named(\"List\", vec![box_type.clone()]);\n        let outcome = schema\n            .check_with_context(\n                Value::List(vec![expected]),\n                &list,\n                64,\n                &mut Context::default(),\n            )\n            .unwrap();\n        let ValueCheck::Rejected(message) = outcome else {\n            panic!(\"expected rejection\")\n        };\n        assert!(message.contains(\"List element 0\"));\n        assert!(matches!(\n            schema\n                .check_with_context(\n                    value(Value::Symbol(Symbol::new(\"same\".into()))),\n                    &box_type,\n                    64,\n                    &mut context\n                )\n                .unwrap(),\n            ValueCheck::Rejected(_)\n        ));\n    }\n\n    #[test]\n    fn contract_metadata_rejects_unknown_and_duplicate_constructor_tags() {\n        assert!(\n            Schema::with_contracts(\n                vec![],\n                vec![ConstructorContract {\n                    tag: \"Unknown\",\n                    predicates: vec![positive],\n                }]\n            )\n            .is_err()\n        );\n        let definitions = vec![DataSchema {\n            name: \"Box\",\n            parameters: 0,\n            constructors: vec![ConstructorSchema {\n                tag: \"Box\",\n                fields: vec![],\n            }],\n        }];\n        assert!(\n            Schema::with_contracts(\n                definitions,\n                vec![\n                    ConstructorContract {\n                        tag: \"Box\",\n                        predicates: vec![]\n                    },\n                    ConstructorContract {\n                        tag: \"Box\",\n                        predicates: vec![]\n                    },\n                ]\n            )\n            .is_err()\n        );\n    }\n}\n"
runtimeSource "rust-strategies" = "//! Proptest support, separate from the reusable numeric runtime.\nuse crate::lawspec_runtime::{self as ls, IntoValue, Value};\nuse proptest::prelude::*;\n\n/// A framework-native factory. Child strategies correspond to type parameters,\n/// not constructor fields. Mapping the returned strategy retains its ValueTree.\npub type NativeFactory = fn(\n    &ls::Schema,\n    &ls::TypeRef,\n    u32,\n    &ls::Context,\n    Vec<BoxedStrategy<Value>>,\n) -> ls::Result<BoxedStrategy<Value>>;\n\n#[derive(Default)]\npub struct NativeGenerators {\n    factories: std::collections::HashMap<&'static str, NativeFactory>,\n}\n\nimpl NativeGenerators {\n    pub fn new(entries: Vec<(&'static str, NativeFactory)>) -> ls::Result<Self> {\n        let mut factories = std::collections::HashMap::new();\n        for (name, factory) in entries {\n            if name.is_empty() || factories.insert(name, factory).is_some() {\n                return Err(format!(\"duplicate or empty native generator: {name}\"));\n            }\n        }\n        Ok(Self { factories })\n    }\n\n    fn factory(&self, ty: &ls::TypeRef) -> Option<NativeFactory> {\n        match ty {\n            ls::TypeRef::Named(name, _) => self.factories.get(name).copied(),\n            _ => None,\n        }\n    }\n}\n\npub fn schema_strategy_with_generators(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    context: &ls::Context,\n    native: &NativeGenerators,\n) -> ls::Result<BoxedStrategy<Value>> {\n    if schema.has_contracts() {\n        return Err(\"constructor contracts require checked_schema_strategy_with_generators\".into());\n    }\n    shape_strategy_with_generators(\n        schema,\n        ty,\n        bits,\n        budget,\n        Default::default(),\n        context,\n        native,\n    )\n}\n\npub fn strategy(name: &str) -> ls::Result<BoxedStrategy<Value>> {\n    strategy_with_profile(name, usize::BITS)\n}\n\nfn scalar_strategy(name: &str) -> ls::Result<BoxedStrategy<Value>> {\n    if let Some(inner) = name.strip_prefix(\"Nullable \") {\n        return Ok(proptest::option::of(strategy(inner)?)\n            .prop_map(|x| Value::Nullable(x.map(Box::new)))\n            .boxed());\n    }\n    if let Some(inner) = name.strip_prefix(\"Optional \") {\n        return Ok(proptest::option::of(strategy(inner)?)\n            .prop_map(|x| Value::Optional(x.map(Box::new)))\n            .boxed());\n    }\n    macro_rules! integer {\n        ($t:ty) => {\n            any::<$t>().prop_map(IntoValue::into_value).boxed()\n        };\n    }\n    Ok(match name {\n        \"Bool\" => any::<bool>().prop_map(Value::Bool).boxed(),\n        \"Int8\" => integer!(i8),\n        \"Int16\" => integer!(i16),\n        \"Int32\" => integer!(i32),\n        \"Int64\" => integer!(i64),\n        \"UInt8\" => integer!(u8),\n        \"UInt16\" => integer!(u16),\n        \"UInt32\" => integer!(u32),\n        \"UInt64\" => integer!(u64),\n        \"IntSize\" => integer!(isize),\n        \"UIntSize\" | \"UIntPtr\" => integer!(usize),\n        \"Integer\" | \"BigInt\" => bigint().prop_map(Value::Integer).boxed(),\n        \"BigUInt\" => proptest::collection::vec(any::<u8>(), 0..65)\n            .prop_map(|bytes| {\n                Value::Integer(ls::BigInt::from_bytes_le(num_bigint::Sign::Plus, &bytes))\n            })\n            .boxed(),\n        \"Decimal\" => (bigint(), -100i32..101)\n            .prop_map(|(c, e)| Value::Decimal(ls::Decimal::new(c, e.into())))\n            .boxed(),\n        \"Rational\" => (bigint(), 1u64..=u64::MAX)\n            .prop_map(|(n, d)| Value::Rational(ls::BigRational::new(n, d.into())))\n            .boxed(),\n        \"Float32\" => any::<u32>()\n            .prop_map(|b| Value::Float32(f32::from_bits(b)))\n            .boxed(),\n        \"Float64\" => any::<u64>()\n            .prop_map(|b| Value::Float64(f64::from_bits(b)))\n            .boxed(),\n        \"Complex64\" => (any::<u32>(), any::<u32>())\n            .prop_map(|(r, i)| {\n                Value::Complex32(ls::Complex32::new(f32::from_bits(r), f32::from_bits(i)))\n            })\n            .boxed(),\n        \"Complex128\" => (any::<u64>(), any::<u64>())\n            .prop_map(|(r, i)| {\n                Value::Complex64(ls::Complex64::new(f64::from_bits(r), f64::from_bits(i)))\n            })\n            .boxed(),\n        \"Char\" => any::<char>().prop_map(Value::Char).boxed(),\n        \"CodePoint\" => (0u32..=0x10ffff).prop_map(Value::CodePoint).boxed(),\n        \"CodeUnit16\" => any::<u16>().prop_map(Value::CodeUnit16).boxed(),\n        \"Text\" => proptest::collection::vec(any::<char>(), 0..65)\n            .prop_map(|cs| Value::Text(cs.into_iter().collect()))\n            .boxed(),\n        \"CodePointText\" => proptest::collection::vec(0u32..=0x10ffff, 0..65)\n            .prop_map(Value::CodePointText)\n            .boxed(),\n        \"Utf16Text\" => proptest::collection::vec(any::<u16>(), 0..65)\n            .prop_map(Value::Utf16Text)\n            .boxed(),\n        \"Bytes\" => proptest::collection::vec(any::<u8>(), 0..65)\n            .prop_map(Value::Bytes)\n            .boxed(),\n        \"Symbol\" => any::<u64>()\n            .prop_map(|id| Value::Symbol(ls::Symbol::new(format!(\"symbol-{id}\"))))\n            .boxed(),\n        \"Unit\" => Just(Value::Unit).boxed(),\n        \"Null\" => Just(Value::Null).boxed(),\n        \"Undefined\" => Just(Value::Undefined).boxed(),\n        _ => return Err(format!(\"no Rust generator for {name}\")),\n    })\n}\nfn bigint() -> BoxedStrategy<ls::BigInt> {\n    (any::<bool>(), proptest::collection::vec(any::<u8>(), 0..65))\n        .prop_map(|(negative, bytes)| {\n            ls::BigInt::from_bytes_le(\n                if negative {\n                    num_bigint::Sign::Minus\n                } else {\n                    num_bigint::Sign::Plus\n                },\n                &bytes,\n            )\n        })\n        .boxed()\n}\npub fn tuple(types: &[&str]) -> ls::Result<BoxedStrategy<Vec<Value>>> {\n    let mut result = Just(Vec::new()).boxed();\n    for name in types {\n        result = (result, strategy(name)?)\n            .prop_map(|(mut xs, x)| {\n                xs.push(x);\n                xs\n            })\n            .boxed();\n    }\n    Ok(result)\n}\n\n/// Construct the affine integer domain after preceding inputs are known.\n/// An empty continuation returns None so the native flat-map/filter combination\n/// retries the preceding inputs and recomputes the domain during shrinking.\npub fn bounded_integer(\n    name: &str,\n    bounds: Vec<(&str, Value)>,\n    machine_bits: u32,\n) -> ls::Result<Option<BoxedStrategy<Value>>> {\n    use num_traits::{One, Signed, Zero};\n    let width = match name {\n        \"Int8\" | \"UInt8\" => Some(8),\n        \"Int16\" | \"UInt16\" => Some(16),\n        \"Int32\" | \"UInt32\" => Some(32),\n        \"Int64\" | \"UInt64\" => Some(64),\n        \"IntSize\" | \"UIntSize\" | \"UIntPtr\" => Some(machine_bits),\n        _ => None,\n    };\n    let unsigned = name.starts_with(\"UInt\") || name == \"BigUInt\";\n    let mut lo = if unsigned {\n        Some(ls::BigInt::zero())\n    } else {\n        width.map(|w| -(ls::BigInt::one() << (w - 1)))\n    };\n    let mut hi = width.map(|w| (ls::BigInt::one() << (if unsigned { w } else { w - 1 })) - 1u8);\n    for (op, value) in bounds {\n        let r = value.exact()?;\n        let floor = r.floor().to_integer();\n        let ceil = r.ceil().to_integer();\n        let (lower, upper) = match op {\n            \">\" => (Some(floor + 1u8), None),\n            \">=\" => (Some(ceil), None),\n            \"<\" => (None, Some(ceil - 1u8)),\n            \"<=\" => (None, Some(floor)),\n            \"==\" => {\n                if !r.is_integer() {\n                    return Ok(None);\n                }\n                let n = r.to_integer();\n                (Some(n.clone()), Some(n))\n            }\n            _ => return Err(\"invalid planned integer bound\".into()),\n        };\n        if let Some(n) = lower {\n            lo = Some(lo.map_or(n.clone(), |old| old.max(n)));\n        }\n        if let Some(n) = upper {\n            hi = Some(hi.map_or(n.clone(), |old| old.min(n)));\n        }\n    }\n    let span = ls::BigInt::one() << 512usize;\n    let lower = lo.unwrap_or_else(|| hi.as_ref().map_or(-&span, |upper| upper - &span));\n    let upper = hi.unwrap_or_else(|| &lower + &span);\n    if lower > upper {\n        return Ok(None);\n    }\n    let count = &upper - &lower + 1u8;\n    let offset = lower.clone();\n    Ok(Some(\n        prop_oneof![\n            Just(Value::Integer(lower)),\n            Just(Value::Integer(upper)),\n            bigint().prop_map(move |n| Value::Integer(&offset + n.abs() % &count))\n        ]\n        .boxed(),\n    ))\n}\n\npub fn strategy_with_profile(name: &str, bits: u32) -> ls::Result<BoxedStrategy<Value>> {\n    if let Some(inner) = name.strip_prefix(\"List \") {\n        return Ok(\n            proptest::collection::vec(strategy_with_profile(inner, bits)?, 0..65)\n                .prop_map(Value::List)\n                .boxed(),\n        );\n    }\n    if let Some(inner) = name.strip_prefix(\"Maybe \") {\n        return Ok(proptest::option::of(strategy_with_profile(inner, bits)?)\n            .prop_map(|x| Value::Maybe(x.map(Box::new)))\n            .boxed());\n    }\n    if let Some(arguments) = name.strip_prefix(\"Either \") {\n        let (left, right) = ls::either_types(arguments)?;\n        return Ok(prop_oneof![\n            strategy_with_profile(left, bits)?.prop_map(|x| Value::Left(Box::new(x))),\n            strategy_with_profile(right, bits)?.prop_map(|x| Value::Right(Box::new(x)))\n        ]\n        .boxed());\n    }\n    if let Some(inner) = name.strip_prefix(\"Nullable \") {\n        return Ok(proptest::option::of(strategy_with_profile(inner, bits)?)\n            .prop_map(|x| Value::Nullable(x.map(Box::new)))\n            .boxed());\n    }\n    if let Some(inner) = name.strip_prefix(\"Optional \") {\n        return Ok(proptest::option::of(strategy_with_profile(inner, bits)?)\n            .prop_map(|x| Value::Optional(x.map(Box::new)))\n            .boxed());\n    }\n    scalar_strategy(match (name, bits) {\n        (\"IntSize\", 32) => \"Int32\",\n        (\"IntSize\", 64) => \"Int64\",\n        (\"UIntSize\" | \"UIntPtr\", 32) => \"UInt32\",\n        (\"UIntSize\" | \"UIntPtr\", 64) => \"UInt64\",\n        _ => name,\n    })\n}\n\n#[derive(Clone, Debug, Default)]\npub struct Case {\n    pub context: ls::Context,\n    pub values: Vec<Value>,\n    pub error: Option<String>,\n}\npub fn seeded(strategy: BoxedStrategy<Value>, seeds: Vec<Value>) -> BoxedStrategy<Value> {\n    if seeds.is_empty() {\n        strategy\n    } else {\n        prop_oneof![strategy, proptest::sample::select(seeds)].boxed()\n    }\n}\n\n/// Compose native proptest generators from instantiated Core data schemas.\n/// The structural budget limits samples, not the mathematical input domain.\n/// Memoization shares strategies for repeated fields in recursive products.\npub fn schema_strategy(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n) -> ls::Result<BoxedStrategy<Value>> {\n    if schema.has_contracts() {\n        return Err(\n            \"constructor contracts require checked_schema_strategy and a Symbol context\".into(),\n        );\n    }\n    shape_strategy(schema, ty, bits, budget, Default::default())\n}\n\ntype Witnesses = std::collections::HashMap<ls::TypeRef, Vec<Value>>;\n\nfn value_cost(value: &Value) -> usize {\n    match value {\n        Value::Data(_, fields) | Value::List(fields) => {\n            1 + fields.iter().map(value_cost).sum::<usize>()\n        }\n        Value::Maybe(Some(value))\n        | Value::Nullable(Some(value))\n        | Value::Optional(Some(value))\n        | Value::Left(value)\n        | Value::Right(value) => 1 + value_cost(value),\n        _ => 1,\n    }\n}\n\n// Witnesses are validated before traversal. Keep their instantiated types so a\n// Symbol seed cannot leak into unrelated fields with the same representation.\nfn collect_witnesses(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    value: &Value,\n    seeds: &mut Witnesses,\n) -> ls::Result<()> {\n    // Builtin containers must use their native structural generators so a\n    // witness list can still shrink its length. Seed payloads recursively;\n    // retain named values as fallbacks for uneven recursive node allocations.\n    if !matches!(\n        value,\n        Value::List(_)\n            | Value::Maybe(_)\n            | Value::Nullable(_)\n            | Value::Optional(_)\n            | Value::Left(_)\n            | Value::Right(_)\n    ) {\n        seeds.entry(ty.clone()).or_default().push(value.clone());\n    }\n    if let Some(constructors) = schema.constructor_fields(ty)? {\n        let Value::Data(tag, fields) = value else {\n            return Err(\"invalid data witness\".into());\n        };\n        let constructor = constructors\n            .iter()\n            .find(|c| c.tag == tag)\n            .ok_or(\"unknown witness constructor\")?;\n        for (field_type, field) in constructor.fields.iter().zip(fields) {\n            collect_witnesses(schema, field_type, field, seeds)?;\n        }\n    } else if let ls::TypeRef::Named(_, arguments) = ty {\n        match value {\n            Value::List(values) => {\n                for value in values {\n                    collect_witnesses(schema, &arguments[0], value, seeds)?;\n                }\n            }\n            Value::Maybe(Some(value))\n            | Value::Nullable(Some(value))\n            | Value::Optional(Some(value))\n            | Value::Left(value) => {\n                collect_witnesses(schema, &arguments[0], value, seeds)?;\n            }\n            Value::Right(value) => collect_witnesses(schema, &arguments[1], value, seeds)?,\n            _ => {}\n        }\n    }\n    Ok(())\n}\n\n/// Reject only false predicates, across whole candidates rather than individual\n/// branches. Native proptest filtering bounds retries and preserves shrinking.\n/// Evaluation errors remain Err values that the property must report as failures.\n/// Context clones preserve Symbol identity without mutating it during shrinking.\npub fn checked_schema_strategy(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    context: &ls::Context,\n    witnesses: Vec<Value>,\n) -> ls::Result<BoxedStrategy<ls::Result<Value>>> {\n    checked_schema_strategy_with_generators(\n        schema,\n        ty,\n        bits,\n        budget,\n        context,\n        witnesses,\n        &NativeGenerators::default(),\n    )\n}\n\npub fn checked_schema_strategy_with_generators(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    context: &ls::Context,\n    witnesses: Vec<Value>,\n    native: &NativeGenerators,\n) -> ls::Result<BoxedStrategy<ls::Result<Value>>> {\n    let mut seeds = Witnesses::new();\n    for witness in witnesses {\n        let value = schema.validate_with_context(witness, ty, bits, &mut context.clone())?;\n        if value_cost(&value) > budget {\n            return Err(\"constructor witness exceeds structural node budget\".into());\n        }\n        collect_witnesses(schema, ty, &value, &mut seeds)?;\n    }\n    let strategy =\n        shape_strategy_with_generators(schema, ty, bits, budget, seeds, context, native)?;\n    let schema = schema.clone();\n    let ty = ty.clone();\n    let context = context.clone();\n    Ok(strategy\n        .prop_filter_map(\"constructor field refinement\", move |value| {\n            match schema.check_with_context(value, &ty, bits, &mut context.clone()) {\n                Ok(ls::ValueCheck::Accepted(value)) => Some(Ok(value)),\n                Ok(ls::ValueCheck::Rejected(_)) => None,\n                Err(error) => Some(Err(error)),\n            }\n        })\n        .boxed())\n}\n\nfn shape_strategy(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    witnesses: Witnesses,\n) -> ls::Result<BoxedStrategy<Value>> {\n    shape_strategy_with_generators(\n        schema,\n        ty,\n        bits,\n        budget,\n        witnesses,\n        &ls::Context::default(),\n        &NativeGenerators::default(),\n    )\n}\n\nfn shape_strategy_with_generators(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    witnesses: Witnesses,\n    context: &ls::Context,\n    native: &NativeGenerators,\n) -> ls::Result<BoxedStrategy<Value>> {\n    type Request = (ls::TypeRef, usize);\n    struct Builder<'a> {\n        schema: &'a ls::Schema,\n        context: &'a ls::Context,\n        native: &'a NativeGenerators,\n        bits: u32,\n        witnesses: Witnesses,\n        inhabited: std::collections::HashMap<Request, bool>,\n        generators: std::collections::HashMap<Request, BoxedStrategy<Value>>,\n    }\n\n    impl Builder<'_> {\n        fn can_generate(&mut self, ty: &ls::TypeRef, budget: usize) -> ls::Result<bool> {\n            if budget == 0 {\n                return Ok(false);\n            }\n            let key = (ty.clone(), budget);\n            if let Some(result) = self.inhabited.get(&key) {\n                return Ok(*result);\n            }\n            let result = if self.native.factory(ty).is_some() {\n                true\n            } else if let Some(constructors) = self.schema.constructor_fields(ty)? {\n                let mut found = false;\n                for constructor in constructors {\n                    if self.allocate(&constructor.fields, budget - 1)?.is_some() {\n                        found = true;\n                        break;\n                    }\n                }\n                found\n            } else {\n                let ls::TypeRef::Named(name, arguments) = ty else {\n                    return Err(\"uninstantiated generator type\".into());\n                };\n                match (*name, arguments.as_slice()) {\n                    (\"List\" | \"Maybe\" | \"Nullable\" | \"Optional\", [_]) => true,\n                    (\"Either\", [left, right]) => {\n                        self.can_generate(left, budget - 1)?\n                            || self.can_generate(right, budget - 1)?\n                    }\n                    (_, []) => true,\n                    _ => return Err(format!(\"unsupported generator type: {ty:?}\")),\n                }\n            };\n            self.inhabited.insert(key, result);\n            Ok(result)\n        }\n\n        fn minimum(&mut self, ty: &ls::TypeRef, limit: usize) -> ls::Result<Option<usize>> {\n            for cost in 1..=limit {\n                if self.can_generate(ty, cost)? {\n                    return Ok(Some(cost));\n                }\n            }\n            Ok(None)\n        }\n\n        // Reserve every field's minimum before sharing the remaining nodes.\n        // A deep field must not disappear merely because its siblings are small.\n        fn allocate(\n            &mut self,\n            fields: &[ls::TypeRef],\n            budget: usize,\n        ) -> ls::Result<Option<Vec<usize>>> {\n            let mut remaining = budget;\n            let mut costs = Vec::new();\n            for field in fields {\n                let Some(cost) = self.minimum(field, remaining)? else {\n                    return Ok(None);\n                };\n                costs.push(cost);\n                remaining -= cost;\n            }\n            let count = costs.len();\n            for (index, cost) in costs.iter_mut().enumerate() {\n                *cost += remaining / count + usize::from(index < remaining % count);\n            }\n            Ok(Some(costs))\n        }\n\n        fn generate(\n            &mut self,\n            ty: &ls::TypeRef,\n            budget: usize,\n        ) -> ls::Result<BoxedStrategy<Value>> {\n            if !self.can_generate(ty, budget)? {\n                return Err(format!(\n                    \"no value within structural node budget {budget}: {ty:?}\"\n                ));\n            }\n            let key = (ty.clone(), budget);\n            if let Some(cached) = self.generators.get(&key) {\n                return Ok(cached.clone());\n            }\n            let result = if let Some(factory) = self.native.factory(ty) {\n                let ls::TypeRef::Named(_, arguments) = ty else {\n                    return Err(\"uninstantiated native generator type\".into());\n                };\n                let mut children = Vec::new();\n                for argument in arguments {\n                    let remaining = budget.saturating_sub(1).max(1);\n                    let child = if self.can_generate(argument, remaining)? {\n                        self.generate(argument, remaining)?\n                    } else {\n                        // Phantom parameters may be uninhabited. Keep a native\n                        // strategy argument that rejects if actually sampled.\n                        Just(Value::Unit)\n                            .prop_filter(\n                                format!(\"no native generator argument within node budget {remaining}: {argument:?}\"),\n                                |_| false,\n                            )\n                            .boxed()\n                    };\n                    children.push(child);\n                }\n                let strategy = factory(self.schema, ty, self.bits, self.context, children)?;\n                let schema = self.schema.clone();\n                let ty = ty.clone();\n                let bits = self.bits;\n                let context = self.context.clone();\n                strategy\n                    .prop_map(move |value| {\n                        schema\n                            .validate_with_context(value, &ty, bits, &mut context.clone())\n                            .unwrap_or_else(|error| panic!(\"native generator {ty:?}: {error}\"))\n                    })\n                    .boxed()\n            } else if let Some(constructors) = self.schema.constructor_fields(ty)? {\n                let mut alternatives = Vec::new();\n                for constructor in constructors {\n                    let Some(costs) = self.allocate(&constructor.fields, budget - 1)? else {\n                        continue;\n                    };\n                    let mut fields = Just(Vec::<Value>::new()).boxed();\n                    for (field, cost) in constructor.fields.iter().zip(costs) {\n                        let next = self.generate(field, cost)?;\n                        fields = (fields, next)\n                            .prop_map(|(mut values, value)| {\n                                values.push(value);\n                                values\n                            })\n                            .boxed();\n                    }\n                    alternatives.push(\n                        fields\n                            .prop_map(move |fields| ls::construct_data(constructor.tag, fields))\n                            .boxed(),\n                    );\n                }\n                proptest::strategy::Union::new(alternatives).boxed()\n            } else {\n                let ls::TypeRef::Named(name, arguments) = ty else {\n                    return Err(\"uninstantiated generator type\".into());\n                };\n                match (*name, arguments.as_slice()) {\n                    (\"List\", [element]) => {\n                        let remaining = budget - 1;\n                        let maximum = self\n                            .minimum(element, remaining)?\n                            .map_or(0, |cost| remaining / cost);\n                        let mut lengths = vec![Just(Value::List(vec![])).boxed()];\n                        for length in 1..=maximum {\n                            let elements = self.generate(element, remaining / length)?;\n                            lengths.push(\n                                proptest::collection::vec(elements, length..=length)\n                                    .prop_map(Value::List)\n                                    .boxed(),\n                            );\n                        }\n                        // Native dependent shrinking changes length and then\n                        // shrinks elements under the recomputed size bound.\n                        (0..=maximum)\n                            .prop_flat_map(move |length| lengths[length].clone())\n                            .boxed()\n                    }\n                    (\"Maybe\" | \"Nullable\" | \"Optional\", [element]) => {\n                        let values = if self.can_generate(element, budget - 1)? {\n                            proptest::option::of(self.generate(element, budget - 1)?).boxed()\n                        } else {\n                            Just(None).boxed()\n                        };\n                        let name = *name;\n                        values\n                            .prop_map(move |value| match name {\n                                \"Maybe\" => Value::Maybe(value.map(Box::new)),\n                                \"Nullable\" => Value::Nullable(value.map(Box::new)),\n                                _ => Value::Optional(value.map(Box::new)),\n                            })\n                            .boxed()\n                    }\n                    (\"Either\", [left, right]) => {\n                        let mut alternatives = Vec::new();\n                        if self.can_generate(left, budget - 1)? {\n                            alternatives.push(\n                                self.generate(left, budget - 1)?\n                                    .prop_map(|value| Value::Left(Box::new(value)))\n                                    .boxed(),\n                            );\n                        }\n                        if self.can_generate(right, budget - 1)? {\n                            alternatives.push(\n                                self.generate(right, budget - 1)?\n                                    .prop_map(|value| Value::Right(Box::new(value)))\n                                    .boxed(),\n                            );\n                        }\n                        proptest::strategy::Union::new(alternatives).boxed()\n                    }\n                    (_, []) => strategy_with_profile(name, self.bits)?,\n                    _ => return Err(format!(\"unsupported generator type: {ty:?}\")),\n                }\n            };\n            let seeds = self\n                .witnesses\n                .get(ty)\n                .into_iter()\n                .flatten()\n                .filter(|value| value_cost(value) <= budget)\n                .cloned()\n                .collect();\n            let result = if self.native.factory(ty).is_some() {\n                result\n            } else {\n                seeded(result, seeds)\n            };\n            self.generators.insert(key, result.clone());\n            Ok(result)\n        }\n    }\n\n    if !matches!(bits, 32 | 64) {\n        return Err(\"machineBits must be 32 or 64\".into());\n    }\n    Builder {\n        schema,\n        context,\n        native,\n        bits,\n        witnesses,\n        inhabited: Default::default(),\n        generators: Default::default(),\n    }\n    .generate(ty, budget)\n}\n"
runtimeSource "kotlin-strategies" = "package lawspec.testing\n\nimport io.kotest.property.Arb\nimport io.kotest.property.RTree\nimport io.kotest.property.RandomSource\nimport io.kotest.property.Sample\nimport io.kotest.property.arbitrary.list\nimport io.kotest.property.arbitrary.merge\n\n/** Kotest's merge preserves branch samples; choice in 5.9 keeps only values. */\nfun <A> lawspecChoice(first: Arb<A>, second: Arb<A>): Arb<A> = first.merge(second)\n\n/** Composes Kotest's list shrink tree with the native trees of its elements. */\nfun <A> lawspecList(element: Arb<A>, range: IntRange): Arb<List<A>> {\n    // Kotest 5.9's list generator keeps structural shrinking but discards element\n    // samples. Retain those samples as the list payload and compose both trees.\n    val sampledElements = object : Arb<Sample<A>>() {\n        // Arb.edgecase returns only a value, so it cannot preserve a shrink tree.\n        // LawSpec emits element boundary cases separately from random properties.\n        override fun edgecase(rs: RandomSource): Sample<A>? = null\n\n        override fun sample(rs: RandomSource): Sample<Sample<A>> = Sample(element.sample(rs))\n    }\n    val lists = Arb.list(sampledElements, range)\n    return object : Arb<List<A>>() {\n        override fun edgecase(rs: RandomSource): List<A>? =\n          lists.edgecase(rs)?.map { it.value }\n\n        override fun sample(rs: RandomSource): Sample<List<A>> {\n            val tree = composeListTree(lists.sample(rs).shrinks)\n            return Sample(tree.value(), tree)\n        }\n    }\n}\n\nprivate fun <A> composeListTree(source: RTree<List<Sample<A>>>): RTree<List<A>> =\n  RTree(\n      { source.value().map { it.value } },\n      lazy {\n          source.children.value.map { composeListTree(it) } +\n            source.value().flatMap { sample ->\n                sample.shrinks.children.value.map { child ->\n                    composeListTree(replaceSample(source, sample, Sample(child.value(), child)))\n                }\n            }\n      },\n  )\n\nprivate fun <A> replaceSample(\n    source: RTree<List<Sample<A>>>,\n    original: Sample<A>,\n    replacement: Sample<A>,\n): RTree<List<Sample<A>>> =\n  RTree(\n      { source.value().map { if (it === original) replacement else it } },\n      lazy { source.children.value.map { replaceSample(it, original, replacement) } },\n  )\n\n/** Preserve both native shrink trees when a later arbitrary depends on a value.\n *\n * Kotest 5.9's flatMap passes only Sample.value to its continuation. Keep the\n * source tree as well, so list lengths and constructor choices can still shrink.\n */\nfun <A, B> lawspecFlatMap(source: Arb<A>, next: (A) -> Arb<B>): Arb<B> =\n  object : Arb<B>() {\n      override fun edgecase(rs: RandomSource): B? = null\n\n      override fun sample(rs: RandomSource): Sample<B> {\n          val sourceTree = source.sample(rs).shrinks\n          val seed = rs.random.nextLong()\n          fun draw(tree: RTree<A>): RTree<B> =\n            next(tree.value()).sample(RandomSource.seeded(seed)).shrinks\n\n          fun compose(sourceNode: RTree<A>, result: RTree<B>): RTree<B> =\n            RTree(\n                { result.value() },\n                lazy {\n                    sourceNode.children.value.map { compose(it, draw(it)) } +\n                      result.children.value.map { compose(sourceNode, it) }\n                },\n            )\n\n          val tree = compose(sourceTree, draw(sourceTree))\n          return Sample(tree.value(), tree)\n      }\n  }\n"
runtimeSource "kotlin-native" = "package lawspec.runtime\n\n/** Native support types whose domains differ from Kotlin's built-in types. */\nobject LawSpecKotlin {\n    sealed interface Nullable<T> {\n        class Null<T> : Nullable<T>\n\n        class Present<T>(val value: T) : Nullable<T>\n    }\n\n    sealed interface Optional<T> {\n        class Undefined<T> : Optional<T>\n\n        class Present<T>(val value: T) : Optional<T>\n    }\n\n    object Null\n\n    object Undefined\n\n    /** Equality follows the fixture identity, even after a checked round trip. */\n    class Symbol internal constructor(internal val token: LawSpecRuntime.SymbolValue) {\n        constructor(description: String) : this(LawSpecRuntime.SymbolValue(description))\n\n        val description: String\n            get() = token.description()\n\n        override fun equals(other: Any?): Boolean = other is Symbol && token === other.token\n\n        override fun hashCode(): Int = System.identityHashCode(token)\n    }\n}\n"
runtimeSource "kotlin-codecs" = "package lawspec.runtime\n\nimport lawspec.runtime.LawSpecKotlin as Native\nimport lawspec.runtime.LawSpecRuntime as Runtime\nimport lawspec.runtime.LawSpecSchema.Codec\nimport lawspec.runtime.LawSpecSchema.Named\n\n/** Framework-independent bridges for Kotlin-specific native representations. */\nobject LawSpecKotlinCodecs {\n    fun construct(\n        schema: LawSpecSchema,\n        type: Named,\n        tag: String,\n        fields: List<Runtime.Value>,\n        bits: Int,\n        symbols: MutableMap<String, Any> = mutableMapOf(),\n    ): Runtime.Value {\n        if (type.name() != \"List\") return schema.construct(type, tag, fields, bits, symbols)\n        val values = when {\n            tag == \"List::Nil\" && fields.isEmpty() -> emptyList()\n            tag == \"List::Cons\" && fields.size == 2 -> {\n                val tail = schema.validate(type, fields[1], bits, symbols).data() as List<*>\n                listOf(fields[0]) + tail.map { it as Runtime.Value }\n            }\n            else -> throw IllegalArgumentException(\"invalid List constructor or field count\")\n        }\n        return schema.validate(type, Runtime.Value(LawSpecSchema.key(type), values), bits, symbols)\n    }\n\n    fun match(\n        schema: LawSpecSchema,\n        type: Named,\n        value: Runtime.Value,\n        bits: Int,\n        branch: (String, List<Runtime.Value>) -> Runtime.Value,\n    ): Runtime.Value = match(schema, type, value, bits, mutableMapOf(), branch)\n\n    fun match(\n        schema: LawSpecSchema,\n        type: Named,\n        value: Runtime.Value,\n        bits: Int,\n        symbols: MutableMap<String, Any>,\n        branch: (String, List<Runtime.Value>) -> Runtime.Value,\n    ): Runtime.Value {\n        val checked = schema.validate(type, value, bits, symbols)\n        if (type.name() == \"List\") {\n            val values = (checked.data() as List<*>).map { it as Runtime.Value }\n            return if (values.isEmpty()) {\n                branch(\"List::Nil\", emptyList())\n            } else {\n                branch(\n                    \"List::Cons\",\n                    listOf(values[0], Runtime.Value(checked.type(), values.drop(1))),\n                )\n            }\n        }\n        val data = checked.data() as Runtime.Data\n        return branch(data.tag(), data.fields())\n    }\n\n    fun unit(schema: LawSpecSchema, bits: Int): Codec<Unit> =\n      schema.codec(Named(\"Unit\"), bits, { Runtime.absent(\"Unit\") }, { })\n\n    fun nullValue(schema: LawSpecSchema, bits: Int): Codec<Native.Null> =\n      schema.codec(Named(\"Null\"), bits, { Runtime.absent(\"Null\") }, { Native.Null })\n\n    fun undefined(schema: LawSpecSchema, bits: Int): Codec<Native.Undefined> =\n      schema.codec(\n          Named(\"Undefined\"), bits, { Runtime.absent(\"Undefined\") }, { Native.Undefined },\n      )\n\n    fun symbol(schema: LawSpecSchema, bits: Int): Codec<Native.Symbol> =\n      schema.codec(\n          Named(\"Symbol\"),\n          bits,\n          { Runtime.Value(\"Symbol\", it.token) },\n          { Native.Symbol(it.data() as Runtime.SymbolValue) },\n      )\n\n    fun codePointText(schema: LawSpecSchema, bits: Int): Codec<IntArray> =\n      schema.codec(\n          Named(\"CodePointText\"),\n          bits,\n          { Runtime.sequence(\"CodePointText\", it) },\n          { value -> (value.data() as List<*>).map { it as Int }.toIntArray() },\n      )\n\n    fun <T> nullable(\n        schema: LawSpecSchema,\n        bits: Int,\n        element: Codec<T>,\n        symbols: MutableMap<String, Any> = mutableMapOf(),\n    ): Codec<Native.Nullable<T>> {\n        val type = Named(\"Nullable\", element.type())\n        return schema.codec(\n            type,\n            bits,\n            symbols,\n            { value ->\n                val payload = when (value) {\n                    is Native.Nullable.Null -> Runtime.Presence(false, null)\n                    is Native.Nullable.Present -> {\n                        Runtime.Presence(\n                            true, LawSpecSchema.encodeField(element, value.value, \"present\"),\n                        )\n                    }\n                }\n                Runtime.Value(LawSpecSchema.key(type), payload)\n            },\n            { value ->\n                val payload = value.data() as Runtime.Presence\n                if (payload.present()) {\n                    Native.Nullable.Present(element.decode(payload.value()))\n                } else {\n                    Native.Nullable.Null()\n                }\n            },\n        )\n    }\n\n    fun <T> optional(\n        schema: LawSpecSchema,\n        bits: Int,\n        element: Codec<T>,\n        symbols: MutableMap<String, Any> = mutableMapOf(),\n    ): Codec<Native.Optional<T>> {\n        val type = Named(\"Optional\", element.type())\n        return schema.codec(\n            type,\n            bits,\n            symbols,\n            { value ->\n                val payload = when (value) {\n                    is Native.Optional.Undefined -> Runtime.Presence(false, null)\n                    is Native.Optional.Present -> {\n                        Runtime.Presence(\n                            true, LawSpecSchema.encodeField(element, value.value, \"present\"),\n                        )\n                    }\n                }\n                Runtime.Value(LawSpecSchema.key(type), payload)\n            },\n            { value ->\n                val payload = value.data() as Runtime.Presence\n                if (payload.present()) {\n                    Native.Optional.Present(element.decode(payload.value()))\n                } else {\n                    Native.Optional.Undefined()\n                }\n            },\n        )\n    }\n}\n"
runtimeSource "kotlin-data-strategies" = "package lawspec.testing\n\nimport io.kotest.property.Arb\nimport io.kotest.property.RTree\nimport io.kotest.property.RandomSource\nimport io.kotest.property.Sample\nimport io.kotest.property.arbitrary.bind\nimport io.kotest.property.arbitrary.constant\nimport io.kotest.property.arbitrary.int\nimport io.kotest.property.arbitrary.map\nimport io.kotest.property.filter\nimport lawspec.runtime.LawSpecRuntime.Data\nimport lawspec.runtime.LawSpecRuntime.Presence\nimport lawspec.runtime.LawSpecRuntime.Value\nimport lawspec.runtime.LawSpecSchema\nimport lawspec.runtime.LawSpecSchema.Named\n\n/** Native Kotest generation and shrinking for instantiated Core data schemas. */\nobject LawSpecKotlinStrategies {\n    fun generator(\n        schema: LawSpecSchema,\n        type: Named,\n        bits: Int,\n        budget: Int,\n        scalar: (String) -> Arb<Value>,\n    ): Arb<Value> {\n        require(!schema.hasContracts()) { \"constructor contracts require checked generation\" }\n        require(budget > 0) { \"structural node budget must be positive\" }\n        require(bits == 32 || bits == 64) { \"machineBits must be 32 or 64\" }\n        schema.isScalar(type) // Validate the entire type application before planning.\n        return requireNotNull(Builder(schema, bits, scalar).build(type, budget)) {\n            \"no value of ${LawSpecSchema.key(type)} within structural node budget $budget\"\n        }\n    }\n\n    data class Case(\n        val values: List<Value>,\n        val symbols: MutableMap<String, Any>,\n        val error: RuntimeException? = null,\n    ) {\n        fun requireValues(): List<Value> {\n            error?.let { throw it }\n            return values\n        }\n    }\n\n    fun cases(): Arb<Case> = object : Arb<Case>() {\n        override fun edgecase(rs: RandomSource): Case? = null\n\n        override fun sample(rs: RandomSource): Sample<Case> =\n            Sample(Case(emptyList(), mutableMapOf()))\n    }\n\n    fun filterCases(source: Arb<Case>, attempts: Int, predicate: (Case) -> Boolean): Arb<Case> {\n        require(attempts > 0) { \"maxAttempts must be positive\" }\n        return bounded(source, attempts, \"property inputs\") { it.error != null || predicate(it) }\n    }\n\n    data class Checked(val value: Value?, val error: RuntimeException?) {\n        fun requireValue(): Value {\n            error?.let { throw it }\n            return requireNotNull(value)\n        }\n    }\n\n    fun interface NativeFactory {\n        fun create(\n            schema: LawSpecSchema,\n            type: Named,\n            bits: Int,\n            symbols: MutableMap<String, Any>,\n            arguments: List<Arb<Value>>,\n        ): Arb<Value>\n    }\n\n    private class NativeFailure(type: Named, cause: RuntimeException) :\n        IllegalArgumentException(\n            \"native generator ${LawSpecSchema.key(type)}: ${cause.message}\", cause,\n        )\n\n    fun <T> nativeValues(codec: LawSpecSchema.Codec<T>, source: Arb<T>): Arb<Value> =\n        source.map { value ->\n            try {\n                codec.encode(value)\n            } catch (error: RuntimeException) {\n                throw NativeFailure(codec.type(), error)\n            }\n        }\n\n    fun <T> nativeArguments(codec: LawSpecSchema.Codec<T>, source: Arb<Value>): Arb<T> =\n        source.map { value ->\n            try {\n                codec.decode(value)\n            } catch (error: RuntimeException) {\n                throw NativeFailure(codec.type(), error)\n            }\n        }\n\n    // Retain the native tree, including failures encountered while evaluating a\n    // shrink node or enumerating its children. Report those in property callbacks.\n    private fun capture(source: Arb<Checked>): Arb<Checked> = object : Arb<Checked>() {\n        override fun edgecase(rs: RandomSource): Checked? = null\n\n        fun failure(error: NativeFailure) = RTree({ Checked(null, error) })\n\n        fun tree(source: RTree<Checked>): RTree<Checked> {\n            val value = try {\n                source.value()\n            } catch (error: NativeFailure) {\n                return failure(error)\n            }\n            return RTree({ value }, lazy {\n                try {\n                    source.children.value.map(::tree)\n                } catch (error: NativeFailure) {\n                    listOf(failure(error))\n                }\n            })\n        }\n\n        override fun sample(rs: RandomSource): Sample<Checked> {\n            val result = try {\n                tree(source.sample(rs).shrinks)\n            } catch (error: NativeFailure) {\n                failure(error)\n            }\n            return Sample(result.value(), result)\n        }\n    }\n\n    fun checkedGenerator(\n        schema: LawSpecSchema,\n        type: Named,\n        bits: Int,\n        budget: Int,\n        maxAttempts: Int,\n        symbols: MutableMap<String, Any>,\n        witnesses: List<Value>,\n        scalar: (String) -> Arb<Value>,\n    ): Arb<Checked> = checkedGenerator(\n        schema, type, bits, budget, maxAttempts, symbols, witnesses, emptyMap(), scalar,\n    )\n\n    fun checkedGenerator(\n        schema: LawSpecSchema,\n        type: Named,\n        bits: Int,\n        budget: Int,\n        maxAttempts: Int,\n        symbols: MutableMap<String, Any>,\n        witnesses: List<Value>,\n        factories: Map<String, NativeFactory>,\n        scalar: (String) -> Arb<Value>,\n    ): Arb<Checked> {\n        require(budget > 0) { \"structural node budget must be positive\" }\n        require(bits == 32 || bits == 64) { \"machineBits must be 32 or 64\" }\n        require(maxAttempts > 0) { \"maxAttempts must be positive\" }\n        schema.isScalar(type)\n        val builder = Builder(schema, bits, scalar, symbols, maxAttempts, factories)\n        witnesses.forEach { builder.addWitness(type, schema.validate(type, it, bits, symbols)) }\n        val source = requireNotNull(builder.build(type, budget)) {\n            \"no value of ${LawSpecSchema.key(type)} within structural node budget $budget\"\n        }\n        return capture(source.map { value ->\n            try {\n                Checked(schema.validate(type, value, bits, symbols), null)\n            } catch (error: RuntimeException) {\n                Checked(null, error)\n            }\n        })\n    }\n\n    private fun nodes(value: Value): Int = 1 + when (val data = value.data()) {\n        is Data -> data.fields().sumOf(::nodes)\n        is Presence -> if (data.present()) nodes(data.value()) else 0\n        is List<*> -> {\n            if (value.type().startsWith(\"List \")) {\n                data.sumOf { nodes(it as Value) }\n            } else {\n                0\n            }\n        }\n        else -> 0\n    }\n\n    private fun <T> bounded(\n        source: Arb<T>,\n        attempts: Int,\n        label: String,\n        accepted: (T) -> Boolean,\n    ): Arb<T> = object : Arb<T>() {\n        override fun edgecase(rs: RandomSource): T? = null\n\n        override fun sample(rs: RandomSource): Sample<T> {\n            repeat(attempts) {\n                val sample = source.sample(rs)\n                val tree = sample.shrinks.filter(accepted)\n                if (tree != null) return Sample(tree.value(), tree)\n            }\n            throw IllegalArgumentException(\n                \"constructor generation exhausted $attempts attempts for $label\",\n            )\n        }\n    }\n\n    private data class Request(val type: Named, val budget: Int)\n\n    private class Builder(\n        val schema: LawSpecSchema,\n        val bits: Int,\n        val scalar: (String) -> Arb<Value>,\n        val symbols: MutableMap<String, Any>? = null,\n        val maxAttempts: Int = 100,\n        val factories: Map<String, NativeFactory> = emptyMap(),\n    ) {\n        val witnesses = mutableMapOf<Named, MutableList<Value>>()\n        val cache = mutableMapOf<Request, Arb<Value>?>()\n\n        fun addWitness(type: Named, value: Value) {\n            witnesses.getOrPut(type) { mutableListOf() }.add(value)\n            when {\n                schema.isScalar(type) -> Unit\n                type.name() == \"List\" -> {\n                    (value.data() as List<*>).forEach {\n                        addWitness(type.arguments()[0] as Named, it as Value)\n                    }\n                }\n                type.name() in listOf(\"Nullable\", \"Optional\") -> {\n                    val presence = value.data() as Presence\n                    if (presence.present()) {\n                        addWitness(type.arguments()[0] as Named, presence.value())\n                    }\n                }\n                else -> {\n                    val data = value.data() as Data\n                    schema.fields(type, data.tag()).forEachIndexed { index, field ->\n                        addWitness(field.type() as Named, data.fields()[index])\n                    }\n                }\n            }\n        }\n\n        fun minimum(type: Named, limit: Int): Int? =\n          (1..limit).firstOrNull { build(type, it) != null }\n\n        fun allocation(fields: List<LawSpecSchema.Field>, available: Int): List<Int>? {\n            var remaining = available\n            val minima = fields.map { field ->\n                val cost = minimum(field.type() as Named, remaining) ?: return null\n                remaining -= cost\n                cost\n            }\n            return minima.mapIndexed { index, cost ->\n                cost + remaining / minima.size + if (index < remaining % minima.size) 1 else 0\n            }\n        }\n\n        fun build(type: Named, available: Int): Arb<Value>? {\n            if (available < 1) return null\n            val request = Request(type, available)\n            if (cache.containsKey(request)) return cache[request]\n            factories[type.name()]?.let { factory ->\n                val arguments = type.arguments().map {\n                    build(it as Named, available) ?: object : Arb<Value>() {\n                        // A phantom parameter can be uninhabited. Fail only if\n                        // its factory actually asks this arbitrary for a value.\n                        override fun edgecase(rs: RandomSource): Value? = null\n                        override fun sample(rs: RandomSource): Sample<Value> =\n                            error(\"no native generator argument for ${LawSpecSchema.key(it)} within node budget $available\")\n                    }\n                }\n                val context = requireNotNull(symbols)\n                val result = factory.create(schema, type, bits, context, arguments).map { value ->\n                    try {\n                        schema.validate(type, value, bits, context)\n                    } catch (error: RuntimeException) {\n                        throw NativeFailure(type, error)\n                    }\n                }\n                cache[request] = result\n                return result\n            }\n            var result = when {\n                schema.isScalar(type) -> scalar(type.name()).map { schema.validate(type, it, bits) }\n                type.name() == \"List\" -> list(type, available)\n                type.name() in listOf(\"Nullable\", \"Optional\") -> presence(type, available)\n                else -> {\n                    choice(schema.constructors(type).mapNotNull { tag ->\n                        val fields = schema.fields(type, tag)\n                        val costs = allocation(fields, available - 1) ?: return@mapNotNull null\n                        val children = fields.mapIndexed { index, field ->\n                            requireNotNull(build(field.type() as Named, costs[index]))\n                        }\n                        val product =\n                            children.fold(Arb.constant(emptyList<Value>())) { prior, child ->\n                                Arb.bind(prior, child) { values, value -> values + value }\n                            }\n                        product.map {\n                            if (symbols == null) {\n                                schema.construct(type, tag, it, bits)\n                            } else {\n                                Value(LawSpecSchema.key(type), Data(tag, it))\n                            }\n                        }\n                    })\n                }\n            }\n            if (result != null && symbols != null) {\n                val seeds = witnesses[type].orEmpty().filter { nodes(it) <= available }\n                if (seeds.isNotEmpty()) {\n                    val sample = Arb.int(seeds.indices).map { seeds[it] }\n                    result = lawspecChoice(result, sample)\n                }\n                result = bounded(result, maxAttempts, LawSpecSchema.key(type)) { value ->\n                    try {\n                        schema.check(type, value, bits, symbols) is LawSpecSchema.Accepted\n                    } catch (error: RuntimeException) {\n                        // Keep evaluator errors for the outer checked result to report.\n                        true\n                    }\n                }\n            }\n            cache[request] = result\n            return result\n        }\n\n        fun list(type: Named, available: Int): Arb<Value> {\n            val element = type.arguments()[0] as Named\n            val remaining = available - 1\n            val cost = minimum(element, remaining)\n            val maximum = if (cost == null) 0 else remaining / cost\n            // Plan before sampling: callbacks only select immutable native arbitraries.\n            val sizes = (0..maximum).map { length ->\n                if (length == 0) {\n                    Arb.constant(Value(LawSpecSchema.key(type), emptyList<Value>()))\n                } else {\n                    lawspecList(requireNotNull(build(element, remaining / length)), length..length)\n                        .map { Value(LawSpecSchema.key(type), it) }\n                }\n            }\n            return lawspecFlatMap(Arb.int(0..maximum)) { sizes[it] }\n        }\n\n        fun presence(type: Named, available: Int): Arb<Value> {\n            val absent = Arb.constant(Value(LawSpecSchema.key(type), Presence(false, null)))\n            val child = build(type.arguments()[0] as Named, available - 1) ?: return absent\n            val present = child.map { Value(LawSpecSchema.key(type), Presence(true, it)) }\n            return requireNotNull(choice(listOf(absent, present)))\n        }\n\n        fun choice(alternatives: List<Arb<Value>>): Arb<Value>? = when (alternatives.size) {\n            0 -> null\n            1 -> alternatives[0]\n            else -> lawspecFlatMap(Arb.int(alternatives.indices)) { alternatives[it] }\n        }\n    }\n}\n"
